#[derive(Clone)]
struct CompareLane {
    id: usize,
    name: String,
    folder: String,
    files: Arc<Vec<String>>,
    /// Last complete persisted inventory generation loaded or committed for
    /// this lane. This is deliberately distinct from the per-batch UI content
    /// revision used to invalidate display/search work.
    inventory_generation: Option<u64>,
    index: usize,
    scanning: bool,
    loading_image: bool,
    loading_image_inflight: bool,
    recursive: bool,
    scan_id: u64,
    load_id: u64,
    image_error: String,
    scan_error: String,
    texture: Option<TextureHandle>,
    texture_size: Option<[usize; 2]>,
    image_path: String,
    pending_jump: String,
    pending_image_index: Option<usize>,
    selected_files: HashSet<usize>,
    selection_anchor: Option<usize>,
    action_message: String,
    media_filter: MediaFilterMode,
    /// A complete persisted generation is currently visible while this lane
    /// reconciles. Progressive batches stay off-screen until the scan proves
    /// complete, so an outage can never replace cached rows with a partial set.
    scan_using_cached_inventory: bool,
}

#[derive(Clone)]
struct MediaTabRuntimeInventory {
    files: Arc<Vec<String>>,
    inventory_generation: Option<u64>,
    /// Last display order published for this tab, as source indices into
    /// `files`. Re-published on activation so the grid paints in the same frame
    /// instead of showing an empty viewport until the display worker finishes
    /// its debounce, index build, and sort/rank round trip (WP-064).
    display: Arc<Vec<usize>>,
}

#[derive(Clone, Debug)]
struct PendingInlineVideoTarget {
    tab_id: String,
    path: String,
    path_key: String,
    source_index: usize,
    requested_scan_id: u64,
    checked_display_key: Option<MediaDisplayCacheKey>,
}

/// Bound on the per-tile canonical key cache (WP-069). Cleared wholesale rather
/// than evicted: it is a pure derived value, so rebuilding is cheap and correct.
const MAX_MEDIA_TILE_KEY_CACHE: usize = 200_000;
const MAX_MEDIA_TAB_RUNTIME_INVENTORIES: usize = 8;
const MAX_MEDIA_TAB_RUNTIME_ITEMS: usize = 1_000_000;

/// Interactions collected while a lane card renders, applied after the borrow
/// of the lane ends. Relative moves (`nav_delta`) broadcast to all lanes when
/// Sync is on; absolute jumps (`target_index`) always stay per-lane.
#[derive(Default)]
struct CompareLaneRenderRequest {
    browse: bool,
    scan: bool,
    nav_delta: Option<isize>,
    target_index: Option<usize>,
    open_index: Option<usize>,
    open_index_in_system: Option<usize>,
    open_path_in_system: Option<String>,
    open_file: bool,
    copy_selected: bool,
    copy_absolute_path: bool,
    copy_portable_path: bool,
    paste: bool,
    delete_selected: bool,
    /// WP-073: Shift+Delete / "Delete permanently" — same confirmation modal,
    /// permanent wording for every file regardless of root.
    delete_selected_permanent: bool,
    open_location: bool,
    open_location_index: Option<usize>,
    /// Explicit folder-navigator request for the Media tab owner. The tab
    /// implementation consumes this path by creating/selecting a tab without
    /// mutating the currently active tab's viewport state.
    open_folder_in_new_tab: Option<String>,
    select_all: bool,
    select_none: bool,
    invert_selection: bool,
    open_selected: bool,
    // Media explorer extras (WP-045); never set from Compare surfaces.
    cut_selected: bool,
    rename_selected: bool,
    new_folder: bool,
    refresh: bool,
    /// (sort setting vocab, descending) from the context sort submenu.
    sort_to: Option<(crate::media_explorer::MediaSort, bool)>,
    /// WP-074 destination-directed file operations on the canonical selection.
    move_to_folder: bool,
    copy_to_folder: bool,
    copy_into_new_folder: bool,
    /// WP-074 contact sheet of the current selection.
    toggle_sheet: bool,
    export_sheet: bool,
    /// WP-075 receiving pane: close it, or file the dragged payload into it
    /// (true = copy, false = move).
    close_receiving_pane: bool,
    drop_on_pane: Option<bool>,
    /// WP-075: a tile drag started on this display index.
    start_drag: Option<usize>,
    /// Multi-selection label mutations apply explicitly to every selected file.
    add_label: Option<String>,
    remove_label: Option<String>,
    clear_labels: bool,
    toggle_favorite: bool,
}

/// Armed, not-yet-executed delete (WP-073). Classification happened at arm
/// time; the modal only renders precomputed strings and counts, so drawing it
/// costs no filesystem work.
#[derive(Clone, Debug, PartialEq, Eq)]
struct MediaDeleteConfirm {
    lane_id: usize,
    /// Paths on roots with a Recycle Bin (restorable after confirm).
    recyclable: Vec<String>,
    /// Paths that will be PERMANENTLY deleted: network/UNC roots (no Recycle
    /// Bin exists there), or every path when `permanent_mode` is set.
    permanent: Vec<String>,
    /// Shift+Delete / explicit permanent request: everything is permanent.
    permanent_mode: bool,
}

/// A destination-directed file operation waiting on the folder picker
/// (WP-074). The canonical source paths are captured when the operator picks
/// the action, so a selection change while the picker is open cannot retarget
/// the job.
#[derive(Clone, Debug, PartialEq, Eq)]
struct MediaDestinationJob {
    lane_id: usize,
    sources: Vec<String>,
    kind: MediaDestinationKind,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MediaDestinationKind {
    Move,
    Copy,
    CopyIntoNewFolder,
}

impl MediaDestinationKind {
    fn label(self) -> &'static str {
        match self {
            Self::Move => "move",
            Self::Copy => "copy",
            Self::CopyIntoNewFolder => "copy into new folder",
        }
    }
}

/// An in-flight tile drag (WP-075). The source paths and the destination tab
/// are both pinned when the drag starts, so a selection change or a pane
/// rebind mid-drag can never redirect the drop.
#[derive(Clone, Debug, PartialEq, Eq)]
struct MediaDragPayload {
    lane_id: usize,
    sources: Vec<String>,
    /// The tab the receiving pane was bound to at drag start.
    target_tab: String,
    /// The folder that tab was showing at drag start.
    target_folder: String,
}

/// Receipt surface for the last move/copy job (WP-074). Per-file results are
/// structured fields, not a sentence in a note, so a model can prove what
/// happened (CODEX 8.3).
#[derive(Clone, Debug, Default, serde::Serialize)]
struct MediaFileOpReport {
    operation: String,
    destination: String,
    settled: bool,
    requested: usize,
    succeeded: usize,
    skipped_same_folder: usize,
    failed: Vec<(String, String)>,
    /// Source path -> final destination path for every file that moved/copied.
    results: Vec<(String, String)>,
}

/// Receipt surface for the last contact-sheet export (WP-074).
#[derive(Clone, Debug, Default, serde::Serialize)]
struct MediaSheetExport {
    settled: bool,
    requested: usize,
    rendered: usize,
    failed: usize,
    names: bool,
    output_path: String,
    error: String,
}

/// Receipt surface for the last delete job (`delete_diagnostics`). Outcomes
/// are only present once `settled` is true (CODEX 8.3: a receipt must not
/// report a value the app has not finished computing).
#[derive(Clone, Debug, Default, serde::Serialize)]
struct MediaDeleteReport {
    job_id: u64,
    lane_id: usize,
    settled: bool,
    requested: usize,
    recycled: usize,
    permanently_deleted: usize,
    skipped_folders: usize,
    failed: Vec<(String, String)>,
    /// Stable per-file outcome labels, `path -> recycled | permanently_deleted
    /// | skipped_folder | failed:<reason>`; empty until settled.
    outcomes: Vec<(String, String)>,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum MediaFilterMode {
    ImagesOnly,
    VideosOnly,
    All,
}

impl MediaFilterMode {
    fn label(self) -> &'static str {
        match self {
            Self::ImagesOnly => "Images",
            Self::VideosOnly => "Videos",
            Self::All => "All",
        }
    }

    fn short_label(self) -> &'static str {
        match self {
            Self::ImagesOnly => "img",
            Self::VideosOnly => "vid",
            Self::All => "all",
        }
    }
}

impl CompareLane {
    fn new(id: usize) -> Self {
        Self {
            id,
            name: String::new(),
            folder: String::new(),
            files: Arc::new(Vec::new()),
            inventory_generation: None,
            index: 0,
            scanning: false,
            loading_image: false,
            loading_image_inflight: false,
            recursive: true,
            scan_id: 0,
            load_id: 0,
            image_error: String::new(),
            scan_error: String::new(),
            texture: None,
            texture_size: None,
            image_path: String::new(),
            pending_jump: String::new(),
            pending_image_index: None,
            selected_files: HashSet::new(),
            selection_anchor: None,
            action_message: String::new(),
            // Facial is a media browser first: a selected folder exposes all
            // supported images and videos by default (WP-050).
            media_filter: MediaFilterMode::All,
            scan_using_cached_inventory: false,
        }
    }

    fn total(&self) -> usize {
        self.files.len()
    }
}

