enum CompareWorkEvent {
    MatchNativeSeekReady {
        command: ApiCommand,
        generation: u64,
        result: Result<
            (
                serde_json::Value,
                Arc<crate::match_video_decode::PlaybackSourcePin>,
            ),
            String,
        >,
    },
    MatchInspectionReady {
        command: ApiCommand,
        generation: u64,
        result: Result<crate::service::MatchInspectionFrame, String>,
    },
    MatchClusterReviewReady {
        command: ApiCommand,
        generation: u64,
        result: Result<serde_json::Value, String>,
    },
    MatchVideoReady {
        command: ApiCommand,
        generation: u64,
        result: Result<serde_json::Value, String>,
    },
    /// Last complete generation loaded off-thread before reconciliation.
    ScanCacheReady {
        lane_id: usize,
        scan_id: u64,
        inventory: crate::media_db::MediaInventory,
        display_order: Arc<Vec<usize>>,
        load_ms: u64,
    },
    ScanRootReady {
        lane_id: usize,
        scan_id: u64,
        identity: crate::media_io::RootIdentity,
    },
    /// Progressive scan batch: lets the Media front paint thumbnails before
    /// a huge recursive walk and final sort have completed (WP-050).
    ScanBatch {
        lane_id: usize,
        scan_id: u64,
        files: Vec<String>,
    },
    ScanDone {
        lane_id: usize,
        scan_id: u64,
        files: Vec<String>,
        display_order: Arc<Vec<usize>>,
        dir_errors: usize,
        elapsed_ms: u64,
        first_batch_ms: Option<u64>,
        batch_count: usize,
        first_batch_items: Option<usize>,
        inventory_generation: Option<u64>,
        inventory_write_ms: Option<u64>,
        inventory_error: Option<String>,
    },
    ScanError {
        lane_id: usize,
        scan_id: u64,
        error: String,
        elapsed_ms: u64,
        inventory_error: Option<String>,
    },
    ImageDone {
        lane_id: usize,
        load_id: u64,
        path: String,
        width: usize,
        height: usize,
        pixels: Vec<u8>,
    },
    ImageError {
        lane_id: usize,
        load_id: u64,
        path: String,
        error: String,
    },
    MediaMoveDone {
        lane_id: usize,
        destination: String,
        sources: Vec<String>,
        moved: Vec<PathBuf>,
        failures: Vec<(String, String)>,
    },
    /// Confirmed delete finished off-thread (WP-073). Outcomes come from the
    /// executed branch per file — never inferred from the request.
    MediaDeleteDone {
        lane_id: usize,
        job_id: u64,
        outcomes: Vec<(String, crate::media_fs::DeleteOutcome)>,
    },
    /// Destination-directed copy finished off-thread (WP-074). Sources are
    /// untouched, so only the destination side needs reporting.
    MediaCopyDone {
        lane_id: usize,
        destination: String,
        copied: Vec<PathBuf>,
        failures: Vec<(String, String)>,
    },
    /// Contact-sheet export finished off-thread (WP-074).
    MediaSheetExported {
        lane_id: usize,
        report: MediaSheetExport,
    },
    /// Anchor strip thumbnails decoded off-thread (WP-017): (file name, w, h, rgba).
    AnchorsLoaded {
        items: Vec<(String, usize, usize, Vec<u8>)>,
        error: Option<String>,
    },
    /// Per-file stat sweep for Modified/Size sorting (WP-044), keyed by the
    /// folder it was computed for so stale sweeps are dropped.
    MediaStatsDone {
        key: MediaStatRequestKey,
        stats: Arc<std::collections::HashMap<String, crate::media_explorer::FileStat>>,
        elapsed_ms: u64,
        failures: usize,
        unknown_created: usize,
    },
    /// Immutable normalized search index built away from the render thread.
    MediaSearchIndexReady {
        key: MediaSearchIndexKey,
        result: Result<(Arc<crate::media_search::MediaSearchIndex>, u64, u64), String>,
        elapsed_ms: u64,
    },
    /// Autocomplete candidates ranked off-thread against the immutable index.
    MediaSuggestionsDone {
        key: MediaSuggestionRequestKey,
        suggestions: Arc<Vec<crate::media_search::Suggestion>>,
        cancelled: bool,
    },
    /// Query/sort result for one exact UI request generation.
    MediaDisplayDone {
        key: MediaDisplayCacheKey,
        request_key: crate::media_search::SearchRequestKey,
        indices: Arc<Vec<usize>>,
        elapsed_ms: u64,
        scanned_rows: usize,
        matched_rows: usize,
        cancelled: bool,
    },
    /// Immediate child directories are enumerated away from the render
    /// thread. Arc keeps a 10k-folder result cheap to share across frames.
    MediaChildFoldersDone {
        key: MediaChildFolderRequestKey,
        folders: Arc<Vec<String>>,
        prepared: Arc<PreparedFolderEntries>,
        error: Option<String>,
    },
    /// CLIP engine finished loading off-thread (WP-047).
    ClipReady(Result<std::sync::Arc<crate::media_clip::ClipEngine>, String>),
    /// CLIP embedding index build progress/completion for a folder.
    ClipIndexProgress {
        key: ClipIndexRequestKey,
        done: usize,
        total: usize,
    },
    ClipIndexDone {
        key: ClipIndexRequestKey,
        indexed: usize,
        failed: usize,
        /// False when the build could not even open the index (lock held by
        /// another process) — the folder must NOT be marked indexed then
        /// (review round 3, finding 2).
        ok: bool,
    },
    /// Semantic query resolved: cosine-ranked paths for (query, folder).
    ClipQueryDone {
        key: ClipQueryRequestKey,
        indices: Vec<usize>,
        missing: usize,
        error: Option<String>,
    },
    MatchSnapshotReady(Result<(serde_json::Value, serde_json::Value), String>),
    MatchSettingsSnapshotReady(Result<serde_json::Value, String>),
    MatchHoldsReconciled {
        epoch: u64,
        result: Result<(), String>,
    },
    MatchGalleryReady {
        navigation: MatchNavigationFence,
        result: Result<serde_json::Value, String>,
    },
    MatchGalleryInventoryReady {
        tab_id: String,
        person_id: String,
        request_generation: u64,
        result: Result<crate::match_store::PersonGalleryInventoryOutcome, String>,
    },
    MatchViewerSnapshotReady {
        media_key: String,
        result: Result<serde_json::Value, String>,
    },
    MatchAutocompleteReady {
        request: MatchAutocompleteRequest,
        result: Result<serde_json::Value, String>,
    },
    MatchRuntimeDiagnosticsReady {
        action_id: String,
        result: Result<serde_json::Value, String>,
    },
    MatchDiagnosticsPersistenceReady {
        action_id: String,
        error: Option<String>,
    },
    MatchIntentReady {
        command: ApiCommand,
        navigation: MatchNavigationFence,
        result: Result<MatchIntentOutcome, String>,
    },
    MatchMaintenanceReady {
        command: ApiCommand,
        result: Result<serde_json::Value, String>,
    },
    MatchCorrectionReady {
        command: ApiCommand,
        result: Result<MatchCorrectionOutcome, String>,
    },
    MatchBatchCorrectionPreflightCommandReady {
        command: ApiCommand,
        result: Result<serde_json::Value, String>,
    },
    MatchSplitPersonPreflightCommandReady {
        command: ApiCommand,
        result: Result<serde_json::Value, String>,
    },
    MatchPersonFacesReady {
        person_id: String,
        result: Result<serde_json::Value, String>,
    },
    MatchPersonEditPreflightsReady {
        key: MatchPersonEditPreflightKey,
        result: Result<serde_json::Value, String>,
    },
    MatchSplitPreflightReady {
        key: MatchSplitPreflightKey,
        result: Result<serde_json::Value, String>,
    },
    MatchBatchPreflightsReady {
        key: MatchBatchPreflightKey,
        result: Result<BTreeMap<String, Result<serde_json::Value, String>>, String>,
    },
}

