fn media_sort_settlement(
    sort_effective: bool,
    display_current: bool,
    stats_required: bool,
    stats_active: bool,
    stats_complete: bool,
) -> (bool, &'static str) {
    let settled =
        sort_effective && display_current && (!stats_required || (stats_complete && !stats_active));
    let reason = if !sort_effective {
        "query_ranking_overrides_sort"
    } else if stats_active {
        "stat_sweep_active"
    } else if stats_required && !stats_complete {
        "stat_sidecar_not_current"
    } else if !display_current {
        "display_order_not_current"
    } else {
        "settled"
    };
    (settled, reason)
}

fn media_frame_percentiles(mut samples: Vec<u64>) -> (usize, u64, u64, u64) {
    if samples.is_empty() {
        return (0, 0, 0, 0);
    }
    samples.sort_unstable();
    let nearest_rank = |percent: usize| {
        let rank = ((samples.len() * percent).saturating_add(99) / 100).clamp(1, samples.len());
        samples[rank - 1]
    };
    (
        samples.len(),
        nearest_rank(50),
        nearest_rank(95),
        *samples.last().unwrap_or(&0),
    )
}

