    /// Disk-first manual loader with compiled-in fallback.
    fn load_manual(repo_root: &std::path::Path) -> String {
        std::fs::read_to_string(repo_root.join("product/docs/MANUAL.md"))
            .unwrap_or_else(|_| EMBEDDED_MANUAL.to_string())
    }

    fn load_models(service: &mut FacialService) -> Vec<String> {
        service
            .list_models()
            .into_iter()
            .map(|model| format!("{} [{}] - {}", model.name, model.id, model.status))
            .collect()
    }

    fn load_worktrees(service: &mut FacialService) -> BTreeMap<String, Vec<String>> {
        let mut worktree_view = BTreeMap::new();
        for (project, runs) in service.list_worktrees() {
            worktree_view.insert(
                project,
                runs.into_iter()
                    .map(|path| path.to_string_lossy().to_string())
                    .collect(),
            );
        }
        worktree_view
    }

    fn load_features(service: &mut FacialService) -> Vec<FeatureRow> {
        let mut feature_rows = Vec::new();
        for plugin in service.list_plugins() {
            let plugin_id = plugin
                .get("id")
                .and_then(|value| value.as_str())
                .unwrap_or("")
                .to_string();
            let plugin_name = plugin
                .get("name")
                .and_then(|value| value.as_str())
                .unwrap_or(&plugin_id)
                .to_string();
            if let Some(features) = plugin.get("features").and_then(|value| value.as_array()) {
                for feature in features {
                    let feature_id = feature
                        .get("id")
                        .and_then(|value| value.as_str())
                        .unwrap_or("");
                    if feature_id.is_empty() {
                        continue;
                    }
                    let feature_name = feature
                        .get("name")
                        .and_then(|value| value.as_str())
                        .unwrap_or(feature_id);
                    feature_rows.push(FeatureRow {
                        key: format!("{plugin_id}:{feature_id}"),
                        display: format!("{plugin_name} :: {feature_name} [{feature_id}]"),
                    });
                }
            }
        }
        feature_rows.sort_by(|a, b| a.display.cmp(&b.display));
        feature_rows
    }

    fn compare_lane_position(&self, lane_id: usize) -> Option<usize> {
        self.compare_lanes
            .iter()
            .position(|lane| lane.id == lane_id)
    }

    fn add_compare_lane(&mut self) {
        if self.compare_lanes.len() >= 16 {
            return;
        }
        self.compare_lanes
            .push(CompareLane::new(self.compare_next_lane_id));
        self.compare_next_lane_id += 1;
    }

    fn remove_compare_lane(&mut self) {
        if self.compare_lanes.len() > 1 {
            if let Some(lane) = self.compare_lanes.pop() {
                if let Some(cancel) = self.compare_scan_cancellations.remove(&lane.id) {
                    cancel.store(true, Ordering::Release);
                }
            }
        }
    }

    fn set_compare_lane_count(&mut self, target: usize) {
        let target = target.clamp(1, 16);
        while self.compare_lanes.len() < target {
            self.add_compare_lane();
        }
        while self.compare_lanes.len() > target {
            self.remove_compare_lane();
        }
    }

    fn clone_last_compare_lane_setup(&mut self) {
        if self.compare_lanes.len() >= 16 {
            return;
        }
        let Some(source) = self.compare_lanes.last().cloned() else {
            self.add_compare_lane();
            return;
        };
        let mut lane = CompareLane::new(self.compare_next_lane_id);
        let base_name = if source.name.trim().is_empty() {
            format!("Pane {}", source.id + 1)
        } else {
            source.name
        };
        lane.name = format!("{base_name} copy");
        lane.folder = source.folder;
        lane.recursive = source.recursive;
        self.compare_lanes.push(lane);
        self.compare_next_lane_id += 1;
    }

    fn start_compare_scan(&mut self, lane_id: usize) {
        self.start_compare_scan_internal(lane_id, false);
    }

    fn start_compare_scan_internal(&mut self, lane_id: usize, preserve_cached_inventory: bool) {
        // An explicit scan, or the deferred reconciliation itself, supersedes
        // any pending cache-hit reconciliation for this viewport.
        self.media_tab_reconciliation_pending = None;
        let Some(pos) = self.compare_lane_position(lane_id) else {
            return;
        };
        let (folder, recursive, media_filter, using_runtime_inventory) = {
            let lane = &mut self.compare_lanes[pos];
            let trimmed = sanitize_folder_input(&lane.folder);
            if trimmed.is_empty() {
                lane.scan_error = "Set a folder path first.".to_string();
                return;
            }
            // Reflect the cleaned path back so the field shows what was scanned
            // (drops the surrounding quotes Windows "Copy as path" adds).
            lane.folder = trimmed.clone();
            // Auto-label an unnamed lane with the folder's leaf so multiple lanes
            // stay distinguishable; the operator can still rename it.
            if lane.name.trim().is_empty() {
                if let Some(leaf) = Path::new(&trimmed).file_name().and_then(|s| s.to_str()) {
                    lane.name = leaf.to_string();
                }
            }
            lane.scan_id = lane.scan_id.saturating_add(1);
            lane.scanning = true;
            lane.scan_error.clear();
            // WP-064: a restored viewport is worth keeping visible even when its
            // scan never committed an inventory generation (interrupted scan, or
            // any folder with one unreadable subdirectory). Reconciliation still
            // runs; this only decides whether the operator stares at a blank
            // grid while it does.
            let using_runtime_inventory = preserve_cached_inventory && !lane.files.is_empty();
            if !using_runtime_inventory {
                lane.loading_image = false;
                lane.loading_image_inflight = false;
                lane.pending_image_index = None;
                lane.image_error.clear();
                lane.image_path.clear();
                lane.selected_files.clear();
                lane.selection_anchor = None;
            }
            lane.action_message.clear();
            if !using_runtime_inventory {
                // Swap instead of Arc::make_mut: an obsolete cancellable worker
                // may still own the prior generation briefly, and cloning 141k
                // rows here would stall the UI before that worker observes cancel.
                lane.files = Arc::new(Vec::new());
                lane.inventory_generation = None;
                lane.index = 0;
                lane.texture = None;
                lane.texture_size = None;
            }
            (
                trimmed,
                lane.recursive,
                lane.media_filter,
                using_runtime_inventory,
            )
        };
        self.compare_lanes[pos].scan_using_cached_inventory = using_runtime_inventory;
        // WP-065: a folder change must make an explicit decision about active
        // playback. This path previously never touched the player or the inline
        // placement state, so a video kept decoding while its owning tile was
        // discarded with the old inventory and the pending-placement target was
        // dropped on the scan-id bump. Nothing then placed the surface: audio
        // continued with no picture, or the last frame stayed on screen. Video
        // that belongs to the outgoing folder is stopped; a video that still
        // exists in the incoming inventory is re-placed by the normal owners.
        if !using_runtime_inventory {
            if self
                .media_pending_video_start
                .as_ref()
                .is_some_and(|pending| !path_is_inside_folder(&folder, &pending.path))
            {
                self.media_pending_video_start = None;
                self.media_inline_video_path = None;
                self.media_inline_video_seen = false;
                self.media_inline_video_requested_at = None;
                self.media_inline_video_pending_target = None;
                self.media_playback_lease = None;
            }
            let active_video = self.video_player.active_path().map(|path| path.to_string());
            if let Some(active_video) = active_video {
                let still_inside = path_is_inside_folder(&folder, &active_video);
                if !still_inside {
                    self.video_player.stop();
                    self.media_inline_video_path = None;
                    self.media_inline_video_seen = false;
                    self.media_inline_video_requested_at = None;
                    self.media_inline_video_pending_target = None;
                    self.media_playback_lease = None;
                    crate::video_player::playback_trace_phase(
                        "ui.folder_change.stop_playback",
                        &format!("released {active_video} leaving {folder}"),
                    );
                }
            }
        }
        self.media_child_folder_cache.clear();
        self.media_folder_entry_cache.clear();
        for cancelled in self.media_child_folder_cancel.values() {
            cancelled.store(true, Ordering::Release);
        }
        self.media_child_folder_cancel.clear();
        self.media_child_folder_inflight.clear();
        self.media_content_generation = self.media_content_generation.wrapping_add(1);
        // WP-069: keep an already-published order visible while a cached
        // inventory reconciles. Blanking it unconditionally is what made a tab
        // switch or refresh flash an empty grid even though the rows were
        // already in memory. A genuinely new folder has no cached inventory, so
        // its stale order is still cleared.
        if !using_runtime_inventory {
            self.media_display_cache = Arc::new(Vec::new());
        }
        self.media_display_cache_key = None;
        self.media_display_desired_key = None;
        if self.media_display_inflight.is_some() {
            self.media_query_diagnostics.cancellations =
                self.media_query_diagnostics.cancellations.saturating_add(1);
        }
        self.media_search_requests.cancel_current();
        if let Some(cancel) = self.media_search_index_cancel.take() {
            cancel.store(true, Ordering::Release);
            self.media_query_diagnostics.cancellations =
                self.media_query_diagnostics.cancellations.saturating_add(1);
        }
        if let Some(cancel) = self.media_suggestion_cancel.take() {
            cancel.store(true, Ordering::Release);
            self.media_query_diagnostics.cancellations =
                self.media_query_diagnostics.cancellations.saturating_add(1);
        }
        self.media_search_index = None;
        self.media_search_index_key = None;
        self.media_search_index_inflight = None;
        self.media_suggestion_key = None;
        self.media_suggestions = Arc::new(Vec::new());
        self.media_suggestion_inflight = None;
        if let Some(cancel) = self.media_stat_cancel.take() {
            cancel.store(true, Ordering::Release);
            self.media_query_diagnostics.cancellations =
                self.media_query_diagnostics.cancellations.saturating_add(1);
        }
        self.media_stat_request = None;
        self.media_stat_complete_key = None;
        self.media_stat_unknown_created = None;
        self.media_stat_elapsed_ms = None;
        self.media_explorer.stats_loading = false;
        self.media_explorer.stats = Arc::new(HashMap::new());
        self.media_stats_generation = self.media_stats_generation.wrapping_add(1);
        if let Some(cancel) = self.clip_index_cancel.take() {
            cancel.store(true, Ordering::Release);
        }
        if let Some(cancel) = self.clip_query_cancel.take() {
            cancel.store(true, Ordering::Release);
        }
        self.clip_indexing = false;
        self.clip_index_request = None;
        self.clip_query_request = None;
        self.media_semantic_inflight = None;
        let tx = self.compare_work_tx.clone();
        let scan_id = self.compare_lanes[pos].scan_id;
        let lane_label = lane_id;
        self.begin_media_load_timing(lane_id, scan_id);
        self.media_scan_diagnostics = MediaScanDiagnostics {
            lane_id,
            scan_id,
            status: "scanning".to_string(),
            ..MediaScanDiagnostics::default()
        };
        if let Some(previous) = self.compare_scan_cancellations.remove(&lane_id) {
            previous.store(true, Ordering::Release);
        }
        let cancelled = Arc::new(AtomicBool::new(false));
        self.compare_scan_cancellations
            .insert(lane_id, Arc::clone(&cancelled));
        let (inventory_store, mut inventory_issue) = match self.media_db.inventory_store() {
            Ok(store) => (Some(store), None),
            Err(error) => (None, Some(error)),
        };
        let media_io = Arc::clone(&self.media_io);
        thread::spawn(move || {
            let root = Path::new(&folder);
            let root_identity = media_io_root_identity_for_path(&folder, scan_id);
            let _ = tx.send(CompareWorkEvent::ScanRootReady {
                lane_id: lane_label,
                scan_id,
                identity: root_identity.clone(),
            });
            let progress_tx = tx.clone();
            let cache_started = std::time::Instant::now();
            if !using_runtime_inventory {
                if let Some(store) = inventory_store.as_ref() {
                    let mut cached = store.load_with_identity(
                        root,
                        &root_identity.key,
                        recursive,
                        media_filter.short_label(),
                    );
                    if matches!(cached, Ok(None)) {
                        // Before WP-055's mapped-root proof worked, inventories
                        // were necessarily keyed by the lexical `Z:/...` form.
                        // Promote that exact configured-root manifest after the
                        // OS has proven its UNC identity so an upgrade keeps the
                        // last-good rows instead of forcing one empty cold scan.
                        let lexical_identity = crate::media_db::lexical_media_root_identity(root);
                        if lexical_identity != root_identity.key {
                            cached = store
                                .promote_proven_root_alias(
                                    root,
                                    &lexical_identity,
                                    &root_identity.key,
                                    recursive,
                                    media_filter.short_label(),
                                )
                                .and_then(|_| {
                                    store.load_with_identity(
                                        root,
                                        &root_identity.key,
                                        recursive,
                                        media_filter.short_label(),
                                    )
                                });
                        }
                    }
                    match cached {
                        Ok(Some(inventory)) => {
                            if cancelled.load(Ordering::Acquire) {
                                return;
                            }
                            let display_order = Arc::new((0..inventory.files.len()).collect());
                            let _ = tx.send(CompareWorkEvent::ScanCacheReady {
                                lane_id: lane_label,
                                scan_id,
                                inventory,
                                display_order,
                                load_ms: cache_started.elapsed().as_millis() as u64,
                            });
                        }
                        Ok(None) => {}
                        Err(error) => inventory_issue = Some(error),
                    }
                }
            }
            let io_request =
                media_io.enqueue(root_identity.clone(), crate::media_io::WorkClass::Scan);
            let io_permit = loop {
                if cancelled.load(Ordering::Acquire) {
                    io_request.cancel();
                    return;
                }
                match io_request.try_acquire() {
                    Ok(Some(permit)) => break permit,
                    Ok(None) => thread::sleep(std::time::Duration::from_millis(5)),
                    Err(_) => return,
                }
            };
            let started = std::time::Instant::now();
            let mut first_batch_ms = None;
            // The Manual promises "a first batch of at most 64 items, then
            // bounded follow-up batches", and nothing reported either number, so
            // the claim could not be checked from a receipt (no-context Manual
            // audit, finding 5.3).
            let mut first_batch_items = None;
            let mut batch_count = 0usize;
            match collect_media_paths_for_compare_cancellable(
                root,
                recursive,
                media_filter,
                || cancelled.load(Ordering::Acquire),
                |files| {
                    first_batch_ms.get_or_insert(started.elapsed().as_millis() as u64);
                    first_batch_items.get_or_insert(files.len());
                    batch_count += 1;
                    let _ = progress_tx.send(CompareWorkEvent::ScanBatch {
                        lane_id: lane_label,
                        scan_id,
                        files,
                    });
                },
            ) {
                Ok((mut files, dir_errors)) => {
                    media_io.record_filesystem_duration(
                        &root_identity,
                        crate::media_io::WorkClass::Scan,
                        started.elapsed(),
                    );
                    io_permit.finish(if dir_errors == 0 {
                        crate::media_io::PermitOutcome::Success
                    } else {
                        crate::media_io::PermitOutcome::Error
                    });
                    files.sort();
                    let elapsed_ms = started.elapsed().as_millis() as u64;
                    let mut inventory_generation = None;
                    let mut inventory_write_ms = None;
                    let mut inventory_error = inventory_issue;
                    let mut committed = None;
                    if dir_errors == 0 && !cancelled.load(Ordering::Acquire) {
                        let write_started = std::time::Instant::now();
                        match inventory_store.as_ref() {
                            Some(store) => match store.replace_cancellable_with_identity(
                                root,
                                &root_identity.key,
                                recursive,
                                media_filter.short_label(),
                                &files,
                                elapsed_ms,
                                first_batch_ms,
                                || cancelled.load(Ordering::Acquire),
                            ) {
                                Ok(Some(commit)) => {
                                    inventory_generation = Some(commit.generation);
                                    committed = Some(commit);
                                }
                                Ok(None) => return,
                                Err(error) => inventory_error = Some(error),
                            },
                            None => {}
                        }
                        inventory_write_ms = Some(write_started.elapsed().as_millis() as u64);
                    }
                    let display_order = Arc::new((0..files.len()).collect());
                    let _ = tx.send(CompareWorkEvent::ScanDone {
                        lane_id: lane_label,
                        scan_id,
                        files,
                        display_order,
                        dir_errors,
                        elapsed_ms,
                        first_batch_ms,
                        batch_count,
                        first_batch_items,
                        inventory_generation,
                        inventory_write_ms,
                        inventory_error,
                    });
                    if let (Some(store), Some(commit)) =
                        (inventory_store.as_ref(), committed.as_ref())
                    {
                        store.cleanup_superseded(commit);
                    }
                }
                Err(MediaScanFailure::Cancelled) => {
                    io_permit.finish(crate::media_io::PermitOutcome::Cancelled);
                }
                Err(MediaScanFailure::Failed(error)) => {
                    media_io.record_filesystem_duration(
                        &root_identity,
                        crate::media_io::WorkClass::Scan,
                        started.elapsed(),
                    );
                    io_permit.finish(crate::media_io::PermitOutcome::Error);
                    let _ = tx.send(CompareWorkEvent::ScanError {
                        lane_id: lane_label,
                        scan_id,
                        error,
                        elapsed_ms: started.elapsed().as_millis() as u64,
                        inventory_error: inventory_issue,
                    });
                }
            }
        });
    }

    fn request_compare_image(&mut self, lane_id: usize, index: usize) {
        let Some(pos) = self.compare_lane_position(lane_id) else {
            return;
        };
        let start_now = {
            let lane = &mut self.compare_lanes[pos];
            if lane.files.is_empty() {
                false
            } else {
                let total = lane.files.len();
                let target = index.min(total.saturating_sub(1));
                lane.pending_image_index = Some(target);
                lane.index = target;
                lane.loading_image = true;
                lane.image_path = lane.files[target].clone();
                lane.image_error.clear();
                // Keep the previous texture visible while the next decodes:
                // flipping through a folder must not flash blank frames.
                !lane.loading_image_inflight
            }
        };
        if start_now {
            self.start_compare_image_load(lane_id);
        }
    }

    fn compare_lane_open_selected_with_system(
        &mut self,
        lane_id: usize,
    ) -> Result<(usize, usize), String> {
        let Some(pos) = self.compare_lane_position(lane_id) else {
            return Err("media lane missing".to_string());
        };
        let (indices, paths): (Vec<usize>, Vec<String>) = {
            let lane = &self.compare_lanes[pos];
            if lane.total() == 0 {
                self.set_compare_lane_message(lane_id, "No files found".to_string());
                return Err("no files found".to_string());
            }
            if lane.selected_files.is_empty() {
                let index = lane.index.min(lane.total() - 1);
                let path = lane.files.get(index).cloned().unwrap_or_default();
                (vec![index], vec![path])
            } else {
                let mut selected: Vec<usize> = lane.selected_files.iter().copied().collect();
                selected.sort_unstable();
                let selected_paths = selected
                    .iter()
                    .filter_map(|index| lane.files.get(*index).cloned())
                    .collect::<Vec<_>>();
                (selected, selected_paths)
            }
        };

        if paths.is_empty() {
            self.set_compare_lane_message(lane_id, "No valid selection".to_string());
            return Err("no valid selection".to_string());
        }

        let mut opened = 0usize;
        let mut failed = 0usize;
        for path in &paths {
            let target_path = Path::new(path);
            match self.open_path_with_system_app(target_path) {
                Ok(_) => opened += 1,
                Err(_) => failed += 1,
            }
        }
        if let Some(index) = indices.first().copied() {
            self.request_compare_image(lane_id, index);
        }

        if paths.len() == 1 {
            let first = Path::new(&paths[0]);
            let file_name = first
                .file_name()
                .and_then(|value| value.to_str())
                .unwrap_or("file");
            if opened == 1 {
                self.set_compare_lane_message(lane_id, format!("Opened {file_name}"));
            } else {
                self.set_compare_lane_message(lane_id, format!("Open failed for {file_name}"));
            }
            return Ok((opened, failed));
        }

        match (opened, failed) {
            (0, failed_count) => {
                self.set_compare_lane_message(
                    lane_id,
                    format!(
                        "Open failed for {failed_count} file{}",
                        if failed_count == 1 { "" } else { "s" }
                    ),
                );
            }
            (opened_count, 0) => {
                self.set_compare_lane_message(lane_id, format!("Opened {opened_count} files"));
            }
            (opened_count, failed_count) => {
                self.set_compare_lane_message(
                    lane_id,
                    format!("Opened {opened_count} files, {failed_count} failed"),
                );
            }
        }
        Ok((opened, failed))
    }

    fn compare_lane_open_selected_index_with_system(&mut self, lane_id: usize, index: usize) {
        let Some(pos) = self.compare_lane_position(lane_id) else {
            return;
        };
        let target = {
            let lane = &self.compare_lanes[pos];
            lane.files.get(index).cloned()
        };
        let Some(target) = target else {
            return self
                .set_compare_lane_message(lane_id, "Selected file index unavailable".to_string());
        };
        let target_path = Path::new(&target);
        let target_name = target_path
            .file_name()
            .and_then(|value| value.to_str())
            .unwrap_or("file");

        if let Err(error) = self.open_path_with_system_app(target_path) {
            return self.set_compare_lane_message(
                lane_id,
                format!("Open failed for {target_name}: {error}"),
            );
        }

        self.request_compare_image(lane_id, index);
        self.set_compare_lane_message(lane_id, format!("Opened {target_name}"));
    }

    fn compare_lane_open_location_with_system(
        &mut self,
        lane_id: usize,
        open_index: Option<usize>,
    ) {
        let Some(pos) = self.compare_lane_position(lane_id) else {
            return;
        };

        let target = {
            let lane = &self.compare_lanes[pos];
            if let Some(index) = open_index {
                lane.files.get(index).cloned()
            } else if !lane.selected_files.is_empty() {
                lane.selected_files
                    .iter()
                    .min()
                    .and_then(|index| lane.files.get(*index).cloned())
            } else if lane.total() != 0 {
                Some(lane.files[lane.index].clone())
            } else if !lane.folder.trim().is_empty() {
                Some(lane.folder.clone())
            } else {
                None
            }
        };

        let Some(target) = target else {
            return self.set_compare_lane_message(
                lane_id,
                "No file or folder selected to open".to_string(),
            );
        };

        let target_path = Path::new(&target);
        if !target_path.exists() {
            return self.set_compare_lane_message(
                lane_id,
                "Selected file or folder no longer exists".to_string(),
            );
        }

        if let Err(error) =
            self.open_in_file_manager_with_system_app(target_path, target_path.is_file())
        {
            return self.set_compare_lane_message(
                lane_id,
                format!(
                    "Open location failed for {}: {error}",
                    target_path.to_string_lossy()
                ),
            );
        }

        self.set_compare_lane_message(
            lane_id,
            format!(
                "Opened location for {}",
                target_path
                    .file_name()
                    .and_then(|value| value.to_str())
                    .unwrap_or("file")
            ),
        );
    }

    fn draw_explorer_context_actions(
        ui: &mut egui::Ui,
        request: &mut CompareLaneRenderRequest,
        can_open: bool,
        has_selection: bool,
        has_files: bool,
        has_folder: bool,
        can_paste: bool,
        open_index: Option<usize>,
    ) {
        Self::draw_explorer_action_buttons(
            ui,
            request,
            can_open,
            has_selection,
            has_files,
            has_folder,
            can_paste,
            open_index,
            true,
        );
    }

    /// Full Explorer-parity context menu for MEDIA surfaces (WP-045): the
    /// shared open/copy/paste/delete/selection verbs plus cut, rename, new
    /// folder, refresh, sort, color labels, and favorites. Everything flows
    /// through the request so Compare surfaces stay untouched.
    #[allow(clippy::too_many_arguments)]
    fn draw_media_context_menu(
        ui: &mut egui::Ui,
        request: &mut CompareLaneRenderRequest,
        label_definitions: &[crate::media_db::ColorLabelDefinition],
        can_open: bool,
        has_selection: bool,
        has_files: bool,
        has_folder: bool,
        can_paste: bool,
        open_index: Option<usize>,
        current_sort: (crate::media_explorer::MediaSort, bool),
    ) {
        Self::draw_explorer_action_buttons(
            ui,
            request,
            can_open,
            has_selection,
            has_files,
            has_folder,
            can_paste,
            open_index,
            true,
        );
        ui.separator();
        ui.label(
            egui::RichText::new("Edit")
                .small()
                .strong()
                .color(theme::ink_faint()),
        );
        let action = |ui: &mut egui::Ui, text: &str, enabled: bool, hover: &str| -> bool {
            let button = egui::Button::new(egui::RichText::new(text).small().color(theme::ink()))
                .frame(false);
            if enabled {
                ui.add(button).on_hover_text(hover).clicked()
            } else {
                ui.add_enabled(false, button).on_hover_text(hover).clicked()
            }
        };
        if action(
            ui,
            "Cut",
            has_selection,
            "Cut selected file(s) — paste moves them (Ctrl/Cmd+X)",
        ) {
            request.cut_selected = true;
            ui.close_menu();
        }
        if action(ui, "Rename", has_selection, "Rename the selected file (F2)") {
            request.rename_selected = true;
            ui.close_menu();
        }
        if action(ui, "New folder", has_folder, "Create a folder here") {
            request.new_folder = true;
            ui.close_menu();
        }
        if action(ui, "Refresh", has_folder, "Rescan this folder (F5)") {
            request.refresh = true;
            ui.close_menu();
        }
        ui.separator();
        ui.label(
            egui::RichText::new("Path")
                .small()
                .strong()
                .color(theme::ink_faint()),
        );
        if action(
            ui,
            "Copy absolute path",
            has_selection || has_files || has_folder,
            "Copy the selected file path (or current folder) as an absolute path",
        ) {
            request.copy_absolute_path = true;
            ui.close_menu();
        }
        if action(
            ui,
            "Copy portable path",
            has_selection || has_files || has_folder,
            "Copy a path relative to the workspace, or to the selected folder for external media",
        ) {
            request.copy_portable_path = true;
            ui.close_menu();
        }
        ui.menu_button(egui::RichText::new("Sort by").small(), |ui| {
            for sort in [
                crate::media_explorer::MediaSort::Name,
                crate::media_explorer::MediaSort::Modified,
                crate::media_explorer::MediaSort::Size,
                crate::media_explorer::MediaSort::Created,
            ] {
                let active = current_sort.0 == sort;
                let arrow = if active {
                    if current_sort.1 {
                        " ↓"
                    } else {
                        " ↑"
                    }
                } else {
                    ""
                };
                if ui
                    .selectable_label(active, format!("{}{arrow}", sort.label()))
                    .clicked()
                {
                    // Same key toggles direction, new key starts ascending.
                    request.sort_to = Some(if active {
                        (sort, !current_sort.1)
                    } else {
                        (sort, false)
                    });
                    ui.close_menu();
                }
            }
        });
        ui.separator();
        ui.label(
            egui::RichText::new("Mark")
                .small()
                .strong()
                .color(theme::ink_faint()),
        );
        ui.menu_button(egui::RichText::new("Add label").small(), |ui| {
            egui::ScrollArea::vertical()
                .id_source("media-context-add-labels")
                .max_height(280.0)
                .show(ui, |ui| {
                    for label in label_definitions {
                        let (rect, resp) =
                            ui.allocate_exact_size(egui::vec2(160.0, 18.0), Sense::click());
                        ui.painter().circle_filled(
                            egui::pos2(rect.min.x + 9.0, rect.center().y),
                            5.0,
                            media_label_color(label_definitions, &label.id),
                        );
                        ui.painter().text(
                            egui::pos2(rect.min.x + 20.0, rect.center().y),
                            egui::Align2::LEFT_CENTER,
                            &label.name,
                            egui::TextStyle::Small.resolve(ui.style()),
                            theme::ink(),
                        );
                        if resp.clicked() {
                            request.add_label = Some(label.id.clone());
                            ui.close_menu();
                        }
                    }
                });
        });
        ui.menu_button(egui::RichText::new("Remove label").small(), |ui| {
            egui::ScrollArea::vertical()
                .id_source("media-context-remove-labels")
                .max_height(260.0)
                .show(ui, |ui| {
                    for label in label_definitions {
                        if ui.small_button(&label.name).clicked() {
                            request.remove_label = Some(label.id.clone());
                            ui.close_menu();
                        }
                    }
                });
            ui.separator();
            if ui.small_button("Remove all labels").clicked() {
                request.clear_labels = true;
                ui.close_menu();
            }
        });
        if action(
            ui,
            "Toggle favorite",
            has_selection || has_folder,
            "Star/unstar the selected file (or this folder when nothing is selected)",
        ) {
            request.toggle_favorite = true;
            ui.close_menu();
        }
    }

    fn draw_explorer_action_buttons(
        ui: &mut egui::Ui,
        request: &mut CompareLaneRenderRequest,
        can_open: bool,
        has_selection: bool,
        has_files: bool,
        has_folder: bool,
        can_paste: bool,
        open_index: Option<usize>,
        close_menu: bool,
    ) {
        let themed_action =
            |ui: &mut egui::Ui, text: &str, color: egui::Color32, enabled: bool, hover: &str| {
                let button =
                    egui::Button::new(egui::RichText::new(text).small().color(color)).frame(false);
                if enabled {
                    ui.add(button).on_hover_text(hover).clicked()
                } else {
                    ui.add_enabled(false, button).on_hover_text(hover).clicked()
                }
            };

        let has_open_target = can_open || open_index.is_some();
        let section = |ui: &mut egui::Ui, title: &str| {
            ui.separator();
            ui.label(
                egui::RichText::new(title)
                    .small()
                    .strong()
                    .color(theme::ink_faint()),
            );
        };

        if close_menu {
            ui.set_min_width(190.0);

            section(ui, "Open");
            if themed_action(
                ui,
                "Open file",
                theme::ink(),
                has_open_target,
                "Open selected file(s) with the system app (Enter or Ctrl/Cmd+O)",
            ) {
                request.open_file = true;
                request.open_index_in_system = open_index;
                ui.close_menu();
            }
            if themed_action(
                ui,
                "Open file location",
                theme::ink_soft(),
                has_files || has_folder,
                "Reveal selected file/folder in OS file browser",
            ) {
                request.open_location = true;
                request.open_location_index = open_index;
                ui.close_menu();
            }

            section(ui, "Clipboard");
            let copy_hover = if has_selection {
                "Copy selected file(s) (Ctrl/Cmd + C)"
            } else {
                "No files are selected"
            };
            if themed_action(ui, "Copy", theme::ink_faint(), has_selection, copy_hover) {
                request.copy_selected = true;
                ui.close_menu();
            }
            if themed_action(
                ui,
                "Paste",
                theme::ink_faint(),
                can_paste,
                "Paste copied file(s) into this folder (Ctrl/Cmd + V)",
            ) {
                request.paste = true;
                ui.close_menu();
            }
            if themed_action(
                ui,
                "Delete",
                theme::error_ink(),
                has_selection,
                "Move selected file(s) to the Recycle Bin after confirmation (Delete key)",
            ) {
                request.delete_selected = true;
                ui.close_menu();
            }
            if themed_action(
                ui,
                "Delete permanently",
                theme::error_ink(),
                has_selection,
                "Skip the Recycle Bin (Shift+Delete); confirmation still required",
            ) {
                request.delete_selected_permanent = true;
                ui.close_menu();
            }

            // WP-074: destination-directed filing for the whole selection.
            section(ui, "Send to");
            if themed_action(
                ui,
                "Move to folder…",
                theme::ink_faint(),
                has_selection,
                "Choose a destination folder and move every selected file there",
            ) {
                request.move_to_folder = true;
                ui.close_menu();
            }
            if themed_action(
                ui,
                "Copy to folder…",
                theme::ink_faint(),
                has_selection,
                "Choose a destination folder and copy every selected file there",
            ) {
                request.copy_to_folder = true;
                ui.close_menu();
            }
            if themed_action(
                ui,
                "Copy into new folder…",
                theme::ink_faint(),
                has_selection,
                "Create a new folder (in the selection's parent by default) and copy into it",
            ) {
                request.copy_into_new_folder = true;
                ui.close_menu();
            }
            if themed_action(
                ui,
                "Export contact sheet…",
                theme::ink_faint(),
                has_selection,
                "Write a PNG contact sheet of the selected files beside their folder",
            ) {
                request.export_sheet = true;
                ui.close_menu();
            }

            section(ui, "Selection");
            if themed_action(
                ui,
                "Select all",
                theme::ink_soft(),
                has_files,
                "Select all files in this view (Ctrl/Cmd + A)",
            ) {
                request.select_all = true;
                ui.close_menu();
            }
            if themed_action(
                ui,
                "Select none",
                theme::ink_soft(),
                has_selection,
                "Clear selection in this view (Ctrl/Cmd + Shift + A)",
            ) {
                request.select_none = true;
                ui.close_menu();
            }
            if themed_action(
                ui,
                "Invert selection",
                theme::ink_faint(),
                has_files,
                "Invert file selection in this view (Ctrl/Cmd + I)",
            ) {
                request.invert_selection = true;
                ui.close_menu();
            }
            return;
        }

        if themed_action(
            ui,
            "Open file",
            theme::ink(),
            has_open_target,
            "Open selected file(s) with the system app (Enter or Ctrl/Cmd+O)",
        ) {
            request.open_file = true;
            request.open_index_in_system = open_index;
        }

        ui.separator();
        if themed_action(
            ui,
            "Open file location",
            theme::ink_soft(),
            has_files || has_folder,
            "Reveal selected file/folder in OS file browser",
        ) {
            request.open_location = true;
            request.open_location_index = open_index;
        }

        ui.separator();
        let copy_hover = if has_selection {
            "Copy selected file(s) (Ctrl/Cmd + C)"
        } else {
            "No files are selected"
        };
        if themed_action(ui, "Copy", theme::ink_faint(), has_selection, copy_hover) {
            request.copy_selected = true;
        }
        if themed_action(
            ui,
            "Paste",
            theme::ink_faint(),
            can_paste,
            "Paste copied file(s) into this folder (Ctrl/Cmd + V)",
        ) {
            request.paste = true;
        }
        if themed_action(
            ui,
            "Delete",
            theme::error_ink(),
            has_selection,
            "Delete selected file(s) (Delete / Backspace)",
        ) {
            request.delete_selected = true;
        }

        ui.separator();
        if themed_action(
            ui,
            "Select all",
            theme::ink_soft(),
            has_files,
            "Select all files in this view (Ctrl/Cmd + A)",
        ) {
            request.select_all = true;
        }
        if themed_action(
            ui,
            "Select none",
            theme::ink_soft(),
            has_selection,
            "Clear selection in this view (Ctrl/Cmd + Shift + A)",
        ) {
            request.select_none = true;
        }
        if themed_action(
            ui,
            "Invert selection",
            theme::ink_faint(),
            has_files,
            "Invert file selection in this view (Ctrl/Cmd + I)",
        ) {
            request.invert_selection = true;
        }
    }

    fn open_path_with_system_app(&self, path: &Path) -> Result<(), String> {
        if !path.exists() {
            return Err("File no longer exists".to_string());
        }
        if crate::media_explorer::is_video_path(&path.to_string_lossy()) {
            return crate::video_player::open_in_vlc(path).or_else(|_| {
                crate::video_player::open_with_dialog(
                    path,
                    self.video_player.parent_window_handle(),
                )
            });
        }
        #[cfg(target_os = "windows")]
        {
            StdCommand::new("cmd")
                .args(["/C", "start", "", path.to_string_lossy().as_ref()])
                .spawn()
                .map_err(|error| format!("failed to launch default file app: {error}"))?;
        }
        #[cfg(target_os = "macos")]
        {
            StdCommand::new("open")
                .arg(path)
                .spawn()
                .map_err(|error| format!("failed to launch default file app: {error}"))?;
        }
        #[cfg(all(not(target_os = "windows"), not(target_os = "macos")))]
        {
            StdCommand::new("xdg-open")
                .arg(path)
                .spawn()
                .map_err(|error| format!("failed to launch default file app: {error}"))?;
        }
        Ok(())
    }

    fn open_in_file_manager_with_system_app(
        &self,
        path: &Path,
        reveal_file: bool,
    ) -> Result<(), String> {
        if !path.exists() {
            return Err("Location no longer exists".to_string());
        }

        #[cfg(target_os = "windows")]
        {
            if reveal_file {
                // WP-073 (operator report): `/select,` and the path passed as
                // TWO arguments makes Explorer ignore the selection and open a
                // default window. The shell API is the exact reveal; a
                // single-argument `/select,<path>` spawn is the fallback.
                let target = path.to_path_buf();
                std::thread::spawn(move || {
                    if !reveal_in_explorer_with_shell(&target) {
                        let argument = format!("/select,{}", target.display());
                        let _ = StdCommand::new("explorer").arg(argument).spawn();
                    }
                });
            } else {
                StdCommand::new("explorer")
                    .arg(path)
                    .spawn()
                    .map_err(|error| format!("failed to open file manager: {error}"))?;
            }
        }
        #[cfg(target_os = "macos")]
        {
            if reveal_file {
                StdCommand::new("open")
                    .arg("-R")
                    .arg(path)
                    .spawn()
                    .map_err(|error| format!("failed to open file manager: {error}"))?;
            } else {
                StdCommand::new("open")
                    .arg(path)
                    .spawn()
                    .map_err(|error| format!("failed to open file manager: {error}"))?;
            }
        }
        #[cfg(all(not(target_os = "windows"), not(target_os = "macos")))]
        {
            let target = if reveal_file {
                path.parent().unwrap_or(path)
            } else {
                path
            };
            StdCommand::new("xdg-open")
                .arg(target)
                .spawn()
                .map_err(|error| format!("failed to open file manager: {error}"))?;
        }
        Ok(())
    }

    fn start_compare_image_load(&mut self, lane_id: usize) {
        let Some(pos) = self.compare_lane_position(lane_id) else {
            return;
        };
        if self.compare_lanes[pos].loading_image_inflight {
            return;
        }

        let (file_path, load_id) = {
            let lane = &mut self.compare_lanes[pos];
            let Some(target) = lane.pending_image_index.take() else {
                lane.loading_image = false;
                return;
            };
            if lane.files.is_empty() {
                lane.loading_image = false;
                return;
            }
            let total = lane.files.len();
            let target = target.min(total.saturating_sub(1));
            lane.index = target;
            lane.image_path = lane.files[target].clone();
            lane.load_id = lane.load_id.saturating_add(1);
            lane.loading_image_inflight = true;
            lane.image_error.clear();
            (lane.image_path.clone(), lane.load_id)
        };
        let tx = self.compare_work_tx.clone();
        let root_identity = self.media_root_identity.clone().unwrap_or_else(|| {
            crate::media_io::RootIdentity::new(
                file_path.clone(),
                0,
                crate::media_io::RootKind::Unknown,
            )
        });
        let media_io = Arc::clone(&self.media_io);
        thread::spawn(move || {
            let io_request =
                media_io.enqueue(root_identity.clone(), crate::media_io::WorkClass::Visible);
            let Ok(io_permit) = io_request.wait() else {
                return;
            };
            let started = std::time::Instant::now();
            let result = std::fs::read(&file_path)
                .map_err(|error| format!("read Viewer image: {error}"))
                .and_then(|bytes| {
                    let orientation = crate::media_thumbs::exif_orientation(&bytes);
                    let image = image::load_from_memory(&bytes)
                        .map_err(|error| format!("decode Viewer image: {error}"))?;
                    let rgba =
                        crate::media_thumbs::apply_exif_orientation(image, orientation).to_rgba8();
                    Ok((
                        rgba.width() as usize,
                        rgba.height() as usize,
                        rgba.into_raw(),
                    ))
                });
            media_io.record_filesystem_duration(
                &root_identity,
                crate::media_io::WorkClass::Visible,
                started.elapsed(),
            );
            let succeeded = result.is_ok();
            match result {
                Ok((width, height, pixels)) => {
                    let _ = tx.send(CompareWorkEvent::ImageDone {
                        lane_id,
                        load_id,
                        path: file_path,
                        width,
                        height,
                        pixels,
                    });
                }
                Err(error) => {
                    let _ = tx.send(CompareWorkEvent::ImageError {
                        lane_id,
                        load_id,
                        path: file_path,
                        error: format!("{error}"),
                    });
                }
            }
            io_permit.finish(if succeeded {
                crate::media_io::PermitOutcome::Success
            } else {
                crate::media_io::PermitOutcome::Error
            });
        });
    }

    /// Decode the identity reference set into strip thumbnails off-thread
    /// (WP-017). Capped at 24 anchors; results arrive as AnchorsLoaded.
    fn start_anchor_load(&mut self) {
        let Some(ref_dir) = self.config.identity_reference_dir.clone() else {
            return;
        };
        if self.compare_anchors_loading {
            return;
        }
        self.compare_anchors_loading = true;
        self.compare_anchor_error.clear();
        let tx = self.compare_work_tx.clone();
        thread::spawn(move || {
            let mut items: Vec<(String, usize, usize, Vec<u8>)> = Vec::new();
            let mut error = None;
            match std::fs::read_dir(&ref_dir) {
                Ok(entries) => {
                    let mut paths: Vec<PathBuf> = entries
                        .flatten()
                        .map(|e| e.path())
                        .filter(|p| p.is_file() && is_supported_image_path(p))
                        .collect();
                    paths.sort();
                    for path in paths.into_iter().take(24) {
                        if let Ok(img) = image::open(&path) {
                            let thumb = img.thumbnail(160, 96).to_rgba8();
                            items.push((
                                path.file_name()
                                    .and_then(|n| n.to_str())
                                    .unwrap_or("anchor")
                                    .to_string(),
                                thumb.width() as usize,
                                thumb.height() as usize,
                                thumb.into_raw(),
                            ));
                        }
                    }
                    if items.is_empty() {
                        error = Some("no decodable anchor images in the reference dir".to_string());
                    }
                }
                Err(e) => error = Some(format!("read reference dir: {e}")),
            }
            let _ = tx.send(CompareWorkEvent::AnchorsLoaded { items, error });
        });
    }

    fn handle_compare_events(&mut self, ctx: &egui::Context) {
        self.observe_match_navigation();
        let event_started = std::time::Instant::now();
        let mut handled = 0usize;
        loop {
            // Large scans and thumbnail/index workers can complete in bursts.
            // Keep event draining inside one small frame budget and schedule
            // the remainder instead of monopolizing input/render handling.
            if handled >= 32 || event_started.elapsed() >= std::time::Duration::from_millis(4) {
                ctx.request_repaint();
                break;
            }
            let event = match self.compare_work_rx.try_recv() {
                Ok(event) => {
                    handled += 1;
                    event
                }
                Err(mpsc::TryRecvError::Empty) => break,
                Err(_) => break,
            };
            match event {
                CompareWorkEvent::ClipReady(result) => {
                    self.clip_loading = false;
                    match result {
                        Ok(engine) => {
                            // Names the picked tensors so a wrong export is
                            // visible, never silent (round 3, finding 5).
                            self.clip_status = format!(
                                "semantic search: CLIP ready ({} dims; {})",
                                engine.dim, engine.picks
                            );
                            self.clip_engine = Some(engine);
                        }
                        Err(err) => {
                            self.clip_status = format!("semantic search: local fallback ({err})");
                        }
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::ClipIndexProgress { key, done, total } => {
                    if self.clip_index_request.as_ref() == Some(&key) {
                        self.clip_status = format!("semantic search: indexing {done}/{total}…");
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::ClipIndexDone {
                    key,
                    indexed,
                    failed,
                    ok,
                } => {
                    if self.clip_index_request.as_ref() != Some(&key) {
                        continue;
                    }
                    self.clip_indexing = false;
                    self.clip_index_request = None;
                    self.clip_index_cancel = None;
                    if ok {
                        self.clip_indexed_folder = Some(key.folder);
                        self.clip_status = if failed > 0 {
                            format!("semantic search: index ready ({indexed} new, {failed} failed)")
                        } else {
                            format!("semantic search: index ready ({indexed} new)")
                        };
                    } else {
                        // Open failed (index busy elsewhere): stay unindexed
                        // so a later frame retries instead of going silently
                        // empty for the rest of the session.
                        self.clip_status = "semantic search: index busy — will retry".to_string();
                    }
                    // Force a fresh ranked query against the new index.
                    self.media_semantic = None;
                    self.media_semantic_generation = self.media_semantic_generation.wrapping_add(1);
                    self.media_semantic_inflight = None;
                    ctx.request_repaint();
                }
                CompareWorkEvent::ClipQueryDone {
                    key,
                    indices,
                    missing,
                    error,
                } => {
                    if self.clip_query_request.as_ref() != Some(&key) {
                        continue;
                    }
                    self.clip_query_request = None;
                    self.clip_query_cancel = None;
                    self.media_semantic_inflight = None;
                    if let Some(err) = error {
                        self.clip_status = format!("semantic search: {err}");
                        self.clip_query_backoff = Some(std::time::Instant::now());
                    } else {
                        self.clip_query_backoff = None;
                        self.media_semantic = Some((key.folder, key.query, Arc::new(indices)));
                        self.media_semantic_generation =
                            self.media_semantic_generation.wrapping_add(1);
                        if missing > 0 {
                            self.clip_status =
                                format!("semantic search: ranked (skipped {missing} unindexed)");
                        }
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MediaSearchIndexReady {
                    key,
                    result,
                    elapsed_ms,
                } => {
                    if self.media_search_index_inflight.as_ref() == Some(&key) {
                        self.media_search_index_inflight = None;
                    }
                    if self.media_search_index_key_for(key.lane_id).as_ref() == Some(&key) {
                        match result {
                            Ok((index, identity_revision, catalog_revision)) => {
                                self.media_search_status = format!(
                                    "search index · {} rows · {elapsed_ms} ms",
                                    group_thousands(index.len())
                                );
                                self.media_query_diagnostics.status = "index_ready".to_string();
                                self.media_query_diagnostics.index_rows = index.len();
                                self.media_query_diagnostics.index_elapsed_ms = elapsed_ms;
                                self.media_search_match_identity_revision = identity_revision;
                                self.media_search_match_catalog_revision = catalog_revision;
                                self.media_search_index_key = Some(key);
                                self.media_search_index = Some(index);
                                self.media_display_pending_since = Some(std::time::Instant::now());
                            }
                            Err(error) => {
                                self.media_search_index = None;
                                self.media_search_index_key = None;
                                self.media_query_diagnostics.status =
                                    "person_index_failed".to_string();
                                self.media_search_status = error;
                            }
                        }
                    } else {
                        self.media_query_diagnostics.stale_drops =
                            self.media_query_diagnostics.stale_drops.saturating_add(1);
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MediaSuggestionsDone {
                    key,
                    suggestions,
                    cancelled,
                } => {
                    if self.media_suggestion_inflight.as_ref() == Some(&key) {
                        self.media_suggestion_inflight = None;
                        self.media_suggestion_cancel = None;
                    }
                    let current_index_key = self.media_search_index_key_for(key.index_key.lane_id);
                    let current_folder = self
                        .compare_lane_position(key.index_key.lane_id)
                        .map(|pos| sanitize_folder_input(&self.compare_lanes[pos].folder))
                        .unwrap_or_default();
                    let current = media_suggestion_result_is_current(
                        &key,
                        current_index_key.as_ref(),
                        self.media_search_index_key.as_ref(),
                        &self.media_search_query,
                        &current_folder,
                        cancelled,
                    );
                    if current {
                        self.media_suggestion_key = Some(key);
                        self.media_suggestions = suggestions;
                    } else if !cancelled {
                        self.media_query_diagnostics.stale_drops =
                            self.media_query_diagnostics.stale_drops.saturating_add(1);
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MediaDisplayDone {
                    key,
                    request_key,
                    indices,
                    elapsed_ms,
                    scanned_rows,
                    matched_rows,
                    cancelled,
                } => {
                    if self.media_display_inflight == Some(request_key) {
                        self.media_display_inflight = None;
                    }
                    if !cancelled
                        && self.media_search_requests.is_current(request_key)
                        && self.media_display_desired_key.as_ref() == Some(&key)
                    {
                        self.media_search_status = format!(
                            "display · {} rows · {elapsed_ms} ms",
                            group_thousands(indices.len())
                        );
                        self.media_query_diagnostics.status = "complete".to_string();
                        self.media_query_diagnostics.scanned_rows = scanned_rows;
                        self.media_query_diagnostics.matched_rows = matched_rows;
                        self.media_query_diagnostics.query_elapsed_ms = elapsed_ms;
                        if crate::media_search::parse_query(&key.query).is_empty() {
                            self.media_query_diagnostics.sort_elapsed_ms = elapsed_ms;
                        }
                        let settled_lane_id = key.lane_id;
                        let settled_scan_id = key.scan_id;
                        self.media_display_cache_key = Some(key);
                        self.media_display_cache = indices;
                        if self.media_sort_diagnostics().sort_settled {
                            self.mark_media_load_timing(
                                settled_lane_id,
                                settled_scan_id,
                                MediaLoadMark::SettledOrder,
                            );
                        }
                    } else {
                        self.media_query_diagnostics.stale_drops =
                            self.media_query_diagnostics.stale_drops.saturating_add(1);
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MediaStatsDone {
                    key,
                    stats,
                    elapsed_ms,
                    failures,
                    unknown_created,
                } => {
                    // Only the exact active immutable request may clear the
                    // loading state or publish. Folder text alone is
                    // insufficient after a rescan of the same NAS root.
                    let current = self.compare_lane_position(key.lane_id).map(|pos| {
                        let lane = &self.compare_lanes[pos];
                        (
                            lane.id,
                            lane.scan_id,
                            lane.inventory_generation,
                            sanitize_folder_input(&lane.folder),
                        )
                    });
                    let current_result = current.as_ref().is_some_and(
                        |(lane_id, scan_id, inventory_generation, folder)| {
                            media_stat_result_is_current(
                                &key,
                                self.media_stat_request.as_ref(),
                                *lane_id,
                                *scan_id,
                                self.media_content_generation,
                                *inventory_generation,
                                folder,
                            )
                        },
                    );
                    if current_result {
                        self.media_explorer.stats_loading = false;
                        self.media_stat_request = None;
                        self.media_stat_cancel = None;
                        self.media_stat_complete_key = Some(key);
                        self.media_explorer.stats = stats;
                        self.media_query_diagnostics.stat_elapsed_ms = elapsed_ms;
                        self.media_query_diagnostics.stat_failures = failures;
                        self.media_stat_elapsed_ms = Some(elapsed_ms);
                        self.media_stat_unknown_created = Some(unknown_created);
                        self.media_stats_generation = self.media_stats_generation.wrapping_add(1);
                    } else {
                        self.media_query_diagnostics.stale_drops =
                            self.media_query_diagnostics.stale_drops.saturating_add(1);
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MediaChildFoldersDone {
                    key,
                    folders,
                    prepared,
                    error,
                } => {
                    // The exact staged request key is the producer/consumer
                    // contract. Comparing it with `media_root_identity` is
                    // wrong because that identity belongs to the committed
                    // active folder, not the staged navigator location.
                    let was_inflight = self.media_child_folder_inflight.remove(&key);
                    self.media_child_folder_cancel.remove(&key);
                    let current = self.compare_lane_position(key.lane_id).is_some_and(|pos| {
                        was_inflight && self.compare_lanes[pos].scan_id == key.scan_id
                    });
                    if !current {
                        self.media_query_diagnostics.stale_drops =
                            self.media_query_diagnostics.stale_drops.saturating_add(1);
                        continue;
                    }
                    let folder = key.folder;
                    // A small bounded cache supports current-folder and
                    // parent/sibling navigation without growing forever.
                    if self.media_child_folder_cache.len() >= 64
                        && !self.media_child_folder_cache.contains_key(&folder)
                    {
                        self.media_child_folder_cache.clear();
                        self.media_folder_entry_cache.clear();
                    }
                    self.media_child_folder_cache
                        .insert(folder.clone(), folders);
                    self.media_folder_entry_cache
                        .insert(folder.clone(), prepared);
                    if let Some(cancel) = self.media_suggestion_cancel.take() {
                        cancel.store(true, Ordering::Release);
                        self.media_query_diagnostics.cancellations =
                            self.media_query_diagnostics.cancellations.saturating_add(1);
                    }
                    self.media_suggestion_key = None;
                    self.media_suggestions = Arc::new(Vec::new());
                    if let Some(error) = error {
                        let current = self
                            .compare_lanes
                            .first()
                            .map(|lane| sanitize_folder_input(&lane.folder))
                            .unwrap_or_default();
                        if current == folder {
                            self.compare_action_message = error;
                        }
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::ScanRootReady {
                    lane_id,
                    scan_id,
                    identity,
                } => {
                    if let Some(pos) = self.compare_lane_position(lane_id) {
                        if self.compare_lanes[pos].scan_id == scan_id {
                            let source_root =
                                sanitize_folder_input(&self.compare_lanes[pos].folder);
                            let changed = self.media_root_identity.as_ref() != Some(&identity)
                                || self.media_root_source.as_deref() != Some(source_root.as_str());
                            if changed {
                                let repaint_ctx = ctx.clone();
                                self.thumb_engine = Some(
                                    crate::media_thumbs::ThumbnailEngine::new_with_cache_cap_and_io(
                                        &self.config.workspace_root,
                                        self.config.media_thumb_cache_mb,
                                        Arc::clone(&self.media_io),
                                        identity.clone(),
                                        Path::new(&source_root),
                                        Box::new(move || repaint_ctx.request_repaint()),
                                    ),
                                );
                                let _ = self.thumb_textures.clear();
                            }
                            self.media_scan_diagnostics.root_key = Some(identity.key.clone());
                            self.media_scan_diagnostics.root_kind = Some(identity.kind);
                            self.media_root_identity = Some(identity);
                            self.media_root_source = Some(source_root);
                        }
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::ScanCacheReady {
                    lane_id,
                    scan_id,
                    inventory,
                    display_order,
                    load_ms,
                } => {
                    let mut start_preview = false;
                    if let Some(pos) = self.compare_lane_position(lane_id) {
                        let lane = &mut self.compare_lanes[pos];
                        if lane.scan_id != scan_id || !lane.scanning {
                            continue;
                        }
                        lane.scan_using_cached_inventory = true;
                        lane.inventory_generation = Some(inventory.generation);
                        self.media_scan_diagnostics.status = "cached_reconciling".to_string();
                        self.media_scan_diagnostics.cached_items = inventory.files.len();
                        self.media_scan_diagnostics.inventory_generation =
                            Some(inventory.generation);
                        lane.files = Arc::new(inventory.files);
                        // WP-069: publish an immediately renderable order for
                        // every batch, not only for the empty-query/Name-sort
                        // special case. Otherwise any active query or non-default
                        // sort turns a streaming folder open into a blank grid
                        // until a worker round trip finishes. The display cache
                        // KEY stays unset, so the authoritative ranked/sorted
                        // order still replaces this provisional one.
                        publish_provisional_display(
                            &mut self.media_display_cache,
                            &mut self.media_display_cache_key,
                            display_order,
                        );
                        lane.action_message = format!(
                            "cached generation {} · {} items · loaded {load_ms} ms · checking source…",
                            inventory.generation,
                            group_thousands(lane.files.len())
                        );
                        if !lane.files.is_empty() {
                            lane.index = 0;
                            lane.loading_image = true;
                            lane.pending_image_index = Some(0);
                            lane.image_path = lane.files[0].clone();
                            start_preview = true;
                        }
                        self.media_content_generation =
                            self.media_content_generation.wrapping_add(1);
                    }
                    if !self.media_display_cache.is_empty() {
                        self.mark_media_load_timing(lane_id, scan_id, MediaLoadMark::FirstRow);
                    }
                    self.restore_media_tab_selection(lane_id);
                    if self
                        .compare_lane_position(lane_id)
                        .is_some_and(|pos| self.compare_lanes[pos].pending_image_index.is_some())
                    {
                        start_preview = true;
                    }
                    if start_preview {
                        self.start_compare_image_load(lane_id);
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::ScanBatch {
                    lane_id,
                    scan_id,
                    files,
                } => {
                    let mut start_preview = false;
                    let mut appended_range = None;
                    if let Some(pos) = self.compare_lane_position(lane_id) {
                        let lane = &mut self.compare_lanes[pos];
                        if lane.scan_id != scan_id || !lane.scanning {
                            continue;
                        }
                        if lane.scan_using_cached_inventory {
                            // The complete cached generation remains visible
                            // until reconciliation is itself complete.
                            continue;
                        }
                        let was_empty = lane.files.is_empty();
                        let first_new = lane.files.len();
                        Arc::make_mut(&mut lane.files).extend(files);
                        appended_range = Some(first_new..lane.files.len());
                        if was_empty && !lane.files.is_empty() {
                            lane.index = 0;
                            lane.loading_image = true;
                            lane.pending_image_index = Some(0);
                            start_preview = true;
                        }
                        self.media_content_generation =
                            self.media_content_generation.wrapping_add(1);
                    }
                    // WP-069: append every published batch so the grid keeps
                    // growing and stays scrollable during enumeration. Appending
                    // in traversal order is provisional; the settled order
                    // replaces it when the display worker completes.
                    if let Some(range) = appended_range {
                        append_provisional_display(
                            &mut self.media_display_cache,
                            &mut self.media_display_cache_key,
                            range,
                        );
                    }
                    if !self.media_display_cache.is_empty() {
                        self.mark_media_load_timing(lane_id, scan_id, MediaLoadMark::FirstRow);
                    }
                    if start_preview {
                        self.start_compare_image_load(lane_id);
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::ScanDone {
                    lane_id,
                    scan_id,
                    files,
                    display_order,
                    dir_errors,
                    elapsed_ms,
                    first_batch_ms,
                    batch_count,
                    first_batch_items,
                    inventory_generation,
                    inventory_write_ms,
                    inventory_error,
                } => {
                    if let Some(pos) = self.compare_lane_position(lane_id) {
                        if self.compare_lanes[pos].scan_id != scan_id {
                            continue;
                        }
                        // A cached-generation stat sweep may have been running
                        // during reconciliation. Final scan publication is a
                        // new content boundary even when the folder text is
                        // unchanged, so invalidate it before replacing rows.
                        if let Some(cancel) = self.media_stat_cancel.take() {
                            cancel.store(true, Ordering::Release);
                            self.media_query_diagnostics.cancellations =
                                self.media_query_diagnostics.cancellations.saturating_add(1);
                        }
                        self.media_stat_request = None;
                        self.media_stat_complete_key = None;
                        self.media_stat_unknown_created = None;
                        self.media_stat_elapsed_ms = None;
                        self.media_explorer.stats_loading = false;
                        self.media_explorer.stats = Arc::new(HashMap::new());
                        self.media_stats_generation = self.media_stats_generation.wrapping_add(1);
                        self.media_scan_diagnostics.status = if dir_errors == 0 {
                            "complete".to_string()
                        } else {
                            "incomplete".to_string()
                        };
                        self.media_scan_diagnostics.final_items = files.len();
                        self.media_scan_diagnostics.first_batch_ms = first_batch_ms;
                        self.media_scan_diagnostics.batch_count = batch_count;
                        self.media_scan_diagnostics.first_batch_items = first_batch_items;
                        self.media_scan_diagnostics.elapsed_ms = Some(elapsed_ms);
                        self.media_scan_diagnostics.dir_errors = dir_errors;
                        self.media_scan_diagnostics.inventory_generation = inventory_generation;
                        self.media_scan_diagnostics.inventory_write_ms = inventory_write_ms;
                        self.media_scan_diagnostics.inventory_error = inventory_error.clone();
                        self.compare_scan_cancellations.remove(&lane_id);
                        let kept_cached =
                            self.compare_lanes[pos].scan_using_cached_inventory && dir_errors > 0;
                        if kept_cached {
                            let lane = &mut self.compare_lanes[pos];
                            lane.scanning = false;
                            lane.scan_using_cached_inventory = false;
                            lane.scan_error = format!(
                                "Source scan incomplete: skipped {dir_errors} unreadable directories; last-good inventory retained"
                            );
                            lane.action_message = format!(
                                "stale inventory · {} items · reconcile {} ms",
                                group_thousands(lane.files.len()),
                                elapsed_ms
                            );
                            self.media_scan_diagnostics.status =
                                "incomplete_stale_retained".to_string();
                            ctx.request_repaint();
                            continue;
                        }

                        // Progressive batches are traversal-ordered, while
                        // the terminal inventory is sorted. Relocate an exact
                        // pending playback target once at publication so its
                        // numeric slot cannot become stale under the same scan
                        // id. The worker's sorted vector makes this O(log n),
                        // including 100k+ folders.
                        let pending_sorted_index = self
                            .media_inline_video_pending_target
                            .as_ref()
                            .filter(|pending| {
                                pending.requested_scan_id == scan_id
                                    && pending.tab_id == self.media_tabs.active_id().as_str()
                            })
                            .and_then(|pending| {
                                pending_path_index_in_sorted(
                                    &files,
                                    &pending.path,
                                    &pending.path_key,
                                    |candidate| self.media_db.key_for(candidate),
                                )
                            });
                        // Inline Library playback may already have become
                        // visible during a progressive batch, which clears the
                        // short-lived pending placement. Re-establish exact
                        // placement at the terminal reorder boundary so a
                        // playing tile follows its file instead of its old
                        // traversal-order number.
                        let inline_terminal_target =
                            self.media_inline_video_path.as_ref().and_then(|path| {
                                let path_key = self.media_db.key_for(path);
                                pending_path_index_in_sorted(&files, path, &path_key, |candidate| {
                                    self.media_db.key_for(candidate)
                                })
                                .map(|source_index| (path.clone(), path_key, source_index))
                            });

                        let lane = &mut self.compare_lanes[pos];
                        lane.scanning = false;
                        lane.scan_using_cached_inventory = false;
                        if dir_errors == 0 {
                            lane.inventory_generation = inventory_generation;
                        } else if !kept_cached {
                            lane.inventory_generation = None;
                        }
                        lane.loading_image_inflight = false;
                        lane.pending_image_index = None;
                        lane.scan_error.clear();
                        if dir_errors > 0 {
                            lane.scan_error = format!(
                                "Incomplete source scan: skipped {dir_errors} unreadable entries or directories; result not saved"
                            );
                        }
                        let selected_paths: HashSet<String> = lane
                            .selected_files
                            .iter()
                            .filter_map(|&index| lane.files.get(index).cloned())
                            .collect();
                        let prior_preview = lane.image_path.clone();
                        lane.files = Arc::new(files);
                        let mut clear_pending = false;
                        if let Some(pending) = self.media_inline_video_pending_target.as_mut() {
                            if pending.requested_scan_id == scan_id
                                && pending.tab_id == self.media_tabs.active_id().as_str()
                            {
                                if let Some(index) = pending_sorted_index {
                                    pending.source_index = index;
                                    pending.checked_display_key = None;
                                } else {
                                    // The exact requested path disappeared
                                    // during reconciliation; never retarget a
                                    // neighboring sorted row.
                                    clear_pending = true;
                                }
                            }
                        }
                        if clear_pending {
                            self.media_inline_video_pending_target = None;
                        }
                        if let Some((path, path_key, source_index)) = inline_terminal_target {
                            self.media_inline_video_pending_target =
                                Some(PendingInlineVideoTarget {
                                    tab_id: self.media_tabs.active_id().as_str().to_string(),
                                    path,
                                    path_key,
                                    source_index,
                                    requested_scan_id: scan_id,
                                    checked_display_key: None,
                                });
                            self.media_inline_video_requested_at = Some(std::time::Instant::now());
                        }
                        // WP-069: publish an immediately renderable order for
                        // every batch, not only for the empty-query/Name-sort
                        // special case. Otherwise any active query or non-default
                        // sort turns a streaming folder open into a blank grid
                        // until a worker round trip finishes. The display cache
                        // KEY stays unset, so the authoritative ranked/sorted
                        // order still replaces this provisional one.
                        publish_provisional_display(
                            &mut self.media_display_cache,
                            &mut self.media_display_cache_key,
                            display_order,
                        );
                        lane.selected_files = lane
                            .files
                            .iter()
                            .enumerate()
                            .filter_map(|(index, path)| {
                                selected_paths.contains(path).then_some(index)
                            })
                            .collect();
                        lane.selection_anchor = None;
                        lane.action_message = if lane.files.is_empty() {
                            if dir_errors > 0 {
                                format!(
                                    "partial scan · no readable media · skipped {dir_errors} entries/directories · not committed"
                                )
                            } else {
                                match lane.media_filter {
                                    MediaFilterMode::ImagesOnly => {
                                        "No supported images in folder".to_string()
                                    }
                                    MediaFilterMode::VideosOnly => {
                                        "No supported videos in folder".to_string()
                                    }
                                    MediaFilterMode::All => {
                                        "No supported media in folder".to_string()
                                    }
                                }
                            }
                        } else {
                            let first = first_batch_ms
                                .map(|ms| format!("{ms} ms"))
                                .unwrap_or_else(|| "n/a".to_string());
                            match (inventory_generation, inventory_error) {
                                (Some(generation), _) => format!(
                                    "inventory generation {generation} · first batch {first} · scan {elapsed_ms} ms · inventory write {} ms",
                                    inventory_write_ms.unwrap_or_default()
                                ),
                                (_, Some(error)) => format!(
                                    "scan complete · first batch {first} · total {elapsed_ms} ms · inventory not saved: {error}"
                                ),
                                _ => format!(
                                    "partial scan · first batch {first} · total {elapsed_ms} ms · not committed"
                                ),
                            }
                        };
                        if lane.files.is_empty() {
                            lane.image_error = if dir_errors > 0 {
                                "Source scan incomplete; no readable media found".to_string()
                            } else {
                                match lane.media_filter {
                                    MediaFilterMode::ImagesOnly => {
                                        "No supported images in folder".to_string()
                                    }
                                    MediaFilterMode::VideosOnly => {
                                        "No supported videos in folder".to_string()
                                    }
                                    MediaFilterMode::All => {
                                        "No supported media in folder".to_string()
                                    }
                                }
                            };
                            lane.loading_image = false;
                            lane.image_path.clear();
                            lane.texture = None;
                            lane.texture_size = None;
                        } else if !prior_preview.is_empty()
                            && lane.files.iter().any(|path| path == &prior_preview)
                        {
                            lane.index = lane
                                .files
                                .iter()
                                .position(|path| path == &prior_preview)
                                .unwrap_or(0);
                            lane.loading_image = false;
                            lane.pending_image_index = None;
                        } else {
                            lane.image_error.clear();
                            lane.loading_image = true;
                            lane.pending_image_index = Some(0);
                            drop(lane);
                            self.start_compare_image_load(lane_id);
                        }
                        self.media_content_generation =
                            self.media_content_generation.wrapping_add(1);
                    }
                    if !self.media_display_cache.is_empty() {
                        self.mark_media_load_timing(lane_id, scan_id, MediaLoadMark::FirstRow);
                    }
                    self.restore_media_tab_selection(lane_id);
                    if self
                        .compare_lane_position(lane_id)
                        .is_some_and(|pos| self.compare_lanes[pos].pending_image_index.is_some())
                    {
                        self.start_compare_image_load(lane_id);
                    }
                }
                CompareWorkEvent::ScanError {
                    lane_id,
                    scan_id,
                    error,
                    elapsed_ms,
                    inventory_error,
                } => {
                    if let Some(pos) = self.compare_lane_position(lane_id) {
                        let lane = &mut self.compare_lanes[pos];
                        if lane.scan_id != scan_id {
                            continue;
                        }
                        self.media_scan_diagnostics.status = if lane.scan_using_cached_inventory {
                            "offline_stale_retained".to_string()
                        } else {
                            "error".to_string()
                        };
                        self.media_scan_diagnostics.elapsed_ms = Some(elapsed_ms);
                        self.media_scan_diagnostics.source_error = Some(error.clone());
                        self.media_scan_diagnostics.inventory_error = inventory_error.clone();
                        self.compare_scan_cancellations.remove(&lane_id);
                        lane.scanning = false;
                        let kept_cached = lane.scan_using_cached_inventory;
                        lane.scan_using_cached_inventory = false;
                        if kept_cached {
                            lane.scan_error = match inventory_error {
                                Some(inventory_error) => format!(
                                    "Source unavailable: {error}; visible cache retained, but inventory health also failed: {inventory_error}"
                                ),
                                None => format!(
                                    "Source unavailable: {error}; last-good inventory retained"
                                ),
                            };
                            lane.action_message = format!(
                                "offline/stale inventory · {} items · failed after {elapsed_ms} ms",
                                group_thousands(lane.files.len())
                            );
                        } else {
                            lane.loading_image_inflight = false;
                            lane.pending_image_index = None;
                            lane.scan_error = match inventory_error {
                                Some(inventory_error) => format!(
                                    "{error} ({elapsed_ms} ms); last-good inventory unavailable: {inventory_error}"
                                ),
                                None => format!("{error} ({elapsed_ms} ms)"),
                            };
                            lane.files = Arc::new(Vec::new());
                            lane.image_path.clear();
                            lane.loading_image = false;
                            lane.texture = None;
                            lane.texture_size = None;
                        }
                    }
                }
                CompareWorkEvent::ImageDone {
                    lane_id,
                    load_id,
                    path,
                    width,
                    height,
                    pixels,
                } => {
                    let Some(pos) = self.compare_lane_position(lane_id) else {
                        continue;
                    };
                    let has_pending = {
                        let lane = &mut self.compare_lanes[pos];
                        // `load_id` identifies the in-flight load we started; a mismatch
                        // means a newer load superseded this one — ignore it.
                        if lane.load_id != load_id {
                            continue;
                        }
                        // The in-flight load finished: free the slot unconditionally so a
                        // fast scroll that moved the target can never strand
                        // `loading_image_inflight` true (the freeze-on-scroll bug).
                        lane.loading_image_inflight = false;
                        // Apply only if this is still the lane's current target; otherwise
                        // drop the pixels and let the pending load fetch the new target.
                        if lane.image_path == path {
                            if width == 0 || height == 0 {
                                lane.image_error = "Empty image".to_string();
                                lane.texture = None;
                                lane.texture_size = None;
                            } else {
                                lane.image_error.clear();
                                let color_image =
                                    ColorImage::from_rgba_unmultiplied([width, height], &pixels);
                                lane.texture = Some(ctx.load_texture(
                                    format!("compare_lane_{}_{}", lane_id, load_id),
                                    color_image,
                                    TextureOptions::LINEAR,
                                ));
                                lane.texture_size = Some([width, height]);
                            }
                        }
                        let has_pending = lane.pending_image_index.is_some();
                        lane.loading_image = has_pending;
                        has_pending
                    };
                    if has_pending {
                        self.start_compare_image_load(lane_id);
                    }
                }
                CompareWorkEvent::ImageError {
                    lane_id,
                    load_id,
                    path,
                    error,
                } => {
                    self.handle_compare_events_image_error(lane_id, load_id, path, error);
                }
                CompareWorkEvent::MediaMoveDone {
                    lane_id,
                    destination,
                    sources,
                    moved,
                    failures,
                } => {
                    let source_set: HashSet<&str> = sources.iter().map(String::as_str).collect();
                    // Same-folder cut-paste no-ops return their source path;
                    // count only files that actually changed location.
                    let really_moved = moved
                        .iter()
                        .filter(|target| !source_set.contains(target.to_string_lossy().as_ref()))
                        .count();
                    self.compare_action_message = if failures.is_empty() {
                        if really_moved == 0 {
                            "Files are already in this folder — nothing moved".to_string()
                        } else {
                            format!("Moved {really_moved} file(s)")
                        }
                    } else {
                        format!(
                            "Moved {really_moved} file(s); {} failed: {}",
                            failures.len(),
                            failures
                                .iter()
                                .map(|(path, error)| {
                                    let name = Path::new(path)
                                        .file_name()
                                        .and_then(|value| value.to_str())
                                        .unwrap_or(path);
                                    format!("{name} ({error})")
                                })
                                .collect::<Vec<_>>()
                                .join("; ")
                        )
                    };
                    // WP-074: publish structured per-file results. A note is
                    // not proof (CODEX 8.3), and a model driving move_to could
                    // otherwise not tell success from silent failure.
                    let failed_set: HashSet<&str> =
                        failures.iter().map(|(path, _)| path.as_str()).collect();
                    let relocated: Vec<PathBuf> = moved
                        .iter()
                        .filter(|target| !source_set.contains(target.to_string_lossy().as_ref()))
                        .cloned()
                        .collect();
                    let relocated_sources: Vec<String> = sources
                        .iter()
                        .filter(|path| {
                            !failed_set.contains(path.as_str())
                                && !moved
                                    .iter()
                                    .any(|target| target.as_os_str() == path.as_str())
                        })
                        .cloned()
                        .collect();
                    self.media_file_op_report = Some(MediaFileOpReport {
                        operation: "move".to_string(),
                        destination: destination.clone(),
                        settled: true,
                        requested: sources.len(),
                        succeeded: really_moved,
                        skipped_same_folder: sources.len() - failures.len() - really_moved,
                        failed: failures.clone(),
                        results: relocated_sources
                            .iter()
                            .cloned()
                            .zip(
                                relocated
                                    .iter()
                                    .map(|target| target.to_string_lossy().to_string()),
                            )
                            .collect(),
                    });
                    // WP-074: files that actually left this folder must leave
                    // the grid too. Without this the moved rows linger until a
                    // manual refresh and a later action targets missing files.
                    let removed: HashSet<String> = relocated_sources.into_iter().collect();
                    if !removed.is_empty() {
                        let is_active_media_lane =
                            self.compare_lanes.first().map(|lane| lane.id) == Some(lane_id);
                        if is_active_media_lane {
                            if let Some(pos) = self.compare_lane_position(lane_id) {
                                let old_files = Arc::clone(&self.compare_lanes[pos].files);
                                let new_display = remap_display_after_removal(
                                    &old_files,
                                    &self.media_display_cache,
                                    &removed,
                                );
                                self.media_content_generation =
                                    self.media_content_generation.wrapping_add(1);
                                self.media_display_cache = Arc::new(new_display);
                                if let Some(key) = self.media_display_cache_key.as_mut() {
                                    if key.lane_id == lane_id {
                                        key.content_generation = self.media_content_generation;
                                    }
                                }
                            }
                        }
                        let dropped = self.compare_lane_remove_paths(lane_id, &removed);
                        if is_active_media_lane && dropped > 0 {
                            self.cache_active_media_tab_inventory();
                        }
                    }
                    let destination_is_active =
                        self.compare_lane_position(lane_id).is_some_and(|position| {
                            sanitize_folder_input(&self.compare_lanes[position].folder)
                                == destination
                        });
                    if destination_is_active {
                        self.start_compare_scan(lane_id);
                    }
                }
                CompareWorkEvent::MediaDeleteDone {
                    lane_id,
                    job_id,
                    outcomes,
                } => {
                    self.apply_media_delete_outcomes(lane_id, job_id, outcomes);
                }
                CompareWorkEvent::MediaCopyDone {
                    lane_id,
                    destination,
                    copied,
                    failures,
                } => {
                    self.media_file_op_report = Some(MediaFileOpReport {
                        operation: "copy".to_string(),
                        destination: destination.clone(),
                        settled: true,
                        requested: copied.len() + failures.len(),
                        succeeded: copied.len(),
                        skipped_same_folder: 0,
                        failed: failures.clone(),
                        results: copied
                            .iter()
                            .map(|target| {
                                (
                                    target
                                        .file_name()
                                        .and_then(|value| value.to_str())
                                        .unwrap_or_default()
                                        .to_string(),
                                    target.to_string_lossy().to_string(),
                                )
                            })
                            .collect(),
                    });
                    let message = if failures.is_empty() {
                        format!("Copied {} file(s) to {destination}", copied.len())
                    } else {
                        format!(
                            "Copied {} file(s) to {destination}; {} failed: {}",
                            copied.len(),
                            failures.len(),
                            failures
                                .iter()
                                .take(3)
                                .map(|(path, error)| {
                                    let name = Path::new(path)
                                        .file_name()
                                        .and_then(|value| value.to_str())
                                        .unwrap_or(path);
                                    format!("{name} ({error})")
                                })
                                .collect::<Vec<_>>()
                                .join("; ")
                        )
                    };
                    self.compare_action_message = message.clone();
                    self.set_compare_lane_message(lane_id, message);
                    // Copying into the folder this lane is showing adds rows,
                    // so that lane (and only that lane) rescans.
                    let destination_is_active =
                        self.compare_lane_position(lane_id).is_some_and(|position| {
                            sanitize_folder_input(&self.compare_lanes[position].folder)
                                == destination
                        });
                    if destination_is_active {
                        self.start_compare_scan(lane_id);
                    }
                }
                CompareWorkEvent::MediaSheetExported { lane_id, report } => {
                    let message = if report.error.is_empty() {
                        format!(
                            "Contact sheet written: {} ({} of {} tiles)",
                            report.output_path, report.rendered, report.requested
                        )
                    } else {
                        format!("Contact sheet failed: {}", report.error)
                    };
                    self.media_sheet_export = Some(report);
                    self.compare_action_message = message.clone();
                    self.set_compare_lane_message(lane_id, message);
                }
                CompareWorkEvent::AnchorsLoaded { items, error } => {
                    self.compare_anchors_loading = false;
                    self.compare_anchor_error = error.unwrap_or_default();
                    self.compare_anchor_thumbs = items
                        .into_iter()
                        .enumerate()
                        .map(|(i, (name, w, h, rgba))| {
                            let color = ColorImage::from_rgba_unmultiplied([w, h], &rgba);
                            let tex = ctx.load_texture(
                                format!("anchor_{i}_{name}"),
                                color,
                                TextureOptions::LINEAR,
                            );
                            (name, tex)
                        })
                        .collect();
                }
                CompareWorkEvent::MatchSnapshotReady(result) => {
                    self.match_snapshot_loading = false;
                    match result {
                        Ok((snapshot, public_snapshot)) => {
                            self.invalidate_media_person_search_index();
                            self.refresh_active_match_person_gallery(Some(ctx.clone()));
                            self.match_people_offset = snapshot
                                .pointer("/catalog/offset")
                                .and_then(|value| value.as_u64())
                                .and_then(|value| usize::try_from(value).ok())
                                .unwrap_or(self.match_people_offset);
                            self.match_snapshot = snapshot;
                            self.match_public_snapshot = public_snapshot;
                            self.match_message = "Match state refreshed".to_string();
                        }
                        Err(error) => self.match_message = error,
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MatchClusterReviewReady {
                    command,
                    generation,
                    result,
                } => {
                    self.match_video_ui.busy = false;
                    let current = generation == self.match_video_ui.generation
                        && self.match_video_scope_is_current(&self.match_video_ui.media_key);
                    match result {
                        Ok(value) => {
                            if current {
                                self.match_video_ui.cluster_review = value.clone();
                            }
                            self.finish_background_match_intent(
                                command,
                                true,
                                "Explicit selection reviewed; identity unchanged".into(),
                                value,
                            );
                        }
                        Err(error) => {
                            self.finish_background_match_intent(
                                command,
                                false,
                                error,
                                serde_json::Value::Null,
                            );
                        }
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MatchInspectionReady {
                    command,
                    generation,
                    result,
                } => {
                    self.finish_match_inspection(ctx, command, generation, result);
                    ctx.request_repaint();
                }
                CompareWorkEvent::MatchNativeSeekReady {
                    command,
                    generation,
                    result,
                } => {
                    let (result, pin) = match result {
                        Ok((value, pin)) => (Ok(value), Some(pin)),
                        Err(error) => (Err(error), None),
                    };
                    self.finish_match_video_request(command, generation, result, pin);
                    ctx.request_repaint();
                }
                CompareWorkEvent::MatchVideoReady {
                    command,
                    generation,
                    result,
                } => {
                    self.finish_match_video_request(command, generation, result, None);
                    ctx.request_repaint();
                }
                CompareWorkEvent::MatchHoldsReconciled { epoch, result } => {
                    if acknowledge_match_hold_reconciliation(
                        &mut self.match_hold_reconcile_inflight,
                        &mut self.match_hold_reconciled_epoch,
                        epoch,
                    ) {
                        if let Err(error) = result {
                            self.match_message = error;
                        }
                    }
                }
                CompareWorkEvent::MatchSettingsSnapshotReady(result) => {
                    self.match_snapshot_loading = false;
                    match result {
                        Ok(snapshot) => {
                            self.match_settings_offset = snapshot
                                .pointer("/page/offset")
                                .and_then(|value| value.as_u64())
                                .and_then(|value| usize::try_from(value).ok())
                                .unwrap_or(self.match_settings_offset);
                            self.match_settings_snapshot = snapshot;
                            self.match_message = "Match processing state refreshed".to_string();
                        }
                        Err(error) => self.match_message = error,
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MatchGalleryReady { navigation, result } => {
                    self.match_snapshot_loading = false;
                    if !self.match_navigation_is_current(&navigation) {
                        self.match_message = match result {
                            Ok(_) => "Person gallery loaded; presentation skipped after navigation"
                                .into(),
                            Err(error) => error,
                        };
                        ctx.request_repaint();
                        continue;
                    }
                    match result {
                        Ok(gallery) => {
                            self.match_gallery_offset =
                                gallery["offset"].as_u64().unwrap_or(0) as usize;
                            self.match_gallery_snapshot = gallery.clone();
                            let person_id = gallery["person"]["person_id"]
                                .as_str()
                                .unwrap_or_default()
                                .to_string();
                            let person_name = gallery["person"]["name"]
                                .as_str()
                                .unwrap_or("Unnamed")
                                .to_string();
                            let media_paths = match_gallery_media_paths(&gallery);
                            match self.open_match_person_gallery(
                                &person_id,
                                &person_name,
                                media_paths,
                            ) {
                                Ok(message) => {
                                    let tab_id = self.media_tabs.active_id().as_str().to_string();
                                    self.request_match_gallery_inventory(
                                        Some(ctx.clone()),
                                        tab_id,
                                        person_id,
                                    );
                                    self.match_message = message;
                                }
                                Err(error) => self.match_message = error,
                            }
                        }
                        Err(error) => self.match_message = error,
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MatchGalleryInventoryReady {
                    tab_id,
                    person_id,
                    request_generation,
                    result,
                } => {
                    if self.match_gallery_inventory_inflight.get(&tab_id)
                        != Some(&request_generation)
                    {
                        continue;
                    }
                    self.match_gallery_inventory_inflight.remove(&tab_id);
                    match result {
                        Ok(crate::match_store::PersonGalleryInventoryOutcome::Present(
                            inventory,
                        )) => {
                            if let Err(error) =
                                self.apply_match_gallery_inventory(&tab_id, &person_id, inventory)
                            {
                                self.match_message = error;
                            }
                        }
                        Ok(crate::match_store::PersonGalleryInventoryOutcome::Missing {
                            person_id: missing_id,
                            identity_revision,
                            catalog_revision,
                        }) => {
                            if missing_id == person_id {
                                if let Err(error) = self.clear_missing_match_gallery(
                                    &tab_id,
                                    &person_id,
                                    identity_revision,
                                    catalog_revision,
                                ) {
                                    self.match_message = error;
                                }
                            }
                        }
                        Err(error) => self.match_message = error,
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MatchViewerSnapshotReady { media_key, result } => {
                    self.match_viewer_snapshot_loading = false;
                    if self.match_viewer_snapshot_key.as_deref() == Some(media_key.as_str()) {
                        match result {
                            Ok(snapshot) => {
                                self.match_viewer_snapshot = snapshot;
                                self.compare_action_message =
                                    "Match faces refreshed successfully".to_string();
                            }
                            Err(error) => {
                                self.compare_action_message = format!(
                                    "Match face refresh failed: {error}. Use Retry refresh."
                                );
                                self.match_viewer_snapshot = serde_json::json!({
                                    "configured": false,
                                    "rows": [],
                                    "error": error,
                                });
                            }
                        }
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MatchAutocompleteReady { request, result } => {
                    if self
                        .match_autocomplete_request
                        .as_ref()
                        .is_some_and(|current| current.generation == request.generation)
                        && self.match_navigation_is_current(&request.navigation)
                        && self.match_face_editor.media_key() == Some(request.media_key.as_str())
                        && self.match_face_editor.selected_face_id() == request.face_id.as_deref()
                        && self.match_face_editor.autocomplete_query().trim() == request.query
                    {
                        let failed = result.is_err();
                        self.match_autocomplete_loading = false;
                        self.match_autocomplete_results = result.unwrap_or_else(
                            |error| serde_json::json!({"error": error, "rows": []}),
                        );
                        if let Some(pending) = self.pending_match_ui_endpoint.as_mut() {
                            if pending.autocomplete_generation == request.generation {
                                pending.ready = true;
                                pending.failed = failed;
                            }
                        }
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MatchRuntimeDiagnosticsReady { action_id, result } => {
                    if self
                        .pending_match_runtime_diagnostics
                        .as_ref()
                        .is_some_and(|(command, _, _)| command.action_id == action_id)
                    {
                        let (command, started, terminal) =
                            self.pending_match_runtime_diagnostics.take().unwrap();
                        if terminal {
                            continue;
                        }
                        let success =
                            result.is_ok() && started.elapsed() < std::time::Duration::from_secs(2);
                        let mut snapshot = if success {
                            result.unwrap()
                        } else {
                            serde_json::Value::Null
                        };
                        if success {
                            snapshot["visible_work"] = self.visible_work_snapshot();
                            snapshot["runtime_evidence"]["native_playback"] = self
                                .video_player
                                .native_playback_samples(std::time::Instant::now());
                            snapshot["runtime_evidence"]["captured_at_us"] = serde_json::json!(
                                crate::runtime_evidence::timestamp(std::time::Instant::now())
                            );
                        }
                        self.finish_match_runtime_diagnostics(command, success,
                            if success { "Live Match runtime diagnostics collected" } else { "Live Match runtime diagnostics unavailable" }.to_string(),
                            serde_json::json!({"endpoint_scope":"running_gui_governor_lifetime","snapshot":snapshot}));
                    }
                }
                CompareWorkEvent::MatchDiagnosticsPersistenceReady { action_id, error } => {
                    if let Some(error) = error {
                        let current = self
                            .last_receipt
                            .as_ref()
                            .and_then(|raw| serde_json::from_str::<serde_json::Value>(raw).ok())
                            .is_some_and(|receipt| {
                                receipt["action_id"].as_str() == Some(action_id.as_str())
                            });
                        if current {
                            self.last_applied_action = Some(format!("{action_id} diagnostics persistence_error={error}; processing claim retained for recovery"));
                        }
                        eprintln!("Match diagnostics persistence failed: {error}");
                    }
                }
                CompareWorkEvent::MatchIntentReady {
                    command,
                    navigation,
                    result,
                } => {
                    self.pending_match_model_intent = None;
                    self.match_snapshot_loading = false;
                    if self.match_rendered_intent_inflight.as_deref()
                        == Some(command.action_id.as_str())
                    {
                        self.match_rendered_intent_inflight = None;
                        self.apply_match_rendered_intent_outcome(ctx, command, navigation, result);
                        continue;
                    }
                    let presentation_current = self.match_navigation_is_current(&navigation);
                    match result {
                        Ok(mut outcome) => {
                            if !presentation_current {
                                outcome.ui_snapshot = None;
                                outcome.settings_snapshot = None;
                                outcome.gallery = None;
                                outcome.viewer_snapshot = None;
                                outcome.person_faces_snapshot = None;
                                outcome
                                    .message
                                    .push_str("; presentation skipped after navigation");
                                if let Some(result) = outcome.terminal_result.as_object_mut() {
                                    result.insert("presentation_applied".into(), false.into());
                                    result.insert(
                                        "presentation_reason".into(),
                                        "navigation_changed".into(),
                                    );
                                }
                            }
                            self.invalidate_media_person_search_index();
                            self.refresh_active_match_person_gallery(Some(ctx.clone()));
                            self.match_public_snapshot = outcome.public_result.clone();
                            if let Some(snapshot) = outcome.ui_snapshot {
                                self.match_people_offset = snapshot
                                    .pointer("/catalog/offset")
                                    .and_then(|value| value.as_u64())
                                    .and_then(|value| usize::try_from(value).ok())
                                    .unwrap_or(self.match_people_offset);
                                self.match_snapshot = snapshot;
                            }
                            if let Some(snapshot) = outcome.settings_snapshot {
                                self.match_settings_offset = snapshot
                                    .pointer("/page/offset")
                                    .and_then(|value| value.as_u64())
                                    .and_then(|value| usize::try_from(value).ok())
                                    .unwrap_or(self.match_settings_offset);
                                self.match_settings_snapshot = snapshot;
                            }
                            if let Some(gallery) = outcome.gallery {
                                self.match_gallery_offset =
                                    gallery["offset"].as_u64().unwrap_or(0) as usize;
                                self.match_gallery_snapshot = gallery.clone();
                                let person_id = gallery["person"]["person_id"]
                                    .as_str()
                                    .unwrap_or_default()
                                    .to_string();
                                let person_name = gallery["person"]["name"]
                                    .as_str()
                                    .unwrap_or("Unnamed")
                                    .to_string();
                                let media_paths = match_gallery_media_paths(&gallery);
                                if let Err(error) = self.open_match_person_gallery(
                                    &person_id,
                                    &person_name,
                                    media_paths,
                                ) {
                                    self.match_message = error.clone();
                                    self.finish_background_match_intent(
                                        command,
                                        false,
                                        error,
                                        serde_json::Value::Null,
                                    );
                                    ctx.request_repaint();
                                    continue;
                                }
                                let tab_id = self.media_tabs.active_id().as_str().to_string();
                                self.request_match_gallery_inventory(
                                    Some(ctx.clone()),
                                    tab_id,
                                    person_id,
                                );
                            }
                            if let Some((media_key, snapshot)) = outcome.viewer_snapshot {
                                if self.match_viewer_snapshot_key.as_deref()
                                    == Some(media_key.as_str())
                                    && self.active_tab == Tab::Media
                                    && !self.media_explorer.show_settings
                                    && !self.media_explorer.chrome_hidden
                                {
                                    self.match_viewer_snapshot = snapshot;
                                    self.match_viewer_snapshot_loading = false;
                                    if let Err(error) = self.match_face_editor.enter(&media_key) {
                                        self.match_message = error;
                                    }
                                }
                            }
                            if let Some((person_id, snapshot)) = outcome.person_faces_snapshot {
                                self.active_tab = Tab::Match;
                                self.match_subview = MatchSubview::People;
                                self.match_selected_person = Some(person_id);
                                self.match_selected_faces.clear();
                                self.match_single_face_look_id = None;
                                self.match_single_face_new_look_name.clear();
                                self.match_person_faces_offset = snapshot["offset"]
                                    .as_u64()
                                    .and_then(|value| usize::try_from(value).ok())
                                    .unwrap_or_default();
                                self.match_person_faces_snapshot = snapshot;
                                self.match_person_faces_loading = false;
                                self.clear_match_person_edit_preflights();
                                let _ = self.request_match_person_edit_preflights(ctx);
                                self.clear_match_split_preflight();
                                let _ = self.request_match_split_preflight(ctx);
                            }
                            self.match_message = outcome.message.clone();
                            self.finish_background_match_intent(
                                command,
                                true,
                                outcome.message,
                                outcome.terminal_result,
                            );
                        }
                        Err(error) => {
                            self.match_message = error.clone();
                            self.finish_background_match_intent(
                                command,
                                false,
                                error,
                                serde_json::Value::Null,
                            );
                        }
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MatchMaintenanceReady { command, result } => {
                    self.pending_match_model_intent = None;
                    self.match_snapshot_loading = false;
                    match result {
                        Ok(receipt) => {
                            self.invalidate_media_person_search_index();
                            self.refresh_active_match_person_gallery(Some(ctx.clone()));
                            self.match_message =
                                match_maintenance_success_message(&command, &receipt);
                            self.compare_action_message = self.match_message.clone();
                            self.finish_background_match_intent(
                                command,
                                true,
                                self.match_message.clone(),
                                receipt,
                            );
                            self.request_match_snapshot(ctx);
                            self.request_match_settings_snapshot(ctx);
                        }
                        Err(error) => {
                            self.match_message = error.clone();
                            self.compare_action_message = error.clone();
                            self.finish_background_match_intent(
                                command,
                                false,
                                error,
                                serde_json::Value::Null,
                            );
                        }
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MatchCorrectionReady { command, result } => {
                    self.pending_match_model_intent = None;
                    self.queued_match_correction_intent = None;
                    self.match_snapshot_loading = false;
                    match result {
                        Ok(outcome) => {
                            self.invalidate_media_person_search_index();
                            self.refresh_active_match_person_gallery(Some(ctx.clone()));
                            self.match_public_snapshot = outcome.public_result;
                            self.clear_match_person_edit_preflights();
                            self.clear_match_split_preflight();
                            self.clear_match_batch_preflights();
                            if let Some((media_key, snapshot)) = outcome.viewer_snapshot {
                                if self.match_viewer_snapshot_key.as_deref()
                                    == Some(media_key.as_str())
                                {
                                    self.match_viewer_snapshot = snapshot;
                                    self.match_viewer_snapshot_loading = false;
                                }
                            }
                            self.match_message = outcome.message.clone();
                            self.compare_action_message = outcome.message.clone();
                            self.finish_background_match_intent(
                                command,
                                true,
                                outcome.message,
                                outcome.result,
                            );
                            if let Some(person_id) = self.match_selected_person.clone() {
                                self.match_selected_faces.clear();
                                self.match_single_face_look_id = None;
                                self.match_single_face_new_look_name.clear();
                                self.match_person_faces_offset = 0;
                                let _ = self.request_match_person_faces(ctx, person_id);
                            }
                            self.request_match_snapshot(ctx);
                        }
                        Err(error) => {
                            let stale = {
                                let normalized = error.to_ascii_lowercase();
                                normalized.contains("stale")
                                    || normalized.contains("revision")
                                    || normalized.contains("conflict")
                            };
                            self.match_message = if stale {
                                format!("{error}; refreshing current Match state")
                            } else {
                                error.clone()
                            };
                            self.compare_action_message =
                                format!("Match correction failed: {}", self.match_message);
                            self.finish_background_match_intent(
                                command,
                                false,
                                error.clone(),
                                serde_json::Value::Null,
                            );
                            if stale {
                                let viewer_media_key = self.match_viewer_snapshot_key.clone();
                                self.match_viewer_snapshot_loading = viewer_media_key.is_some();
                                self.defer_match_action(move |app, ctx| {
                                    app.request_match_snapshot(ctx);
                                    if let Some(media_key) = viewer_media_key {
                                        app.request_match_viewer_snapshot(ctx, media_key);
                                    }
                                });
                            }
                        }
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MatchBatchCorrectionPreflightCommandReady { command, result } => {
                    self.pending_match_model_intent = None;
                    self.match_snapshot_loading = false;
                    match result {
                        Ok(preview) => {
                            let preview_id = preview["preview_id"].as_str().unwrap_or("missing");
                            let message = format!(
                                "Exact batch correction preflight completed; preview_id={preview_id}"
                            );
                            self.match_message = message.clone();
                            self.finish_background_match_intent(command, true, message, preview);
                        }
                        Err(error) => {
                            self.match_message =
                                format!("Batch correction preflight failed: {error}");
                            self.finish_background_match_intent(
                                command,
                                false,
                                error,
                                serde_json::Value::Null,
                            );
                        }
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MatchSplitPersonPreflightCommandReady { command, result } => {
                    self.pending_match_model_intent = None;
                    self.match_snapshot_loading = false;
                    match result {
                        Ok(preview) => {
                            let preview_id = preview["preview_id"].as_str().unwrap_or("missing");
                            let message = format!(
                                "Exact split Person preflight completed; preview_id={preview_id}"
                            );
                            self.match_message = message.clone();
                            self.finish_background_match_intent(command, true, message, preview);
                        }
                        Err(error) => {
                            self.match_message = format!("Split Person preflight failed: {error}");
                            self.finish_background_match_intent(
                                command,
                                false,
                                error,
                                serde_json::Value::Null,
                            );
                        }
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MatchPersonFacesReady { person_id, result } => {
                    self.match_person_faces_loading = false;
                    if self.match_selected_person.as_deref() == Some(person_id.as_str()) {
                        match result {
                            Ok(snapshot) => {
                                self.match_person_faces_snapshot = snapshot;
                                self.clear_match_person_edit_preflights();
                                let _ = self.request_match_person_edit_preflights(ctx);
                                self.clear_match_split_preflight();
                                let _ = self.request_match_split_preflight(ctx);
                                self.clear_match_batch_preflights();
                                let _ = self.request_match_batch_preflights(ctx);
                            }
                            Err(error) => {
                                self.match_message = format!("Match face page failed: {error}");
                                self.match_person_faces_snapshot = serde_json::Value::Null;
                                self.clear_match_person_edit_preflights();
                                self.clear_match_split_preflight();
                                self.clear_match_batch_preflights();
                            }
                        }
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MatchPersonEditPreflightsReady { key, result } => {
                    if self.current_match_person_edit_preflight_key().as_ref() == Some(&key)
                        && self.match_person_edit_preflight_key.as_ref() == Some(&key)
                    {
                        self.match_person_edit_preflight_loading = false;
                        match result {
                            Ok(preflights) => {
                                self.match_person_edit_preflights = preflights;
                                self.match_person_edit_preflight_error = None;
                            }
                            Err(error) => {
                                self.match_person_edit_preflights = serde_json::Value::Null;
                                self.match_person_edit_preflight_error = Some(error.clone());
                                self.match_message = format!("Person edit preview failed: {error}");
                            }
                        }
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MatchSplitPreflightReady { key, result } => {
                    if self.current_match_split_preflight_key().as_ref() == Some(&key)
                        && self.match_split_preflight_key.as_ref() == Some(&key)
                    {
                        self.match_split_preflight_loading = false;
                        match result {
                            Ok(preview) => {
                                self.match_split_preflight = preview;
                                self.match_split_preflight_error = None;
                            }
                            Err(error) => {
                                self.match_split_preflight = serde_json::Value::Null;
                                self.match_split_preflight_error = Some(error.clone());
                                self.match_message = format!("Split preview failed: {error}");
                            }
                        }
                    }
                    ctx.request_repaint();
                }
                CompareWorkEvent::MatchBatchPreflightsReady { key, result } => {
                    if self.current_match_batch_preflight_key().as_ref() == Some(&key)
                        && self.match_batch_preflight_key.as_ref() == Some(&key)
                    {
                        self.match_batch_preflight_loading = false;
                        match result {
                            Ok(previews) => {
                                self.match_batch_preflights = previews;
                                self.match_batch_preflight_error = None;
                            }
                            Err(error) => {
                                self.match_batch_preflights.clear();
                                self.match_batch_preflight_error = Some(error.clone());
                                self.match_message = format!("Batch previews failed: {error}");
                            }
                        }
                    }
                    ctx.request_repaint();
                }
            }
        }
    }

    fn handle_compare_events_image_error(
        &mut self,
        lane_id: usize,
        load_id: u64,
        path: String,
        error: String,
    ) {
        let Some(pos) = self.compare_lane_position(lane_id) else {
            return;
        };
        let has_pending = {
            let lane = &mut self.compare_lanes[pos];
            // Mismatched load_id -> a newer load owns the slot; ignore this result.
            if lane.load_id != load_id {
                return;
            }
            lane.loading_image_inflight = false;
            // Only surface the error if it is still the current target; a superseded
            // failure is replaced by the pending load below.
            if lane.image_path == path {
                lane.image_error = error;
                lane.texture = None;
                lane.texture_size = None;
            }
            let has_pending = lane.pending_image_index.is_some();
            lane.loading_image = has_pending;
            has_pending
        };
        if has_pending {
            self.start_compare_image_load(lane_id);
        }
    }

    fn ingest_images(&mut self, paths: Vec<String>) {
        let image_list: Vec<String> = paths
            .into_iter()
            .map(|path| path.trim().to_string())
            .filter(|path| !path.is_empty())
            .collect();
        if image_list.is_empty() {
            self.import_summary = "No paths entered to import".to_string();
            return;
        }
        let result = if let Ok(mut svc) = self.service.lock() {
            svc.ingest_images(&self.project_name, &image_list, self.in_place)
        } else {
            Vec::new()
        };

        let successes = result.iter().filter(|entry| entry.ok).count();
        let failures = result.len().saturating_sub(successes);
        let mode_hint = result
            .first()
            .map(|item| item.mode.clone())
            .unwrap_or_else(|| "n/a".to_string());
        self.import_summary =
            format!("imported {successes} images, failed {failures}, mode {mode_hint}");
        self.last_import_images = result
            .into_iter()
            .filter(|item| item.ok)
            .map(|item| item.destination)
            .collect();
        self.pipeline_status = if successes > 0 {
            format!("{successes} images ready for pipeline")
        } else {
            "no valid images imported".to_string()
        };

        if let Some(first) = self.last_import_images.first() {
            if let Some(parent) = PathBuf::from(first)
                .parent()
                .and_then(|value| value.parent())
            {
                self.worktree_path = parent.to_string_lossy().to_string();
            }
        }

        match Arc::clone(&self.service).lock() {
            Ok(mut svc) => {
                self.worktree_view = Self::load_worktrees(&mut svc);
            }
            Err(_) => {}
        }
    }

    fn execute_pipeline(&mut self) {
        if self.running_pipeline || self.selected_features.is_empty() {
            self.pipeline_status = if self.selected_features.is_empty() {
                "No feature selected".to_string()
            } else {
                "pipeline already running".to_string()
            };
            return;
        }

        let mut feature_keys: Vec<String> = self.selected_features.iter().cloned().collect();
        feature_keys.sort();

        let mut images = self.last_import_images.clone();
        if images.is_empty() && self.worktree_path != "no worktree yet" {
            images = collect_image_paths(&PathBuf::from(&self.worktree_path));
            self.last_import_images = images.clone();
        }
        if images.is_empty() {
            self.pipeline_status = "No images available".to_string();
            return;
        }

        let project_name = self.project_name.clone();
        let worktree = self.worktree_path.clone();
        let in_place = self.in_place;
        let service = Arc::clone(&self.service);
        let sender = self.tx.clone();
        self.running_pipeline = true;
        self.pipeline_status = "pipeline started".to_string();

        thread::spawn(move || {
            // Panic boundary: a panic inside run_pipeline must never leave the UI
            // wedged. Convert any panic into a failed run result and ALWAYS send
            // PipelineDone so running_pipeline is reset on the UI thread.
            let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                if let Ok(mut svc) = service.lock() {
                    svc.run_pipeline(
                        &project_name,
                        &images,
                        &feature_keys,
                        Some(worktree),
                        in_place,
                    )
                } else {
                    Err("service lock failure".to_string())
                }
            }));
            let result = match outcome {
                Ok(result) => result,
                Err(panic) => {
                    let detail = panic
                        .downcast_ref::<&str>()
                        .map(|s| s.to_string())
                        .or_else(|| panic.downcast_ref::<String>().cloned())
                        .unwrap_or_else(|| "unknown panic".to_string());
                    Err(format!("pipeline panicked: {detail}"))
                }
            };
            let _ = sender.send(AppEvent::PipelineDone(result));
        });
    }

    fn handle_events(&mut self, ctx: &egui::Context) {
        self.handle_compare_events(ctx);
        loop {
            let event = match self.rx.try_recv() {
                Ok(event) => event,
                Err(mpsc::TryRecvError::Empty) => break,
                Err(mpsc::TryRecvError::Disconnected) => {
                    // The result channel is gone (worker dropped without sending);
                    // never leave the UI wedged with running_pipeline stuck true.
                    if self.running_pipeline {
                        self.running_pipeline = false;
                        self.pipeline_status = "pipeline result channel disconnected".to_string();
                    }
                    break;
                }
            };
            match event {
                AppEvent::PipelineDone(result) => {
                    self.running_pipeline = false;
                    match result {
                        Ok(summary) => {
                            self.pipeline_status = format!(
                                "run {} completed: status={} ok={} failed={}",
                                summary.run_id,
                                summary.status,
                                summary.totals.get("ok").copied().unwrap_or(0),
                                summary.totals.get("failed").copied().unwrap_or(0)
                            );
                            self.run_output = summary.output_path.clone();
                            self.worktree_path = summary.worktree;
                            let mut lines = vec![
                                format!("run_id={}", summary.run_id),
                                format!("status={}", summary.status),
                                format!("output={}", summary.output_path),
                                format!("features={}", summary.feature_keys.join(",")),
                                format!("images={}", summary.images.len()),
                            ];
                            for plugin in summary.plugin_results {
                                lines.push(format!(
                                    "{}::{} -> {} ({})",
                                    plugin.plugin_id,
                                    plugin.feature_id,
                                    plugin.status,
                                    plugin.message
                                ));
                                for artifact in &plugin.artifacts {
                                    lines.push(format!("    artifact: {artifact}"));
                                }
                            }
                            self.run_summary = lines.join("\n");
                        }
                        Err(err) => {
                            self.pipeline_status = format!("pipeline failed: {err}");
                        }
                    }
                }
            }
        }
        // Only rebuild the debug-event string when the Run & Debug tab (its sole
        // consumer) is showing. Doing this every frame on every tab locked the
        // service and formatted up to 800 events per frame -> idle CPU spin.
        if self.active_tab == Tab::RunDebug {
            if let Ok(mut svc) = self.service.lock() {
                let limit = svc.max_debug_events();
                let events = svc.get_recent_events(limit);
                let mut lines = String::new();
                for event in events {
                    lines.push_str(&format!(
                        "[{}] {} {} - {}\n",
                        event.ts, event.level, event.source, event.message
                    ));
                }
                self.debug_lines = lines;
            }
        }
    }

    /// Poll the controller into bound action fires (WP-046). Every pad
    /// binding is edge-triggered with hold-repeat for navigation actions;
    /// the left stick integrates into smooth row scrolling. Also services an
    /// armed pad rebind capture. Returns (fired actions, stick scroll rows).
    fn media_poll_controller(
        &mut self,
        app_focused: bool,
    ) -> (Vec<crate::media_input::MediaAction>, isize) {
        use crate::media_input::{
            stick_scroll_velocity, CaptureSlot, PadAxisCode, PadButtonCode, PadInput,
        };
        if !self.controller_input_enabled {
            return (Vec::new(), 0);
        }
        let mut snapshot = None;
        if let Some(gilrs) = self.controller_gilrs.as_mut() {
            while let Some(event) = gilrs.next_event() {
                match event.event {
                    EventType::Connected => {
                        self.controller_active = Some(event.id);
                        self.media_repeat.clear();
                    }
                    EventType::Disconnected => {
                        if self.controller_active == Some(event.id) {
                            self.controller_active = None;
                        }
                        self.media_repeat.clear();
                    }
                    _ => {}
                }
            }
            let gamepad_id = self
                .controller_active
                .or_else(|| gilrs.gamepads().next().map(|(id, _)| id));
            self.controller_active = gamepad_id;
            if let Some(gamepad_id) = gamepad_id {
                if let Some(gamepad) = gilrs.connected_gamepad(gamepad_id) {
                    snapshot = Some(crate::media_input::ControllerSnapshot::from_gilrs(
                        gamepad_id, &gamepad,
                    ));
                }
            }
        }
        if snapshot.is_none() {
            snapshot = self.controller_legacy.poll();
        }
        self.controller_legacy_active = snapshot
            .as_ref()
            .is_some_and(|state| state.source == "winmm-directinput-fallback");
        self.controller_input_source = snapshot
            .as_ref()
            .map(|state| state.source.clone())
            .unwrap_or_default();
        self.controller_input_device_id = snapshot
            .as_ref()
            .map(|state| state.device_id.clone())
            .unwrap_or_default();
        self.controller_input_device_name = snapshot
            .as_ref()
            .map(|state| state.device_name.clone())
            .unwrap_or_default();
        let Some(gamepad) = snapshot else {
            self.media_repeat.clear();
            return (Vec::new(), 0);
        };
        let now_ms = self.input_epoch.elapsed().as_millis() as u64;
        let bindings: Vec<(crate::media_input::MediaAction, PadInput)> = self
            .media_bindings
            .pad
            .iter()
            .map(|(action, input)| (*action, *input))
            .collect();

        // Latch Start even while Guide/background suppression owns the input,
        // so releasing Guide/focus with Start still held cannot manufacture a
        // delayed Facial edge.
        let start_down = gamepad.pressed(PadButtonCode::Start);
        let start_was_down = self.controller_start_down;
        self.controller_start_down = start_down;
        // Guide owns its chord layer (notably Guide+Start = Alt+Tab),
        // and background windows own no controller input. Suppress every held
        // Facial binding until release so releasing Guide/focus cannot create
        // a delayed false edge inside Facial.
        let guide_pressed = gamepad.guide_pressed;
        if crate::media_input::suppress_controller_actions(app_focused, guide_pressed) {
            // Focus loss is a hard handoff boundary: release buttons before
            // another app can observe a stale Facial drag/click.
            if !app_focused {
                if self.controller_pointer_left_down {
                    let _ = crate::platform_input::set_pointer_button(
                        crate::platform_input::PointerButton::Left,
                        false,
                    );
                }
                if self.controller_pointer_right_down {
                    let _ = crate::platform_input::set_pointer_button(
                        crate::platform_input::PointerButton::Right,
                        false,
                    );
                }
                self.controller_pointer_left_down = false;
                self.controller_pointer_right_down = false;
                self.controller_pointer_mode = false;
                self.controller_pointer_accum = [0.0, 0.0];
            }
            for (_, input) in &bindings {
                let is_down = match input {
                    PadInput::Button(code) => gamepad.pressed(*code),
                    PadInput::AxisPos(code) => gamepad.axis(*code) > 0.5,
                    PadInput::AxisNeg(code) => gamepad.axis(*code) < -0.5,
                };
                if is_down {
                    self.media_repeat.suppress(*input, now_ms);
                }
            }
            self.media_stick_accum = 0.0;
            self.media_last_poll = Some(std::time::Instant::now());
            return (Vec::new(), 0);
        }

        if crate::media_input::reserved_app_switch_edge_with_guide(
            app_focused,
            guide_pressed,
            start_down,
            start_was_down,
        ) {
            if self.controller_pointer_left_down {
                let _ = crate::platform_input::set_pointer_button(
                    crate::platform_input::PointerButton::Left,
                    false,
                );
            }
            if self.controller_pointer_right_down {
                let _ = crate::platform_input::set_pointer_button(
                    crate::platform_input::PointerButton::Right,
                    false,
                );
            }
            self.controller_pointer_left_down = false;
            self.controller_pointer_right_down = false;
            self.controller_pointer_mode = false;
            self.controller_pointer_accum = [0.0, 0.0];
            self.media_stick_accum = 0.0;
            self.media_repeat.clear();
            self.compare_action_message = match crate::platform_input::switch_apps() {
                Ok(()) => "Switched apps — controller handed off".to_string(),
                Err(err) => format!("App switch failed: {err}"),
            };
            self.media_last_poll = Some(std::time::Instant::now());
            return (Vec::new(), 0);
        }

        let now = std::time::Instant::now();
        let dt = self
            .media_last_poll
            .map(|t| now.duration_since(t).as_secs_f32().min(0.10))
            .unwrap_or(0.0);
        self.media_last_poll = Some(now);

        if self.controller_pointer_mode {
            let vx = crate::media_input::pointer_velocity(gamepad.axis(PadAxisCode::RightStickX));
            let vy = crate::media_input::pointer_velocity(-gamepad.axis(PadAxisCode::RightStickY));
            self.controller_pointer_accum[0] += vx * dt;
            self.controller_pointer_accum[1] += vy * dt;
            let dx = self.controller_pointer_accum[0].trunc() as i32;
            let dy = self.controller_pointer_accum[1].trunc() as i32;
            self.controller_pointer_accum[0] -= dx as f32;
            self.controller_pointer_accum[1] -= dy as f32;
            if let Err(err) = crate::platform_input::move_pointer(dx, dy) {
                self.compare_action_message = format!("Controller cursor failed: {err}");
                self.controller_pointer_mode = false;
            }

            let left_down = gamepad.pressed(PadButtonCode::South);
            if left_down != self.controller_pointer_left_down {
                if let Err(err) = crate::platform_input::set_pointer_button(
                    crate::platform_input::PointerButton::Left,
                    left_down,
                ) {
                    self.compare_action_message = format!("Controller click failed: {err}");
                }
                self.controller_pointer_left_down = left_down;
            }
            let right_down = gamepad.pressed(PadButtonCode::East);
            if right_down != self.controller_pointer_right_down {
                if let Err(err) = crate::platform_input::set_pointer_button(
                    crate::platform_input::PointerButton::Right,
                    right_down,
                ) {
                    self.compare_action_message = format!("Controller click failed: {err}");
                }
                self.controller_pointer_right_down = right_down;
            }
        }

        // Armed pad rebind: the first pressed button / deflected axis wins.
        if let Some(capture) = &self.media_capture {
            if let CaptureSlot::Pad(action) = capture.slot {
                if capture.expired(now_ms) {
                    self.media_capture = None;
                } else {
                    let mut captured: Option<PadInput> = None;
                    for code in PadButtonCode::ALL {
                        if gamepad.pressed(code) {
                            captured = Some(PadInput::Button(code));
                            break;
                        }
                    }
                    if captured.is_none() {
                        for code in [
                            PadAxisCode::LeftStickX,
                            PadAxisCode::LeftStickY,
                            PadAxisCode::RightStickX,
                            PadAxisCode::RightStickY,
                        ] {
                            let value = gamepad.axis(code);
                            if value > 0.6 {
                                captured = Some(PadInput::AxisPos(code));
                                break;
                            }
                            if value < -0.6 {
                                captured = Some(PadInput::AxisNeg(code));
                                break;
                            }
                        }
                    }
                    if let Some(input) = captured {
                        self.media_bindings.rebind_pad(action, input);
                        self.save_media_bindings();
                        self.media_capture = None;
                        self.media_repeat.clear();
                        // The capturing press is still physically held: mark
                        // it held-without-edge so the new binding does not
                        // fire instantly (round 3, finding 10).
                        self.media_repeat.suppress(input, now_ms);
                        self.compare_action_message =
                            format!("{} bound to {}", action.label(), input.display());
                        return (Vec::new(), 0); // swallow the captured press
                    }
                }
            }
        }

        let mut fired = Vec::new();
        for (action, input) in bindings {
            if self.controller_pointer_mode
                && matches!(
                    input,
                    PadInput::Button(PadButtonCode::South | PadButtonCode::East)
                )
            {
                self.media_repeat.suppress(input, now_ms);
                continue;
            }
            let is_down = match input {
                PadInput::Button(code) => gamepad.pressed(code),
                PadInput::AxisPos(code) => gamepad.axis(code) > 0.5,
                PadInput::AxisNeg(code) => gamepad.axis(code) < -0.5,
            };
            if self
                .media_repeat
                .should_fire(input, is_down, now_ms, action.repeats())
            {
                fired.push(action);
            }
        }

        // Analog scroll: left stick Y (gilrs up = +1, so invert for rows).
        let stick_y = gamepad.axis(PadAxisCode::LeftStickY);
        self.media_stick_accum += stick_scroll_velocity(-stick_y) * dt;
        let rows = self.media_stick_accum.trunc() as isize;
        self.media_stick_accum -= rows as f32;

        (fired, rows)
    }

    // -----------------------------------------------------------------------
    // Model-drivable control surface (file-based UI-intent protocol)
    // -----------------------------------------------------------------------

    /// Poll intents/, apply at most one ui-intent this frame, write its Receipt
    /// (Applied/Rejected) via api::mark_intent_applied, record a ModelAction event.
    /// Returns true if an intent was applied (for repaint coalescing).
    fn poll_and_apply_model_intent(&mut self, ctx: &egui::Context) -> bool {
        // Keep a live snapshot intent in the queue until the renderer returns
        // the requested framebuffer. This prevents a second frame from
        // re-applying the same still-pending intent.
        if self.pending_model_snapshot.is_some() || self.pending_match_model_intent.is_some() {
            return false;
        }
        let cmd = match api::poll_pending_intent(&self.api_paths) {
            Some(cmd) => cmd,
            None => return false,
        };

        if let CommandKind::UiSnapshot {
            output,
            include_sensitive_match,
        } = &cmd.command
        {
            let include_sensitive_match = *include_sensitive_match;
            let sensitive_match =
                self.last_rendered_sensitive_match || self.match_sensitive_presentation_visible();
            let path = match self.ui_snapshot_path(output.as_deref(), &cmd.action_id) {
                Ok(path) => path,
                Err(error) => {
                    let pending = PendingModelSnapshot {
                        path: self
                            .config
                            .workspace_root
                            .join(".facial")
                            .join("ui-snapshots")
                            .join("live-ui")
                            .join(format!("{}.png", cmd.action_id)),
                        command: cmd,
                        requested_at: None,
                        sensitive_match,
                    };
                    self.finish_model_snapshot(pending, Err(error));
                    return true;
                }
            };
            let pending = PendingModelSnapshot {
                path,
                command: cmd,
                requested_at: None,
                sensitive_match,
            };
            if let Err(error) =
                sensitive_match_capture_authorization(sensitive_match, include_sensitive_match)
            {
                self.finish_model_snapshot(pending, Err(error.to_string()));
                return true;
            }
            self.pending_model_snapshot = Some(pending);
            return true;
        }

        if matches!(cmd.command, CommandKind::MatchRuntimeDiagnostics) {
            return self.queue_match_runtime_diagnostics(ctx, cmd);
        }
        if matches!(
            cmd.command,
            CommandKind::MatchSettingsManagePeople | CommandKind::MatchEditorAutocomplete(..)
        ) {
            return self.queue_match_ui_endpoint(ctx, cmd);
        }
        if matches!(cmd.command, CommandKind::MatchIntent { .. }) {
            return self.queue_background_match_intent(ctx, cmd);
        }
        if matches!(cmd.command, CommandKind::MatchMaintenance(..)) {
            return self.queue_background_match_maintenance(ctx, cmd);
        }
        if matches!(cmd.command, CommandKind::MatchClusterReview(..)) {
            return self.queue_background_match_cluster_review(ctx, cmd);
        }
        if matches!(cmd.command, CommandKind::MatchVideo(..)) {
            return self.queue_background_match_video(ctx, cmd);
        }
        if matches!(cmd.command, CommandKind::MatchCorrection(..)) {
            return self.queue_background_match_correction(ctx, cmd);
        }
        if matches!(cmd.command, CommandKind::MatchBatchCorrectionPreflight(..)) {
            return self.queue_background_match_batch_correction_preflight(ctx, cmd);
        }
        if matches!(cmd.command, CommandKind::MatchSplitPersonPreflight(..)) {
            return self.queue_background_match_split_person_preflight(ctx, cmd);
        }

        let (mut applied, mut message) = self.apply_ui_intent(ctx, &cmd);
        // A receipt is written in the same frame the intent is applied, before
        // the next render refreshes the persisted tab viewports. Without this,
        // a mutation receipt embedded the PRE-change tab array — so a model that
        // read the receipt of the very command it just issued saw the old value
        // and could not tell a stale-but-succeeded receipt from an
        // accurate-but-failed one (no-context Manual audit, finding G).
        self.snapshot_active_media_tab();
        let intent_result = if let CommandKind::MediaVideoControl { action, output, .. } =
            &cmd.command
        {
            let fresh = self.video_player.snapshot_fresh();
            let mut value = match fresh {
                Ok(snapshot) => {
                    self.sync_media_playback_priority(snapshot.as_ref());
                    if applied && self.media_pending_video_start.is_none() {
                        if let Some(state) = snapshot.as_ref().filter(|state| state.confirmed) {
                            let contradicted = ((action == "play" || action == "play_library")
                                && !state.playing)
                                || (action == "pause" && state.playing);
                            if contradicted {
                                applied = false;
                                message = format!(
                                    "LibVLC confirmed {:?}, not requested {action}",
                                    state.status
                                );
                            }
                        }
                    }
                    if applied
                        && self.media_pending_video_start.is_none()
                        && snapshot.as_ref().is_some_and(|state| !state.confirmed)
                    {
                        message = format!("{message}; pending LibVLC confirmation");
                    }
                    snapshot
                        .and_then(|state| serde_json::to_value(state).ok())
                        .unwrap_or_else(|| serde_json::json!({}))
                }
                Err(error) => {
                    applied = false;
                    message = error.clone();
                    serde_json::json!({"error": error})
                }
            };
            if let Some(object) = value.as_object_mut() {
                if let Some(pending) = self.media_pending_video_start.as_ref() {
                    object.insert("playing".to_string(), serde_json::Value::Bool(false));
                    object.insert("confirmed".to_string(), serde_json::Value::Bool(false));
                    object.insert(
                        "status".to_string(),
                        serde_json::Value::String("preparing_surface".to_string()),
                    );
                    object.insert(
                        "pending_path".to_string(),
                        serde_json::Value::String(pending.path.clone()),
                    );
                    object.insert(
                        "pending_surface_owner".to_string(),
                        serde_json::Value::String(match pending.owner {
                            VideoSurfaceOwner::Viewer => "viewer".to_string(),
                            VideoSurfaceOwner::Library => "library".to_string(),
                        }),
                    );
                    object.insert(
                        "pending_age_ms".to_string(),
                        serde_json::json!(pending.requested_at.elapsed().as_millis()),
                    );
                    message = format!("{message}; waiting for visible surface placement");
                }
                object.insert(
                    "surface_owner".to_string(),
                    self.media_video_surface_owner()
                        .map(serde_json::Value::String)
                        .unwrap_or(serde_json::Value::Null),
                );
                if let Ok(diagnostics) = serde_json::to_value(self.video_player.diagnostics()) {
                    object.insert("playback_diagnostics".to_string(), diagnostics);
                }
                if let Some(engine) = self.thumb_engine.as_ref() {
                    if let Ok(diagnostics) = serde_json::to_value(engine.diagnostics()) {
                        object.insert("thumbnail_diagnostics".to_string(), diagnostics);
                    }
                }
                if let Ok(diagnostics) = serde_json::to_value(self.media_io.diagnostics()) {
                    object.insert("media_io_diagnostics".to_string(), diagnostics);
                }
                object.insert(
                    "search_status".to_string(),
                    serde_json::Value::String(self.media_search_status.clone()),
                );
                if let Ok(diagnostics) = serde_json::to_value(&self.media_scan_diagnostics) {
                    object.insert("scan_diagnostics".to_string(), diagnostics);
                }
                if let Ok(diagnostics) = serde_json::to_value(&self.media_query_diagnostics) {
                    object.insert("query_diagnostics".to_string(), diagnostics);
                }
                object.insert(
                    "ui_frame_diagnostics".to_string(),
                    serde_json::json!({
                        "last_us": self.media_ui_frame_last_us,
                        "max_us": self.media_ui_frame_max_us,
                    }),
                );
            }
            if action == "capture_frame" {
                let path = self.media_video_capture_path(output.as_deref(), &cmd.action_id);
                if let Some(object) = value.as_object_mut() {
                    object.insert(
                        "capture_path".to_string(),
                        serde_json::Value::String(path.to_string_lossy().to_string()),
                    );
                    object.insert(
                        "capture_exists".to_string(),
                        serde_json::Value::Bool(
                            path.metadata().is_ok_and(|metadata| metadata.len() > 0),
                        ),
                    );
                }
            }
            value
        } else if let CommandKind::MediaLabelMutation { path, .. } = &cmd.command {
            serde_json::json!({
                "labels": &self.media_label_definitions,
                "usage": &self.media_label_usage_counts,
                "path": path,
                "assigned_labels": path.as_deref().map(|path| self.media_db.labels(path)),
            })
        } else if let CommandKind::MediaFolderNavigate { action } = &cmd.command {
            let lane = self.compare_lanes.first();
            serde_json::json!({
                "action": action,
                "staged_folder": sanitize_folder_input(&self.media_explorer.folder_navigator_location),
                "committed_folder": lane.map(|lane| sanitize_folder_input(&lane.folder)).unwrap_or_default(),
                "active_tab": self.media_tabs.active_id().as_str(),
                "active_lane": lane.map(|lane| lane.id),
                "scan_requested": applied && matches!(action.as_str(), "commit" | "open_new_tab"),
                "navigator_visible": self.media_explorer.show_folder_navigator,
            })
        } else if let CommandKind::MediaTabs {
            action,
            tab_id,
            path,
        } = &cmd.command
        {
            let (window_sample_count, window_p50_us, window_p95_us, window_max_us) =
                self.media_frame_window_summary();
            let reconciliation = self
                .media_tab_reconciliation_pending
                .as_ref()
                .map(|pending| {
                    serde_json::json!({
                        "pending": true,
                        "tab_id": pending.tab_id,
                        "lane_id": pending.lane_id,
                        "folder": pending.folder,
                        "starts_in_ms": pending
                            .due_at
                            .saturating_duration_since(std::time::Instant::now())
                            .as_millis(),
                    })
                })
                .unwrap_or_else(|| serde_json::json!({"pending": false}));
            serde_json::json!({
                "action": action,
                "requested_tab_id": tab_id,
                "requested_path": path,
                "active_tab_id": self.media_tabs.active_id().as_str(),
                "tabs": self.media_tabs.tabs().iter().map(|tab| {
                    let resolved = if tab.viewport.folder_key.is_empty() { String::new() } else { self.media_db.path_for_key(&tab.viewport.folder_key) };
                    let collection = tab.viewport.kind != crate::media_tabs::MediaTabKind::Folder;
                    serde_json::json!({
                        "id": tab.id.as_str(),
                        // WP-067: tab kind and sub-view are model-visible so a
                        // collection tab is distinguishable from a folder tab.
                        "kind": if collection { "collection" } else { "folder" },
                        "collection_view": collection.then(|| format!("{:?}", tab.viewport.collection_view)),
                        "collection_label_id": tab.viewport.collection_label_id,
                        "title": if collection { "Favorites".to_string() } else { crate::media_tabs::folder_tab_title(&resolved) },
                        "folder_key": tab.viewport.folder_key,
                        "folder": resolved,
                        "search_query": tab.viewport.search_query,
                        // WP-066: per-tab search scope.
                        "search_folder_only": tab.viewport.search_folder_only,
                        // WP-068: per-tab ordering.
                        "sort": format!("{:?}", tab.viewport.sort),
                        "sort_descending": tab.viewport.sort_descending,
                        "view_mode": format!("{:?}", tab.viewport.view_mode),
                        "split_ratio": tab.viewport.split_ratio,
                        "viewer_meta_height": tab.viewport.viewer_meta_height,
                    })
                }).collect::<Vec<_>>(),
                "selection_restore_pending": !self.media_tab_pending_selection_keys.is_empty(),
                // Structured label catalog: open_collection needs a stable ID,
                // and a model must not have to parse it out of the note text.
                "label_catalog": self.media_label_definitions.iter().map(|definition| {
                    serde_json::json!({
                        "id": definition.id,
                        "name": definition.name,
                        "hex": definition.hex,
                        "usage": self.media_label_usage_counts
                            .get(&definition.id)
                            .copied()
                            .unwrap_or(0),
                    })
                }).collect::<Vec<_>>(),
                "search_folder_only": self.media_search_folder_only,
                "last_scope_change": self.media_last_scope_change.map(|(scan, inventory)| {
                    serde_json::json!({
                        "scan_unchanged": scan,
                        "inventory_unchanged": inventory,
                    })
                }),
                "activation_restore": &self.media_tab_activation_diagnostics,
                "reconciliation": reconciliation,
                "grid_navigation": &self.media_grid_navigation_diagnostics,
                "chrome_hidden": self.media_explorer.chrome_hidden,
                "match_immersive_hold_applied": self.match_immersive_hold_applied,
                "match_presentation_hold_epoch": self.match_external_holds.snapshot(),
                "match_playback_hold": self.match_external_holds.playback(),
                "split_ratio": self.media_explorer.split_ratio,
                "split_ratio_min": crate::media_explorer::SPLIT_MIN,
                "split_ratio_max": crate::media_explorer::SPLIT_MAX,
                // WP-072: live Viewer metadata band height plus its static
                // bounds, so a model can drive and prove the layout headlessly.
                "viewer_meta_height": self.media_explorer.viewer_meta_height,
                "viewer_meta_height_min": crate::media_explorer::META_MIN,
                "viewer_meta_height_max_static": crate::media_explorer::META_STATIC_MAX,
                // Model-driven chrome changes are intentionally in-app only:
                // they never raise, activate, resize, or fullscreen the native
                // viewport. This constant is a receipt-level safety assertion.
                "native_fullscreen_changed": false,
                "scan_generation": self.compare_lanes.first().map(|lane| lane.scan_id),
                "scan_active": self.compare_lanes.first().is_some_and(|lane| lane.scanning),
                // `scan_active` covers the whole scan, including the inventory
                // write, which on a very large folder runs far longer than the
                // enumeration itself. A model waiting on `scan_active == false`
                // before acting was therefore waiting on the write, not on the
                // rows (no-context Manual audit, finding 5.4). This says which.
                "scan_phase": if !self.compare_lanes.first().is_some_and(|lane| lane.scanning) {
                    "idle"
                } else if self.media_scan_diagnostics.elapsed_ms.is_some() {
                    // Enumeration finished; the rows are already renderable.
                    "persisting_inventory"
                } else {
                    "enumerating"
                },
                "inventory_count": self.compare_lanes.first().map(|lane| lane.files.len()).unwrap_or(0),
                // WP-069: the grid renders the DISPLAY order, not the inventory,
                // so a blank grid with a full inventory is the exact defect this
                // packet fixes. Report what is actually renderable and whether it
                // is the settled order or a provisional one.
                "display_count": self.media_display_cache.len(),
                // The first rows in the order the grid actually paints them.
                // Without this a model can see HOW MANY rows are shown but not
                // WHICH, nor in what order — so it cannot verify a sort took
                // effect, and cannot enumerate a collection's files at all while
                // the GUI holds the media-database lock (audit findings).
                "display_head": self
                    .compare_lanes
                    .first()
                    .map(|lane| {
                        self.media_display_cache
                            .iter()
                            .take(10)
                            .filter_map(|index| lane.files.get(*index))
                            .map(|path| {
                                Path::new(path)
                                    .file_name()
                                    .and_then(|value| value.to_str())
                                    .unwrap_or(path.as_str())
                                    .to_string()
                            })
                            .collect::<Vec<_>>()
                    })
                    .unwrap_or_default(),
                // Canonical full paths for the same bounded head. A benchmark
                // can select a real recursive video without re-enumerating the
                // NAS outside Facial or trying to reconstruct a path from its
                // filename.
                "display_head_paths": self
                    .compare_lanes
                    .first()
                    .map(|lane| {
                        self.media_display_cache
                            .iter()
                            .take(10)
                            .filter_map(|index| lane.files.get(*index))
                            .cloned()
                            .collect::<Vec<_>>()
                    })
                    .unwrap_or_default(),
                "selected_path": self
                    .compare_lanes
                    .first()
                    .and_then(|lane| self.media_selected_path(lane.id)),
                "cursor_path": self.compare_lanes.first().and_then(|lane| {
                    self.media_explorer.cursor
                        .and_then(|display_index| self.media_display_cache.get(display_index))
                        .and_then(|source_index| lane.files.get(*source_index))
                        .cloned()
                }),
                "display_provenance": if self.media_display_cache.is_empty() {
                    "empty"
                } else if self.media_display_cache_key.is_some() {
                    "settled"
                } else {
                    "provisional"
                },
                "scan_error": self.compare_lanes.first().map(|lane| lane.scan_error.as_str()).unwrap_or_default(),
                "scan_diagnostics": &self.media_scan_diagnostics,
                // `media_tabs --action list` is the documented polling loop for
                // grid state, so it is where a model watches a large folder
                // load — and it was the one media intent carrying no I/O or
                // query diagnostics (no-context Manual audit, finding 5.1).
                "media_io_diagnostics": self.media_io.diagnostics(),
                "thumbnail_diagnostics": self.thumb_engine.as_ref().map(|engine| engine.diagnostics()),
                "query_diagnostics": &self.media_query_diagnostics,
                // WP-068/069: a keyed display may have been published before
                // the stat sidecar finished. This is the authoritative polling
                // gate for whether the selected sort consumed current stats.
                "sort_diagnostics": self.media_sort_diagnostics(),
                // WP-073: last delete job. Outcomes appear only once
                // settled=true — a receipt never reports a value the app has
                // not finished computing (CODEX 8.3).
                "delete_diagnostics": self.media_delete_report,
                // WP-074 selection/sheet state and the last contact-sheet export.
                "select_mode": self.media_select_mode,
                "sheet_mode": self.media_sheet_mode,
                "sheet_names": self.media_sheet_names,
                "selected_count": self
                    .compare_lanes
                    .first()
                    .map(|lane| lane.selected_files.len())
                    .unwrap_or(0),
                "sheet_export": self.media_sheet_export,
                // WP-074: structured per-file move/copy results; a note is not
                // proof (CODEX 8.3).
                "file_op_diagnostics": self.media_file_op_report,
                // WP-075 receiving pane state.
                "receiving_pane_tab": self.media_receiving_pane,
                "receiving_pane_folder": self.media_receiving_pane_folder,
                "drag_active": self.media_drag_payload.is_some(),
                "active_load_timing": self.active_media_load_timing(),
                // Canonical topology names. Keep the prior aliases above/below
                // for compatibility with receipts already consumed in the
                // field before WP-069's acceptance run.
                "media_load_timing": self.active_media_load_timing(),
                "load_timing_history": self
                    .media_load_timings
                    .iter()
                    .map(MediaLoadTiming::snapshot)
                    .collect::<Vec<_>>(),
                "media_load_timing_history": self
                    .media_load_timings
                    .iter()
                    .map(MediaLoadTiming::snapshot)
                    .collect::<Vec<_>>(),
                "ui_frame_diagnostics": {
                    "last_us": self.media_ui_frame_last_us,
                    // Session-cumulative, not windowed: this is the worst frame
                    // since launch, including startup, so a single large value
                    // is not by itself evidence of a current stall.
                    "max_us": self.media_ui_frame_max_us,
                    "max_window": "session_cumulative",
                    "window_ms": 2000,
                    "window_sample_count": window_sample_count,
                    "window_p50_us": window_p50_us,
                    "window_p95_us": window_p95_us,
                    "window_max_us": window_max_us,
                    "window_scope": "media_update_frames",
                },
                "ui_filesystem_diagnostics": {
                    "scope": "draw_media_tab_through_draw_media_settings_controls",
                    "enforcement": "cargo_test::media_hot_draw_surface_has_no_synchronous_filesystem_calls",
                    "violation_count": 0,
                    "violations": [],
                },
            })
        } else if matches!(cmd.command, CommandKind::MediaSearch { .. }) {
            // WP-066: make filtering provable without foregrounding — which
            // terms were additive, which were subtractive, the active scope, and
            // how many rows survived. An empty result caused by subtraction is
            // otherwise indistinguishable from a broken query.
            let parsed = crate::media_search::parse_query(&self.media_search_query);
            let inventory = self
                .compare_lanes
                .first()
                .map(|lane| lane.files.len())
                .unwrap_or(0);
            // The display worker has NOT re-ranked yet in this frame, so the
            // published order still belongs to the previous query. Reporting its
            // length as matched_count made every search receipt lag by exactly
            // one intent (no-context Manual audit, finding D). Report a count
            // only when the published order actually belongs to this query;
            // otherwise say so, rather than returning a confidently wrong number.
            let settled_for_this_query = self.media_display_cache_key.as_ref().is_some_and(|key| {
                key.query == self.media_search_query
                    && key.search_folder_only == self.media_search_folder_only
            });
            let matched = self.media_display_cache.len();
            serde_json::json!({
                "scan_diagnostics": &self.media_scan_diagnostics,
                // query_diagnostics and search_status describe the ranking that
                // has actually completed. Immediately after a query change that
                // is the PREVIOUS query, so emitting them beside a correct
                // "applied" status handed a model a plausible wrong number
                // (second no-context Manual audit). Withhold them until they
                // describe this query.
                "query_diagnostics": settled_for_this_query
                    .then(|| serde_json::to_value(&self.media_query_diagnostics).ok())
                    .flatten(),
                "search_status": settled_for_this_query
                    .then(|| self.media_search_status.clone()),
                "media_io_diagnostics": self.media_io.diagnostics(),
                "search_scope": if self.media_search_folder_only { "folder" } else { "tab" },
                "search_terms": {
                    "text": parsed.text,
                    "tags": parsed.tags,
                    "labels": parsed.labels,
                    "person_ids": parsed.person_ids,
                    "notes": parsed.notes_contain,
                    "kinds": parsed.kinds.iter().map(|kind| match kind {
                        crate::media_search::MediaKindFilter::Image => "image",
                        crate::media_search::MediaKindFilter::Video => "video",
                    }).collect::<Vec<_>>(),
                    "favorite": parsed.favorite,
                    "favorite_contradiction": parsed.favorite_contradiction,
                },
                "search_excluded": {
                    "tags": parsed.excluded.tags,
                    "labels": parsed.excluded.labels,
                    "person_ids": parsed.excluded.person_ids,
                    "notes": parsed.excluded.notes_contain,
                    "kinds": parsed.excluded.kinds.iter().map(|kind| match kind {
                        crate::media_search::MediaKindFilter::Image => "image",
                        crate::media_search::MediaKindFilter::Video => "video",
                    }).collect::<Vec<_>>(),
                    "words": parsed.excluded.words,
                },
                "matched_count": settled_for_this_query.then_some(matched),
                "excluded_count": settled_for_this_query
                    .then(|| inventory.saturating_sub(matched)),
                // When false, ranking for this query is still in flight; poll
                // media_tabs --action list and read display_count once
                // display_provenance reports "settled".
                "counts_settled": settled_for_this_query,
                "inventory_count": inventory,
                "match_identity_revision": (self.media_search_match_identity_revision != 0)
                    .then_some(self.media_search_match_identity_revision),
                "match_catalog_revision": (self.media_search_match_catalog_revision != 0)
                    .then_some(self.media_search_match_catalog_revision),
                "ui_frame_diagnostics": {
                    "last_us": self.media_ui_frame_last_us,
                    "max_us": self.media_ui_frame_max_us,
                }
            })
        } else {
            serde_json::json!({
                "scan_diagnostics": &self.media_scan_diagnostics,
                "query_diagnostics": &self.media_query_diagnostics,
                "media_io_diagnostics": self.media_io.diagnostics(),
                "search_status": &self.media_search_status,
                "ui_frame_diagnostics": {
                    "last_us": self.media_ui_frame_last_us,
                    "max_us": self.media_ui_frame_max_us,
                }
            })
        };
        let snapshot = self.current_state_snapshot();
        let kind = cmd.command.id_str().to_string();
        let now = chrono::Utc::now().to_rfc3339();
        let status = if applied {
            api::ActionStatus::Applied
        } else {
            api::ActionStatus::Rejected
        };
        let receipt = api::Receipt {
            action_id: cmd.action_id.clone(),
            kind: kind.clone(),
            status,
            actor: cmd.actor.clone(),
            protocol_version: cmd.protocol_version,
            started_at: now.clone(),
            finished_at: now,
            result: intent_result,
            error: if applied { None } else { Some(message.clone()) },
            note: Some(message.clone()),
        };

        let snapshot_value = serde_json::to_value(&snapshot).unwrap_or(serde_json::Value::Null);

        let persistence_error = match self.service.lock() {
            Ok(mut svc) => {
                let result = api::mark_intent_applied(&mut svc, &self.api_paths, &receipt);
                svc.record_applied_action(&cmd.action_id, &kind, applied, &message, snapshot_value);
                result.err().map(|error| error.to_string())
            }
            Err(_) => Some("service lock unavailable while finalizing UI intent".to_string()),
        };

        self.last_applied_action = Some(match persistence_error.as_deref() {
            Some(error) => {
                // The intent HAS been applied; only its bookkeeping failed. The
                // GUI is a windows-subsystem process, so this stderr line goes
                // nowhere, and a model following the documented poll-the-receipt
                // protocol would wait forever on an intent that already ran
                // (observed intermittently by a Manual-only audit). Write a
                // terminal receipt directly so the poller always converges, and
                // say in it that finalization failed.
                eprintln!("UI intent {} finalization failed: {error}", cmd.action_id);
                let mut fallback = receipt.clone();
                fallback.note = Some(format!(
                    "{message} :: WARNING intent applied but finalization failed: {error}"
                ));
                if let Err(write_error) = api::write_receipt_file(&self.api_paths, &fallback) {
                    eprintln!(
                        "UI intent {} fallback receipt write failed: {write_error}",
                        cmd.action_id
                    );
                }
                format!(
                    "{} intent={} applied={} persistence_error={} :: {}",
                    cmd.action_id, kind, applied, error, message
                )
            }
            None => format!(
                "{} intent={} applied={} :: {}",
                cmd.action_id, kind, applied, message
            ),
        });
        self.last_receipt = serde_json::to_string_pretty(&receipt).ok();

        applied
    }

    /// Apply one decoded Command (ui-intent CommandKind) to UI/service state.
    /// Returns (applied: bool, message: String) used for the receipt + event.
    fn apply_ui_intent(&mut self, ctx: &egui::Context, cmd: &ApiCommand) -> (bool, String) {
        match &cmd.command {
            CommandKind::SetProject { project_name } => {
                self.project_name = project_name.clone();
                (true, format!("project set to {project_name}"))
            }
            CommandKind::SetWorktree { worktree_path } => {
                self.worktree_path = worktree_path.clone();
                (true, format!("worktree set to {worktree_path}"))
            }
            CommandKind::SelectTab { tab } => match Tab::from_vocab(tab) {
                Some(t) => {
                    self.active_tab = t;
                    if t == Tab::Manual {
                        self.show_manual = true;
                    }
                    (true, format!("tab set to {tab}"))
                }
                None => (false, format!("unknown tab vocab: {tab}")),
            },
            CommandKind::SetFeatures { feature_keys } => {
                let known: HashSet<&str> = self
                    .feature_rows
                    .iter()
                    .map(|row| row.key.as_str())
                    .collect();
                let mut accepted = Vec::new();
                let mut dropped = Vec::new();
                for key in feature_keys {
                    if known.contains(key.as_str()) {
                        accepted.push(key.clone());
                    } else {
                        dropped.push(key.clone());
                    }
                }
                self.selected_features = accepted.iter().cloned().collect();
                if dropped.is_empty() {
                    (true, format!("selected {} features", accepted.len()))
                } else {
                    (
                        true,
                        format!(
                            "selected {} features; dropped unknown: {}",
                            accepted.len(),
                            dropped.join(",")
                        ),
                    )
                }
            }
            CommandKind::SetInPlace { in_place } => {
                self.in_place = *in_place;
                (true, format!("in_place set to {in_place}"))
            }
            CommandKind::ImportPaths {
                project_name,
                paths,
                in_place,
            } => {
                self.project_name = project_name.clone();
                self.in_place = *in_place;
                self.ingest_images(paths.clone());
                (true, self.import_summary.clone())
            }
            CommandKind::StartRunUi => {
                if self.running_pipeline {
                    (false, "pipeline already running".to_string())
                } else if self.selected_features.is_empty() {
                    (false, "no features selected".to_string())
                } else {
                    self.execute_pipeline();
                    (true, self.pipeline_status.clone())
                }
            }
            CommandKind::UiSnapshot { .. } => (
                false,
                "ui_snapshot must be handled by the renderer capture path".to_string(),
            ),
            // media browser intents (WP-042): drive the front surface headlessly.
            CommandKind::MediaSetFolder { path } => {
                if self.compare_lanes.is_empty() {
                    self.compare_lanes = vec![CompareLane::new(0)];
                    self.compare_next_lane_id = 1;
                }
                let lane_id = self.compare_lanes[0].id;
                let folder = sanitize_folder_input(path);
                if folder.is_empty() {
                    (false, "media folder path is empty".to_string())
                } else if self.media_tabs.active().viewport.kind
                    != crate::media_tabs::MediaTabKind::Folder
                {
                    // The Favorites tab has no folder. Silently "succeeding"
                    // here reported "scanning" while nothing changed
                    // (no-context Manual audit, finding A).
                    (
                        false,
                        format!(
                            "active tab {} is the Favorites collection tab and has no folder; \
                             select a folder tab (media_tabs --action select --tab-id ID) or \
                             open one (media_tabs --action open --path {folder})",
                            self.media_tabs.active_id().as_str()
                        ),
                    )
                } else {
                    self.active_tab = Tab::Media;
                    if let Some(pos) = self.compare_lane_position(lane_id) {
                        self.compare_lanes[pos].folder = folder.clone();
                    }
                    self.start_compare_scan(lane_id);
                    (true, format!("media folder set to {folder}; scanning"))
                }
            }
            CommandKind::MediaSearch { query, mode } => {
                // Mode vocab maps onto the 3-mode ranker (WP-047): tags/notes
                // become filter chips so those intents keep working.
                let (mode_index, effective_query) = match mode.as_deref() {
                    None | Some("name") => (0, query.clone()),
                    Some("fuzzy") => (1, query.clone()),
                    Some("semantic") => (2, query.clone()),
                    Some("tags") => (
                        0,
                        format!(
                            "tag:{}",
                            crate::media_search::quote_chip_value(query.trim())
                        ),
                    ),
                    Some("notes") => (
                        0,
                        format!(
                            "note:{}",
                            crate::media_search::quote_chip_value(query.trim())
                        ),
                    ),
                    Some(other) => {
                        return (false, format!("unknown media search mode: {other}"));
                    }
                };
                self.active_tab = Tab::Media;
                self.media_search_query = effective_query.clone();
                self.media_search_mode = mode_index;
                (
                    true,
                    format!(
                        "media search set: query='{effective_query}' mode={}",
                        ["name", "fuzzy", "semantic"][mode_index]
                    ),
                )
            }
            CommandKind::MediaSelect { paths } => {
                if self.compare_lanes.is_empty() {
                    return (false, "media surface has no lane".to_string());
                }
                let lane_id = self.compare_lanes[0].id;
                if self.compare_lane_position(lane_id).is_none() {
                    return (false, "media lane missing".to_string());
                }
                // Separator + casing insensitive matching: models naturally
                // send forward-slash paths while scans produce native ones.
                let wanted: HashSet<String> = paths
                    .iter()
                    .map(|p| sanitize_folder_input(p).replace('\\', "/").to_lowercase())
                    .collect();
                let matched = self.media_select_paths(lane_id, paths);
                let missed = wanted.len().saturating_sub(matched);
                (
                    matched > 0 || wanted.is_empty(),
                    format!(
                        "selected {matched} of {} requested paths ({missed} not in current folder)",
                        wanted.len()
                    ),
                )
            }
            CommandKind::MediaOpenSelected => {
                if self.compare_lanes.is_empty() {
                    return (false, "media surface has no lane".to_string());
                }
                let lane_id = self.compare_lanes[0].id;
                match self.compare_lane_open_selected_with_system(lane_id) {
                    Ok((opened, failed)) => (
                        failed == 0 && opened > 0,
                        format!("external media handoff: opened={opened} failed={failed}"),
                    ),
                    Err(error) => (false, error),
                }
            }
            CommandKind::MediaTabs {
                action,
                tab_id,
                path,
            } => {
                self.active_tab = Tab::Media;
                let result = match action.as_str() {
                    "list" => Ok(format!(
                        "{} media tabs; active={}",
                        self.media_tabs.tabs().len(),
                        self.media_tabs.active_id().as_str()
                    )),
                    // The backend media_labels_list command cannot run while the
                    // GUI holds the exclusive media database lock, and there was
                    // no read-only ui-intent to list labels — so a model could
                    // not discover the label ID that open_collection needs
                    // without MUTATING the catalog (no-context Manual audit,
                    // finding B).
                    "labels" => Ok(format!(
                        // The catalog is ALSO emitted as a structured
                        // `label_catalog` array in the receipt result; a model
                        // must never have to regex an ID out of this sentence
                        // (second no-context Manual audit).
                        "{} labels: {}",
                        self.media_label_definitions.len(),
                        self.media_label_definitions
                            .iter()
                            .map(|definition| format!(
                                "{}='{}'({})",
                                definition.id,
                                definition.name,
                                self.media_label_usage_counts
                                    .get(&definition.id)
                                    .copied()
                                    .unwrap_or(0)
                            ))
                            .collect::<Vec<_>>()
                            .join(", ")
                    )),
                    "select" => tab_id
                        .as_deref()
                        .ok_or_else(|| "media tab select requires tab_id".to_string())
                        .and_then(|id| self.activate_media_tab(id))
                        .map(|()| {
                            format!("active media tab={}", self.media_tabs.active_id().as_str())
                        }),
                    "open" => {
                        let target = path
                            .as_deref()
                            .map(sanitize_folder_input)
                            .filter(|value| !value.is_empty())
                            .unwrap_or_else(|| {
                                sanitize_folder_input(
                                    &self.media_explorer.folder_navigator_location,
                                )
                            });
                        self.open_media_folder_in_new_tab(&target)
                            .map(|id| format!("opened media tab={id}"))
                    }
                    "close" => tab_id
                        .as_deref()
                        .ok_or_else(|| "media tab close requires tab_id".to_string())
                        .and_then(|id| self.close_media_tab(id))
                        .map(|active| format!("closed media tab; active={active}")),
                    // WP-066/WP-068: per-tab search scope and per-tab ordering
                    // are new operator controls, so they need receipt-backed
                    // model equivalents (FACIAL-MODEL-001) — a model cannot
                    // click a toolbar toggle.
                    "set_scope" => {
                        let wanted = path.as_deref().unwrap_or("tab");
                        let folder_only = match wanted {
                            "folder" => true,
                            "tab" | "tree" => false,
                            other => {
                                return (
                                    false,
                                    format!("unknown search scope: {other} (folder|tab)"),
                                )
                            }
                        };
                        // A collection tab has no folder, so "this folder only"
                        // has nothing to scope to: the per-tab field could never
                        // take the value while the receipt said it had. Refuse,
                        // exactly as set_sort refuses its stat keys here
                        // (no-context Manual audit, finding 3.2).
                        if self.media_tabs.active().viewport.kind
                            != crate::media_tabs::MediaTabKind::Folder
                        {
                            return (
                                false,
                                "search scope does not apply to the Favorites collection tab, \
                                 which has no folder; select a folder tab first"
                                    .to_string(),
                            );
                        }
                        let before = self
                            .compare_lanes
                            .first()
                            .map(|lane| (lane.scan_id, lane.files.len()));
                        self.media_search_folder_only = folder_only;
                        // Write the per-tab field here rather than waiting for a
                        // later snapshot, so a `list` in the same apply frame
                        // reports the value this command just set.
                        self.media_tabs.active_mut().viewport.search_folder_only = folder_only;
                        self.touch_media_settings();
                        let after = self
                            .compare_lanes
                            .first()
                            .map(|lane| (lane.scan_id, lane.files.len()));
                        // The whole point of separating scope from the Tree flag
                        // is that scope never rescans. Prove it in the receipt —
                        // also as structured fields, so proving it does not
                        // require parsing this sentence (audit finding I).
                        self.media_last_scope_change = Some((
                            before.map(|b| b.0) == after.map(|a| a.0),
                            before.map(|b| b.1) == after.map(|a| a.1),
                        ));
                        Ok(format!(
                            "search scope={wanted} scan_unchanged={} inventory_unchanged={}",
                            before.map(|b| b.0) == after.map(|a| a.0),
                            before.map(|b| b.1) == after.map(|a| a.1)
                        ))
                    }
                    "set_sort" => {
                        let raw = path.as_deref().unwrap_or_default().to_ascii_lowercase();
                        let (key, descending) = match raw.split_once(':') {
                            Some((key, dir)) => (key.to_string(), dir == "desc"),
                            None => (raw.clone(), false),
                        };
                        let sort = match key.as_str() {
                            "name" => crate::media_explorer::MediaSort::Name,
                            "modified" => crate::media_explorer::MediaSort::Modified,
                            "size" => crate::media_explorer::MediaSort::Size,
                            "created" => crate::media_explorer::MediaSort::Created,
                            other => {
                                return (
                                    false,
                                    format!(
                                        "unknown sort key: {other} (name|modified|size|created, \
                                         optionally :asc or :desc)"
                                    ),
                                )
                            }
                        };
                        // A collection tab's rows come from the metadata cache
                        // and carry no stat sidecar, so a stat-dependent key
                        // would silently order by name while claiming otherwise.
                        // Reporting success and changing nothing is worse than
                        // refusing (no-context Manual audit, finding C).
                        let collection = self.media_tabs.active().viewport.kind
                            != crate::media_tabs::MediaTabKind::Folder;
                        if collection && sort.needs_stat() {
                            return (
                                false,
                                format!(
                                    "sort key {key} needs file metadata that the Favorites \
                                     collection tab does not collect; use name, or select a \
                                     folder tab"
                                ),
                            );
                        }
                        self.media_explorer.sort = sort;
                        self.media_explorer.sort_desc = descending;
                        self.media_tabs.active_mut().viewport.sort = match sort {
                            crate::media_explorer::MediaSort::Name => MediaTabSort::Name,
                            crate::media_explorer::MediaSort::Modified => MediaTabSort::Modified,
                            crate::media_explorer::MediaSort::Size => MediaTabSort::Size,
                            crate::media_explorer::MediaSort::Created => MediaTabSort::Created,
                        };
                        self.media_tabs.active_mut().viewport.sort_descending = descending;
                        self.touch_media_settings();
                        if self.media_tabs.active().viewport.kind
                            == crate::media_tabs::MediaTabKind::Collection
                        {
                            let lane_id =
                                self.compare_lanes.first().map(|lane| lane.id).unwrap_or(0);
                            self.materialize_media_collection_tab(lane_id);
                        }
                        Ok(format!(
                            "sort={key} descending={descending} tab={}",
                            self.media_tabs.active_id().as_str()
                        ))
                    }
                    // WP-069: drive real virtual-grid scrolling without
                    // foreground input. This moves in display coordinates by
                    // arithmetic only; unlike media_select it does not linearly
                    // search a 141k-row inventory on the UI thread.
                    "navigate_grid" => {
                        let direction = path.as_deref().unwrap_or_default();
                        let display_count = self.media_display_cache.len();
                        let columns = self.media_explorer.last_grid_columns.max(1);
                        let previous_cursor = self.media_explorer.cursor;
                        let before = self
                            .compare_lanes
                            .first()
                            .map(|lane| (lane.scan_id, lane.files.len()));
                        let target = match media_grid_navigation_target(
                            previous_cursor,
                            display_count,
                            columns,
                            direction,
                        ) {
                            Ok(target) => target,
                            Err(error) => return (false, error),
                        };
                        self.visible_media_metrics.navigation.clear_pending();
                        if let Some(lane) = self.compare_lanes.first() {
                            self.visible_media_metrics.navigation.begin(
                                (
                                    self.media_tabs.active_id().as_str().to_string(),
                                    lane.scan_id,
                                    target,
                                ),
                                std::time::Instant::now(),
                            );
                        }
                        self.media_explorer.cursor = Some(target);
                        self.media_scroll_to_cursor = true;
                        let after = self
                            .compare_lanes
                            .first()
                            .map(|lane| (lane.scan_id, lane.files.len()));
                        self.media_grid_navigation_diagnostics =
                            Some(MediaGridNavigationDiagnostics {
                                action: direction.to_string(),
                                previous_cursor,
                                cursor: target,
                                display_count,
                                columns,
                                scan_generation_unchanged: before.map(|value| value.0)
                                    == after.map(|value| value.0),
                                inventory_count_unchanged: before.map(|value| value.1)
                                    == after.map(|value| value.1),
                            });
                        Ok(format!(
                            "grid navigation={direction} cursor={target} display_count={display_count}"
                        ))
                    }
                    // Model-safe presentation control: change only the egui
                    // chrome state. Unlike the operator Ctrl+F binding, this
                    // branch must never send a native ViewportCommand or raise
                    // the application above the operator's foreground window.
                    "set_chrome" => {
                        let state = path.as_deref().unwrap_or_default();
                        let hidden = match media_chrome_hidden_for_action(state) {
                            Ok(hidden) => hidden,
                            Err(error) => return (false, error),
                        };
                        self.media_explorer.chrome_hidden = hidden;
                        self.match_external_holds
                            .set_fullscreen(hidden && !self.media_explorer.show_settings);
                        self.media_explorer.chrome_hidden_at = hidden.then(std::time::Instant::now);
                        Ok(format!(
                            "Media chrome={} native_fullscreen_changed=false",
                            if hidden { "hidden" } else { "visible" }
                        ))
                    }
                    // Background-safe live geometry control for WP-065. This
                    // changes only the in-app panel split and never raises,
                    // resizes, or fullscreens the native viewport.
                    "set_split" => {
                        let raw = path.as_deref().unwrap_or_default();
                        let (requested, applied) = match media_split_ratio_for_action(raw) {
                            Ok(values) => values,
                            Err(error) => return (false, error),
                        };
                        self.media_explorer.split_ratio = applied;
                        self.media_tabs.active_mut().viewport.split_ratio = applied;
                        self.touch_media_settings();
                        Ok(format!(
                            "Library / Viewer split={applied} (requested {requested}); native_fullscreen_changed=false"
                        ))
                    }
                    // WP-072: the Viewer metadata band height, per tab, with
                    // the same requested-vs-applied honesty as set_split. The
                    // static clamp is reported; the live panel clamp renders.
                    "set_meta_height" => {
                        let raw = path.as_deref().unwrap_or_default();
                        let (requested, applied) = match media_meta_height_for_action(raw) {
                            Ok(values) => values,
                            Err(error) => return (false, error),
                        };
                        self.media_explorer.viewer_meta_height = applied;
                        self.media_tabs.active_mut().viewport.viewer_meta_height = applied;
                        self.touch_media_settings();
                        Ok(format!(
                            "Viewer metadata band height={applied} points (requested {requested}); native_fullscreen_changed=false"
                        ))
                    }
                    // WP-067: the favourites/labels collection tab needs a
                    // receipt-backed intent, not only a keyboard binding, so a
                    // model can reach and prove it (FACIAL-MODEL-001).
                    "open_collection" => {
                        let raw = path.as_deref().unwrap_or("fav_videos");
                        // `labels:<label-id>` selects a label in the same call,
                        // otherwise the labels view opens with nothing chosen
                        // and a model cannot reach a label's files (WP-067).
                        let (view_key, label_id) = match raw.split_once(':') {
                            Some((view, label)) => (view, Some(label.to_string())),
                            None => (raw, None),
                        };
                        let parsed = match view_key {
                            "fav_videos" | "" => {
                                Some(crate::media_tabs::MediaCollectionView::FavoriteVideos)
                            }
                            "fav_images" => {
                                Some(crate::media_tabs::MediaCollectionView::FavoriteImages)
                            }
                            "labels" => Some(crate::media_tabs::MediaCollectionView::Labels),
                            _ => None,
                        };
                        if let (Some(crate::media_tabs::MediaCollectionView::Labels), Some(id)) =
                            (parsed, label_id.as_deref())
                        {
                            if !self
                                .media_label_definitions
                                .iter()
                                .any(|definition| definition.id == id)
                            {
                                return (false, format!("unknown label id: {id}"));
                            }
                        }
                        match parsed {
                            Some(view) => self.open_media_collection_tab().map(|id| {
                                self.media_tabs.active_mut().viewport.collection_view = view;
                                if let Some(label) = label_id {
                                    self.media_tabs.active_mut().viewport.collection_label_id =
                                        label;
                                }
                                let lane_id =
                                    self.compare_lanes.first().map(|lane| lane.id).unwrap_or(0);
                                self.materialize_media_collection_tab(lane_id);
                                let count = self
                                    .compare_lanes
                                    .first()
                                    .map(|lane| lane.files.len())
                                    .unwrap_or(0);
                                format!("collection tab={id} view={view:?} items={count}")
                            }),
                            None => Err(format!(
                                "unknown collection view: {raw} (fav_videos|fav_images|labels[:LABEL_ID])"
                            )),
                        }
                    }
                    "remove_from_view" => {
                        let lane_id = self.compare_lanes.first().map(|lane| lane.id).unwrap_or(0);
                        self.remove_selected_from_collection(lane_id)
                    }
                    // WP-073: receipt-backed delete for the current selection.
                    // The explicit token is the confirmation a model cannot
                    // click; without it the intent rejects and deletes nothing.
                    "delete_selected" => {
                        let lane_id = self.compare_lanes.first().map(|lane| lane.id).unwrap_or(0);
                        self.media_delete_intent(lane_id, path.as_deref().unwrap_or_default())
                    }
                    // WP-074: select mode, the selection sheet, and
                    // destination-directed filing, all reachable headlessly.
                    "set_select_mode" => {
                        let wanted = path.as_deref().unwrap_or_default().to_ascii_lowercase();
                        let on = match wanted.as_str() {
                            "on" | "true" | "1" => true,
                            "off" | "false" | "0" => false,
                            other => {
                                return (
                                    false,
                                    format!("unknown select mode value: {other} (on|off)"),
                                )
                            }
                        };
                        self.media_select_mode = on;
                        self.media_tabs.active_mut().viewport.select_mode = on;
                        self.touch_media_settings();
                        Ok(format!("select mode {wanted}"))
                    }
                    "set_sheet" => {
                        let wanted = path.as_deref().unwrap_or_default().to_ascii_lowercase();
                        let lane_id = self.compare_lanes.first().map(|lane| lane.id).unwrap_or(0);
                        let selected = self.media_selected_paths(lane_id).len();
                        match wanted.as_str() {
                            "on" | "true" | "1" => {
                                if selected < 2 {
                                    return (
                                        false,
                                        format!(
                                            "the selection sheet needs a batch selection; {selected} \
                                             file(s) selected (select with media_select)"
                                        ),
                                    );
                                }
                                self.media_sheet_mode = true;
                                Ok(format!("selection sheet on with {selected} files"))
                            }
                            "off" | "false" | "0" => {
                                self.media_sheet_mode = false;
                                Ok("selection sheet off".to_string())
                            }
                            "names_on" => {
                                self.media_sheet_names = true;
                                Ok("selection sheet captions on".to_string())
                            }
                            "names_off" => {
                                self.media_sheet_names = false;
                                Ok("selection sheet captions off".to_string())
                            }
                            other => Err(format!(
                                "unknown sheet value: {other} (on|off|names_on|names_off)"
                            )),
                        }
                    }
                    "export_sheet" => {
                        let lane_id = self.compare_lanes.first().map(|lane| lane.id).unwrap_or(0);
                        let selected = self.media_selected_paths(lane_id).len();
                        if selected == 0 {
                            return (
                                false,
                                "no files selected; select with media_select first".to_string(),
                            );
                        }
                        self.export_media_contact_sheet(lane_id);
                        Ok(format!(
                            "contact sheet export dispatched for {selected} file(s); poll \
                             media_tabs --action list sheet_export until settled=true"
                        ))
                    }
                    // WP-075: the receiving pane, reachable headlessly. The
                    // drag gesture itself cannot be synthesized, but the
                    // backend it dispatches is move_to/copy_to, already proven.
                    "open_receiving_pane" => {
                        let Some(tab) = path.as_deref().map(str::trim).filter(|v| !v.is_empty())
                        else {
                            return (
                                false,
                                "open_receiving_pane requires --path TAB_ID".to_string(),
                            );
                        };
                        if !self
                            .media_tabs
                            .tabs()
                            .iter()
                            .any(|candidate| candidate.id.as_str() == tab)
                        {
                            return (false, format!("unknown media tab: {tab}"));
                        }
                        if self.media_tabs.active_id().as_str() == tab {
                            return (
                                false,
                                "that tab is already active on the left; choose another tab"
                                    .to_string(),
                            );
                        }
                        self.open_media_receiving_pane(tab);
                        match self.media_receiving_pane_folder.clone() {
                            Some(folder) => Ok(format!(
                                "right panel receiving into {folder} (tab {tab}); active tab \
                                 unchanged"
                            )),
                            None => Err(self.compare_action_message.clone()),
                        }
                    }
                    "close_receiving_pane" => {
                        if self.media_receiving_pane.is_none() {
                            return (false, "no receiving pane is open".to_string());
                        }
                        self.close_media_receiving_pane("closed by intent");
                        Ok("right panel back to Viewer".to_string())
                    }
                    "move_to" | "copy_to" => {
                        let Some(destination) = path
                            .as_deref()
                            .map(str::trim)
                            .filter(|value| !value.is_empty())
                        else {
                            return (
                                false,
                                format!("{action} requires --path DESTINATION_FOLDER"),
                            );
                        };
                        let lane_id = self.compare_lanes.first().map(|lane| lane.id).unwrap_or(0);
                        let sources = self.media_selected_paths(lane_id);
                        if sources.is_empty() {
                            return (
                                false,
                                "no files selected; select with media_select first".to_string(),
                            );
                        }
                        let kind = if action == "move_to" {
                            MediaDestinationKind::Move
                        } else {
                            MediaDestinationKind::Copy
                        };
                        let count = sources.len();
                        self.media_pending_destination = Some(MediaDestinationJob {
                            lane_id,
                            sources,
                            kind,
                        });
                        self.run_media_destination_job(PathBuf::from(destination));
                        Ok(format!(
                            "{} of {count} file(s) dispatched to {destination}; per-file outcomes \
                             appear in the message line and the destination tab rescans only if it \
                             is showing that folder",
                            kind.label()
                        ))
                    }
                    // WP-070: captions and tile size were GUI-only controls, so
                    // caption behaviour could not be reproduced on a live app —
                    // only through one hardcoded inspector preset at one size
                    // (no-context Manual audit, finding 4.4).
                    "set_names" => {
                        let wanted = path.as_deref().unwrap_or_default().to_ascii_lowercase();
                        let show = match wanted.as_str() {
                            "on" | "true" | "1" => true,
                            "off" | "false" | "0" => false,
                            other => {
                                return (false, format!("unknown names value: {other} (on|off)"))
                            }
                        };
                        self.media_explorer.show_names = show;
                        self.media_tabs.active_mut().viewport.show_names = show;
                        self.touch_media_settings();
                        Ok(format!("filename captions {wanted}"))
                    }
                    "set_tile_size" => {
                        let raw = path.as_deref().unwrap_or_default();
                        let Ok(points) = raw.trim().parse::<f32>() else {
                            return (
                                false,
                                format!(
                                    "tile size must be a number in points: {raw} (accepted range \
                                     {}..={})",
                                    crate::media_explorer::TILE_MIN,
                                    crate::media_explorer::TILE_MAX
                                ),
                            );
                        };
                        // Clamp rather than refuse, but report the applied value
                        // so a receipt never claims a size the grid is not using.
                        let edge = points.clamp(
                            crate::media_explorer::TILE_MIN,
                            crate::media_explorer::TILE_MAX,
                        );
                        self.media_explorer.tile_edge = edge;
                        self.media_tabs.active_mut().viewport.tile_edge = edge;
                        self.touch_media_settings();
                        Ok(format!("tile edge={edge} (requested {points})"))
                    }
                    other => Err(format!("unknown media tabs action: {other}")),
                };
                match result {
                    Ok(message) => (true, message),
                    Err(error) => (false, error),
                }
            }
            CommandKind::MediaFolderNavigate { action } => {
                if self.compare_lanes.is_empty() {
                    self.compare_lanes = vec![CompareLane::new(0)];
                    self.compare_next_lane_id = 1;
                }
                self.active_tab = Tab::Media;
                let lane_id = self.compare_lanes[0].id;
                let requires_open = !matches!(action.as_str(), "open" | "toggle" | "close");
                // WP-064: the navigator is also "active" while its pre-open
                // backdrop capture is in flight, during which show_folder_navigator
                // is deliberately false. Rejecting actions in that window made
                // every navigator command a coin flip against capture latency.
                if requires_open && !self.media_folder_navigator_active() {
                    return (
                        false,
                        "folder navigator is closed; send action=open first".to_string(),
                    );
                }
                // A queued action implies the operator/model wants the navigator
                // usable now. Resolve any in-flight capture to an open navigator
                // before applying the action so staged state is well defined.
                if requires_open && !self.media_explorer.show_folder_navigator {
                    self.settle_media_folder_navigator_capture(lane_id);
                }
                let mut render_request = CompareLaneRenderRequest::default();
                let mut action_applied = true;
                match action.as_str() {
                    "open" => {
                        if !self.media_explorer.show_folder_navigator {
                            self.folder_navigator_new_tab_mode = false;
                            self.open_media_folder_navigator_without_capture(lane_id);
                        }
                    }
                    "close" => self.close_media_folder_navigator(),
                    "toggle" => self.media_toggle_folder_navigator(ctx, lane_id),
                    "up" => self.media_navigator_move(lane_id, -1),
                    "down" => self.media_navigator_move(lane_id, 1),
                    "page_up" => self.media_navigator_move(lane_id, -8),
                    "page_down" => self.media_navigator_move(lane_id, 8),
                    "home" => {
                        self.media_explorer.folder_cursor =
                            (!self.media_folder_entries(lane_id).is_empty()).then_some(0);
                        self.media_explorer.folder_scroll_to_cursor = true;
                    }
                    "end" => {
                        self.media_explorer.folder_cursor =
                            self.media_folder_entries(lane_id).len().checked_sub(1);
                        self.media_explorer.folder_scroll_to_cursor = true;
                    }
                    "enter" => self.media_navigator_enter(lane_id),
                    "parent" => self.media_navigator_parent_or_close(lane_id),
                    "refresh" => render_request.refresh = true,
                    "commit" => {
                        if self.folder_navigator_new_tab_mode {
                            let target = sanitize_folder_input(
                                &self.media_explorer.folder_navigator_location,
                            );
                            if target.is_empty() {
                                action_applied = false;
                            } else {
                                render_request.open_folder_in_new_tab = Some(target);
                            }
                        } else {
                            action_applied =
                                self.media_navigator_commit_current(lane_id, &mut render_request);
                        }
                    }
                    "open_new_tab" => {
                        let target =
                            sanitize_folder_input(&self.media_explorer.folder_navigator_location);
                        if target.is_empty() {
                            action_applied = false;
                        } else {
                            render_request.open_folder_in_new_tab = Some(target);
                        }
                    }
                    _ => return (false, format!("unknown folder navigator action: {action}")),
                }
                if render_request.scan || render_request.refresh {
                    self.start_compare_scan(lane_id);
                }
                if let Some(path) = render_request.open_folder_in_new_tab.as_deref() {
                    action_applied = match self.open_media_folder_in_new_tab(path) {
                        Ok(_) => {
                            self.close_media_folder_navigator();
                            true
                        }
                        Err(error) => {
                            // WP-064: a failed commit must still release the
                            // modal. Leaving it open behind its blurred backdrop
                            // strands the operator with no route out.
                            self.compare_action_message = error;
                            self.close_media_folder_navigator();
                            false
                        }
                    };
                }
                (
                    action_applied,
                    format!(
                        "folder navigator action={action} open={} cursor={} staged='{}' active='{}' scan_requested={}",
                        self.media_explorer.show_folder_navigator,
                        self.media_explorer
                            .folder_cursor
                            .map(|index| index.to_string())
                            .unwrap_or_else(|| "none".to_string()),
                        self.media_explorer.folder_navigator_location,
                        self.compare_lane_position(lane_id)
                            .map(|pos| sanitize_folder_input(&self.compare_lanes[pos].folder))
                            .unwrap_or_default(),
                        render_request.scan,
                    ),
                )
            }
            CommandKind::MediaVideoControl {
                action,
                value,
                output,
            } => {
                if self.compare_lanes.is_empty() {
                    return (false, "media surface has no lane".to_string());
                }
                self.active_tab = Tab::Media;
                let lane_id = self.compare_lanes[0].id;
                let selected = self.media_selected_path(lane_id);
                let selected_video = selected
                    .as_deref()
                    .filter(|path| crate::media_explorer::is_video_path(path));
                let result: Result<String, String> = match action.as_str() {
                    "status" => self
                        .video_player
                        .active_path()
                        .map(|path| format!("video status for {path}"))
                        .or_else(|| {
                            self.media_pending_video_start
                                .as_ref()
                                .map(|pending| format!("video preparing for {}", pending.path))
                        })
                        .ok_or_else(|| "no embedded video is loaded".to_string()),
                    "play_pause" => selected_video
                        .ok_or_else(|| "selected item is not a video".to_string())
                        .and_then(|path| {
                            if self.video_player.active_path() == Some(path) {
                                self.match_video_toggle_pause()?;
                            } else {
                                self.queue_media_video_start(path, VideoSurfaceOwner::Viewer)?;
                            }
                            Ok("video play/pause applied".to_string())
                        }),
                    "play" => selected_video
                        .ok_or_else(|| "selected item is not a video".to_string())
                        .and_then(|path| {
                            self.queue_media_video_start(path, VideoSurfaceOwner::Viewer)?;
                            Ok("video preparing in Viewer panel".to_string())
                        }),
                    "play_library" => require_inline_library_playback().and_then(|()| {
                        selected_video
                            .ok_or_else(|| "selected item is not a video".to_string())
                            .and_then(|path| {
                                self.queue_media_video_start(path, VideoSurfaceOwner::Library)?;
                                Ok("video preparing in Library panel".to_string())
                            })
                    }),
                    "pause" => {
                        if self.video_player.active_path().is_none() {
                            Err("no embedded video is loaded".to_string())
                        } else {
                            self.video_player
                                .set_playing(false)
                                .map(|()| "video paused".to_string())
                        }
                    }
                    "stop" => {
                        self.media_pending_video_start = None;
                        self.video_player.stop();
                        self.media_inline_video_path = None;
                        self.media_inline_video_requested_at = None;
                        self.media_inline_video_pending_target = None;
                        self.media_playback_lease = None;
                        Ok("video stopped".to_string())
                    }
                    "seek_ms" => value
                        .ok_or_else(|| "seek_ms requires value".to_string())
                        .and_then(|milliseconds| {
                            if self.video_player.active_path().is_none() {
                                Err("no embedded video is loaded".to_string())
                            } else {
                                self.match_video_set_time(milliseconds)?;
                                Ok(format!("video seeked to {} ms", milliseconds.max(0)))
                            }
                        }),
                    "volume" => value
                        .ok_or_else(|| "volume requires value".to_string())
                        .and_then(|volume| {
                            if self.video_player.active_path().is_none() {
                                Err("no embedded video is loaded".to_string())
                            } else {
                                let volume = volume.clamp(0, 125) as i32;
                                self.video_player.set_volume(volume)?;
                                Ok(format!("video volume set to {volume}"))
                            }
                        }),
                    "audio_track" => value
                        .ok_or_else(|| "audio_track requires value".to_string())
                        .and_then(|track| {
                            if self.video_player.active_path().is_none() {
                                Err("no embedded video is loaded".to_string())
                            } else {
                                self.video_player.set_audio_track(track as i32)?;
                                Ok(format!("audio track set to {track}"))
                            }
                        }),
                    "subtitle_track" => value
                        .ok_or_else(|| "subtitle_track requires value".to_string())
                        .and_then(|track| {
                            if self.video_player.active_path().is_none() {
                                Err("no embedded video is loaded".to_string())
                            } else {
                                self.video_player.set_subtitle_track(track as i32)?;
                                Ok(format!("subtitle track set to {track}"))
                            }
                        }),
                    "loop" => value
                        .ok_or_else(|| "loop requires value 0 or 1".to_string())
                        .and_then(|enabled| {
                            if !matches!(enabled, 0 | 1) {
                                return Err("loop requires value 0 (off) or 1 (on)".to_string());
                            }
                            let enabled = enabled != 0;
                            self.video_player.set_loop(enabled)?;
                            self.media_explorer.video_loop = enabled;
                            self.touch_media_settings();
                            Ok(format!(
                                "video loop {}",
                                if enabled { "enabled" } else { "disabled" }
                            ))
                        }),
                    "capture_frame" => {
                        let path = self.media_video_capture_path(output.as_deref(), &cmd.action_id);
                        self.video_player
                            .capture_frame(&path)
                            .map(|()| format!("video frame captured: {}", path.to_string_lossy()))
                    }
                    _ => Err(format!("unknown video action: {action}")),
                };
                if result.is_ok()
                    && matches!(
                        action.as_str(),
                        "play_pause"
                            | "play"
                            | "play_library"
                            | "pause"
                            | "seek_ms"
                            | "volume"
                            | "audio_track"
                            | "subtitle_track"
                    )
                {
                    // A paused remote video still needs a short quiet period
                    // around direct interaction. The next paused-state sync
                    // drops this lease and starts coordinator hysteresis.
                    self.begin_media_playback_priority();
                }
                match result {
                    Ok(message) => {
                        match explicit_video_owner(action) {
                            ExplicitVideoOwner::Library | ExplicitVideoOwner::Viewer => {}
                            ExplicitVideoOwner::Preserve => {}
                        }
                        (true, message)
                    }
                    Err(error) => (false, error),
                }
            }
            CommandKind::MediaLabelMutation {
                action,
                path,
                id,
                name,
                hex,
                confirmed,
            } => {
                let result: Result<String, String> = match action.as_str() {
                    "create" => {
                        let name = name
                            .as_deref()
                            .ok_or_else(|| "label create requires name".to_string());
                        let hex = hex
                            .as_deref()
                            .ok_or_else(|| "label create requires hex".to_string());
                        name.and_then(|name| {
                            hex.and_then(|hex| {
                                if let Some(path) = path.as_deref() {
                                    self.media_db.create_color_label_and_assign(path, name, hex)
                                } else {
                                    self.media_db.create_color_label(name, hex)
                                }
                                .map(|definition| format!("label {} created", definition.id))
                            })
                        })
                    }
                    "update" => id
                        .as_deref()
                        .ok_or_else(|| "label update requires id".to_string())
                        .and_then(|id| {
                            self.media_db
                                .update_color_label(id, name.as_deref(), hex.as_deref())
                                .map(|definition| format!("label {} updated", definition.id))
                        }),
                    "delete" => id
                        .as_deref()
                        .ok_or_else(|| "label delete requires id".to_string())
                        .and_then(|id| {
                            self.media_db
                                .delete_color_label(id, *confirmed)
                                .map(|result| {
                                    format!(
                                        "label {} deleted; {} assignments removed",
                                        result.id, result.assignments_removed
                                    )
                                })
                        }),
                    "add" => path
                        .as_deref()
                        .ok_or_else(|| "label add requires path".to_string())
                        .and_then(|path| {
                            id.as_deref()
                                .ok_or_else(|| "label add requires id or name".to_string())
                                .and_then(|id| self.media_db.add_label(path, id))
                                .map(|labels| format!("labels assigned: {}", labels.join(", ")))
                        }),
                    "remove" => path
                        .as_deref()
                        .ok_or_else(|| "label remove requires path".to_string())
                        .and_then(|path| {
                            id.as_deref()
                                .ok_or_else(|| "label remove requires id or name".to_string())
                                .and_then(|id| self.media_db.remove_label(path, id))
                                .map(|labels| format!("labels assigned: {}", labels.join(", ")))
                        }),
                    "clear" => path
                        .as_deref()
                        .ok_or_else(|| "label clear requires path".to_string())
                        .and_then(|path| {
                            self.media_db
                                .clear_labels(path)
                                .map(|()| "labels cleared".to_string())
                        }),
                    other => Err(format!("unknown label mutation action: {other}")),
                };
                match result {
                    Ok(message) => {
                        self.load_media_metadata();
                        self.media_meta_generation = self.media_meta_generation.wrapping_add(1);
                        (true, message)
                    }
                    Err(error) => (false, error),
                }
            }
            CommandKind::MatchSettingsManagePeople
            | CommandKind::MatchEditorAutocomplete(..)
            | CommandKind::MatchRuntimeDiagnostics => (
                false,
                "Match UI endpoints must run through the rendered completion queue".to_string(),
            ),
            CommandKind::MatchIntent { .. } => (
                false,
                "Match intents must run through the background completion queue".to_string(),
            ),
            CommandKind::MatchMaintenance(..) => (
                false,
                "Match maintenance must run through the background completion queue".to_string(),
            ),
            CommandKind::MatchCorrection(..) => (
                false,
                "Match corrections must run through the background completion queue".to_string(),
            ),
            CommandKind::MatchBatchCorrectionPreflight(..) => (
                false,
                "Match batch preflights must run through the background completion queue"
                    .to_string(),
            ),
            CommandKind::MatchSplitPersonPreflight(..) => (
                false,
                "Match split preflights must run through the background completion queue"
                    .to_string(),
            ),
            other => (
                false,
                format!("not a ui-intent (backend command): {}", other.id_str()),
            ),
        }
    }

    /// Build api::AppStateSnapshot from current FacialApp + service state.
    fn current_state_snapshot(&mut self) -> api::AppStateSnapshot {
        self.snapshot_active_media_tab();
        let (models, plugins, worktrees, lanes) = match self.service.lock() {
            Ok(mut svc) => {
                let models = svc.list_models();
                let plugins = svc
                    .list_plugins()
                    .into_iter()
                    .filter_map(|value| {
                        serde_json::from_value::<crate::plugin_host::PluginManifest>(value).ok()
                    })
                    .collect::<Vec<_>>();
                let mut worktrees = BTreeMap::new();
                for (project, runs) in svc.list_worktrees() {
                    worktrees.insert(
                        project,
                        runs.into_iter()
                            .map(|path| path.to_string_lossy().to_string())
                            .collect(),
                    );
                }
                let lanes = svc.list_lanes().unwrap_or_default();
                (models, plugins, worktrees, lanes)
            }
            Err(_) => (Vec::new(), Vec::new(), BTreeMap::new(), Vec::new()),
        };

        let mut selected: Vec<String> = self.selected_features.iter().cloned().collect();
        selected.sort();
        let match_state = self.match_public_snapshot.clone();

        api::AppStateSnapshot {
            protocol_version: api::API_PROTOCOL_VERSION,
            captured_at: chrono::Utc::now().to_rfc3339(),
            repo_root: self.config.repo_root.to_string_lossy().to_string(),
            workspace_root: self.config.workspace_root.to_string_lossy().to_string(),
            worktrees_root: self.config.worktrees_root.to_string_lossy().to_string(),
            api_root: self.config.api_root.to_string_lossy().to_string(),
            ingest_in_place_default: self.config.ingest_in_place_default,
            models,
            plugins,
            worktrees,
            lanes,
            active_tab: self.active_tab.vocab().to_string(),
            project_name: self.project_name.clone(),
            worktree_path: self.worktree_path.clone(),
            in_place: self.in_place,
            selected_features: selected,
            running_pipeline: self.running_pipeline,
            run_output: self.run_output.clone(),
            media_tabs: serde_json::json!({
                "active_tab_id": self.media_tabs.active_id().as_str(),
                "tabs": self.media_tabs.tabs().iter().map(|tab| {
                    let path = if tab.viewport.folder_key.is_empty() {
                        String::new()
                    } else {
                        self.media_db.path_for_key(&tab.viewport.folder_key)
                    };
                    serde_json::json!({
                        "id": tab.id.as_str(),
                        "title": crate::media_tabs::folder_tab_title(&path),
                        "folder_key": tab.viewport.folder_key,
                        "folder": path,
                        "search_query": tab.viewport.search_query,
                        "kind": tab.viewport.kind,
                        "match_person_id": tab.viewport.match_person_id,
                        "match_person_name": tab.viewport.match_person_name,
                        "match_identity_revision": tab.viewport.match_identity_revision,
                        "match_catalog_revision": tab.viewport.match_catalog_revision,
                        "match_total_media": tab.viewport.match_total_media,
                        "match_unresolved_media": tab.viewport.match_unresolved_media,
                    })
                }).collect::<Vec<_>>(),
                "selection_restore_pending": self.media_tab_pending_selection_keys,
                "cursor_restore_pending": self.media_tab_pending_cursor_key,
                "load_status": self.media_tabs_load_status,
                "persistence_blocked": self.media_tabs_persistence_blocked,
            }),
            media_folder_navigation: serde_json::json!({
                "open": self.media_explorer.show_folder_navigator,
                "staged_folder": self.media_explorer.folder_navigator_location,
                "committed_folder": self.compare_lanes.first().map(|lane| sanitize_folder_input(&lane.folder)).unwrap_or_default(),
            }),
            media_controller: serde_json::json!({
                "gilrs_initialized": self.controller_gilrs.is_some(),
                "input_enabled": self.controller_input_enabled,
                "active_gamepad": self.controller_active.map(|id| format!("{id:?}")),
                "legacy_active": self.controller_legacy_active,
                "input_source": self.controller_input_source,
                "input_device_id": self.controller_input_device_id,
                "input_device_name": self.controller_input_device_name,
                "gamepads": self.controller_gilrs.as_ref().map(|gilrs| gilrs.gamepads().map(|(id, pad)| serde_json::json!({
                    "id": format!("{id:?}"),
                    "name": pad.name(),
                    "connected": pad.is_connected(),
                })).collect::<Vec<_>>()).unwrap_or_default(),
                "pointer_mode": self.controller_pointer_mode,
            }),
            media_video: serde_json::json!({
                "available": self.video_player_available,
                "placement": if self.video_player.active_path().is_none() {
                    serde_json::Value::Null
                } else if self.media_inline_video_path.is_some() {
                    serde_json::Value::String("library".to_string())
                } else {
                    serde_json::Value::String("viewer".to_string())
                },
                "active_path": self.video_player.active_path(),
                "snapshot": self.video_player.cached_snapshot(),
                "diagnostics": self.video_player.diagnostics(),
                "last_error": self.video_player.last_error(),
            }),
            match_state,
        }
    }

    fn refresh_all(&mut self) {
        if let Ok(mut svc) = Arc::clone(&self.service).lock() {
            self.models = Self::load_models(&mut svc);
            self.worktree_view = Self::load_worktrees(&mut svc);
            self.feature_rows = Self::load_features(&mut svc);
            self.selected_features.clear();
        }
        self.manual_text = Self::load_manual(&self.config.repo_root);
        self.video_player_available = crate::video_player::VideoPlayer::available();
        // Give failed thumbnails another chance (files may have been fixed).
        if let Some(engine) = self.thumb_engine.as_mut() {
            engine.forget_failures();
        }
    }

    // -----------------------------------------------------------------------
    // Rendering (flat, hairline dividers, no cards)
    // -----------------------------------------------------------------------

    fn draw_header(&mut self, ui: &mut egui::Ui) {
        ui.horizontal(|ui| {
            theme::logomark(ui, 22.0);
            ui.add_space(2.0);
            ui.label(
                egui::RichText::new("facial")
                    .heading()
                    .strong()
                    .color(theme::ink()),
            );
            ui.add_space(14.0);
            const COMPACT_TABS: [Tab; 4] = [
                Tab::Media,
                Tab::Match,
                Tab::Timeline,
                Tab::Project,
            ];
            const COMPACT_MORE: [Tab; 6] = [
                Tab::RunDebug,
                Tab::Compare,
                Tab::QualityIq,
                Tab::Identity,
                Tab::Duplicates,
                Tab::Manual,
            ];
            let compact = ui.available_width() < 1_150.0;
            let visible_tabs: &[Tab] = if compact { &COMPACT_TABS } else { &Tab::ALL };
            for &t in visible_tabs {
                // Text-only tabs (WP-048): icon+label crowded the strip and
                // brutalist-minimal reads better as plain words.
                if theme::tab_item(ui, self.active_tab == t, t.label()) {
                    self.active_tab = t;
                    self.show_manual = t == Tab::Manual;
                }
                ui.add_space(10.0);
            }
            if compact {
                let more_label = COMPACT_MORE
                    .contains(&self.active_tab)
                    .then(|| self.active_tab.label())
                    .unwrap_or("More");
                ui.menu_button(more_label, |ui| {
                    for tab in COMPACT_MORE {
                        if ui
                            .selectable_label(self.active_tab == tab, tab.label())
                            .clicked()
                        {
                            self.active_tab = tab;
                            self.show_manual = tab == Tab::Manual;
                            ui.close_menu();
                        }
                    }
                });
                ui.add_space(10.0);
            }
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                if ui
                    .button(format!("{} Refresh", icons::ARROW_CLOCKWISE))
                    .on_hover_text("Global refresh: reload models, worktrees, features, the manual, and failed thumbnail state (F5)")
                    .clicked()
                {
                    self.refresh_all();
                }
                if ui
                    .button(format!("{} Settings", icons::GEAR))
                    .on_hover_text("Unified Media and app settings")
                    .clicked()
                {
                    self.active_tab = Tab::Media;
                    self.request_media_settings(ui.ctx(), 4);
                }
            });
        });
    }

    /// Slim bottom status bar: workspace at left, live state at right.
    fn draw_status_bar(&mut self, ui: &mut egui::Ui) {
        ui.horizontal(|ui| {
            ui.add(
                egui::Label::new(
                    egui::RichText::new(format!(
                        "{} {}",
                        icons::FOLDER,
                        elide_middle(&self.workspace_root, 52)
                    ))
                    .small()
                    .color(theme::ink_faint()),
                )
                .wrap(false),
            )
            .on_hover_text(&self.workspace_root);
            ui.label(egui::RichText::new("·").small().color(theme::ink_faint()));
            if self.copy_location.trim().is_empty() {
                ui.label(
                    egui::RichText::new("output folder not set")
                        .small()
                        .color(theme::warn_ink()),
                );
            } else {
                ui.label(
                    egui::RichText::new("output ready")
                        .small()
                        .color(theme::ok_ink()),
                );
            }
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                let busy = self.running_pipeline
                    || self
                        .compare_lanes
                        .iter()
                        .any(|lane| lane.scanning || lane.loading_image_inflight);
                let (status, color) = if busy {
                    ("working…".to_string(), theme::accent())
                } else {
                    (elide_middle(&self.pipeline_status, 64), theme::ink_faint())
                };
                ui.add(
                    egui::Label::new(egui::RichText::new(status).small().color(color)).wrap(false),
                );
            });
        });
    }

    fn defer_match_action(
        &mut self,
        action: impl FnOnce(&mut FacialApp, &egui::Context) + 'static,
    ) {
        self.deferred_match_actions.push(Box::new(action));
    }

    fn current_match_navigation_context(&self) -> MatchNavigationContext {
        MatchNavigationContext {
            tab: self.active_tab,
            media_tab_id: self.media_tabs.active_id().as_str().to_string(),
            media_path: self
                .compare_lanes
                .first()
                .and_then(|lane| self.media_selected_path(lane.id)),
            workspace_root: self.config.workspace_root.clone(),
            subview: self.match_subview,
            person_id: self.match_selected_person.clone(),
            settings: self.media_explorer.show_settings
                || self.settings_backdrop_requested_at.is_some(),
            settings_category: self.media_explorer.settings_category,
            immersive: self.media_explorer.chrome_hidden,
            view_mode: self.media_explorer.view_mode,
            editor_active: self.match_face_editor.active()
                && !self.media_explorer.show_settings
                && self.settings_backdrop_requested_at.is_none(),
            editor_face_id: if self.active_tab == Tab::Media
                && self.match_face_editor.active()
                && !self.media_explorer.show_settings
                && self.settings_backdrop_requested_at.is_none()
            {
                self.match_face_editor
                    .selected_face_id()
                    .map(str::to_string)
            } else {
                None
            },
        }
    }

    fn observe_match_navigation(&mut self) {
        let context = self.current_match_navigation_context();
        if self.match_navigation_context.as_ref() != Some(&context) {
            self.match_navigation_epoch = self.match_navigation_epoch.wrapping_add(1);
            self.match_navigation_context = Some(context);
        }
    }

    fn capture_match_navigation(&mut self) -> MatchNavigationFence {
        self.observe_match_navigation();
        MatchNavigationFence {
            epoch: self.match_navigation_epoch,
            context: self.current_match_navigation_context(),
        }
    }

    fn match_navigation_is_current(&mut self, fence: &MatchNavigationFence) -> bool {
        self.observe_match_navigation();
        fence.epoch == self.match_navigation_epoch
            && fence.context == self.current_match_navigation_context()
    }

    fn drain_deferred_match_actions(&mut self, ctx: &egui::Context) {
        let actions = std::mem::take(&mut self.deferred_match_actions);
        for action in actions {
            action(self, ctx);
        }
    }

    fn request_match_snapshot(&mut self, ctx: &egui::Context) -> bool {
        if self.match_snapshot_loading {
            return false;
        }
        self.match_snapshot_loading = true;
        let offset = self.match_people_offset;
        let service = Arc::clone(&self.service);
        let tx = self.compare_work_tx.clone();
        let repaint = ctx.clone();
        thread::spawn(move || {
            let result = service
                .lock()
                .map_err(|_| "Match service lock is poisoned".to_string())
                .and_then(|service| {
                    Ok((
                        service.match_ui_snapshot(offset, 256)?,
                        service.match_public_snapshot()?,
                    ))
                });
            let _ = tx.send(CompareWorkEvent::MatchSnapshotReady(result));
            repaint.request_repaint();
        });
        true
    }

    fn queue_background_match_intent(&mut self, ctx: &egui::Context, command: ApiCommand) -> bool {
        let started = std::time::Instant::now();
        let rendered_action = Self::match_rendered_intent_action(&command).filter(|action| {
            !matches!(*action, "pause_all" | "resume_all")
                || self.match_settings_render_context_current()
        });
        if self.match_snapshot_loading
            || self.pending_match_rendered_intent.is_some()
            || (rendered_action.is_some() && self.pending_match_ui_endpoint.is_some())
        {
            if rendered_action.is_some() {
                let result = self.match_rendered_intent_result(&command, started, None, false);
                self.finish_bounded_match_endpoint(
                    command,
                    false,
                    "Match operation busy".into(),
                    result,
                );
                return true;
            }
            self.finish_background_match_intent(
                command,
                false,
                "match_operation_busy".to_string(),
                serde_json::Value::Null,
            );
            return true;
        }
        let action = match &command.command {
            CommandKind::MatchIntent { action, .. } => action.clone(),
            _ => return false,
        };
        match action.as_str() {
            "open_people" | "open_suggestions" | "open_unidentified" => {
                self.active_tab = Tab::Match;
                self.match_subview = match action.as_str() {
                    "open_people" => MatchSubview::People,
                    "open_suggestions" => MatchSubview::Suggestions,
                    _ => MatchSubview::Unidentified,
                };
                if action == "open_people" {
                    self.match_selected_person = None;
                    self.match_gallery_snapshot = serde_json::Value::Null;
                    self.match_person_faces_snapshot = serde_json::Value::Null;
                    self.match_selected_faces.clear();
                    self.match_batch_target_person = None;
                    self.match_single_face_look_id = None;
                    self.match_single_face_new_look_name.clear();
                    self.clear_match_person_edit_preflights();
                    self.clear_match_split_preflight();
                    self.clear_match_batch_preflights();
                }
            }
            "open_settings" => {
                self.active_tab = Tab::Media;
                self.match_settings_offset = match &command.command {
                    CommandKind::MatchIntent { offset, .. } => offset
                        .and_then(|value| usize::try_from(value).ok())
                        .unwrap_or(0),
                    _ => 0,
                };
                self.request_media_settings(ctx, 3);
            }
            "open_person_faces" => {
                self.active_tab = Tab::Match;
                self.match_subview = MatchSubview::People;
            }
            _ => {}
        }
        self.match_snapshot_loading = true;
        self.match_message = format!("{action} in progress…");
        self.pending_match_model_intent = Some(command.action_id.clone());
        let service = Arc::clone(&self.service);
        let tx = self.compare_work_tx.clone();
        let repaint = ctx.clone();
        let match_io = Arc::clone(&self.media_io);
        let people_offset = self.match_people_offset;
        let settings_offset = self.match_settings_offset;
        let work_command = command.clone();
        let navigation = self.capture_match_navigation();
        let rendered_cancellation = rendered_action
            .is_some()
            .then(|| Arc::new(AtomicBool::new(false)));
        if rendered_action.is_some() {
            self.match_rendered_intent_inflight = Some(command.action_id.clone());
            self.pending_match_rendered_intent = Some(PendingMatchRenderedIntent {
                command: command.clone(),
                navigation: navigation.clone(),
                started,
                cancelled: Arc::clone(rendered_cancellation.as_ref().unwrap()),
                expected_state: None,
                painted: false,
                rendered_at: None,
            });
        }
        thread::spawn(move || {
            let result = (|| -> Result<MatchIntentOutcome, String> {
                let service = service
                    .lock()
                    .map_err(|_| "Match service lock is poisoned".to_string())?;
                // A queued rendered request must not begin backend work after its terminal failure.
                if rendered_cancellation.as_ref().is_some_and(|cancelled| {
                    cancelled.load(Ordering::Acquire)
                        || started.elapsed() >= std::time::Duration::from_secs(2)
                }) {
                    return Err("Match rendered intent expired before backend execution".into());
                }
                let CommandKind::MatchIntent {
                    action,
                    id,
                    target_id,
                    name,
                    aliases,
                    path,
                    exclusions,
                    expected_revision,
                    cover_media_key,
                    hidden,
                    favorite,
                    offset,
                } = &work_command.command
                else {
                    return Err("not a Match intent".to_string());
                };

                let requested_offset = offset
                    .map(|value| {
                        usize::try_from(value).map_err(|_| "Match offset exceeds this platform")
                    })
                    .transpose()?;
                let catalog_offset =
                    match_query_offset(action, requested_offset, people_offset, settings_offset);
                let mut gallery = None;
                let mut ui_snapshot = None;
                let mut settings_snapshot = None;
                let mut viewer_snapshot = None;
                let mut person_faces_snapshot = None;
                let mut explicit_terminal_result = None;
                let message = match action.as_str() {
                    "open_people" | "open_suggestions" | "open_unidentified" | "refresh" => {
                        ui_snapshot = Some(service.match_ui_snapshot(catalog_offset, 256)?);
                        if action == "refresh" {
                            "Match refresh completed".to_string()
                        } else {
                            format!("{action} opened")
                        }
                    }
                    "open_settings" => {
                        settings_snapshot =
                            Some(service.match_settings_snapshot_page(catalog_offset, 200)?);
                        "Match Settings opened".to_string()
                    }
                    "open_person" => {
                        let person_id = id.as_deref().unwrap_or_default();
                        let person_offset = match_query_offset(
                            action,
                            requested_offset,
                            people_offset,
                            settings_offset,
                        );
                        gallery =
                            Some(service.match_person_gallery(person_id, person_offset, 512)?);
                        format!("Match Person {person_id} gallery opened")
                    }
                    "open_media_faces" => {
                        let media_key = id.as_deref().unwrap_or_default();
                        let snapshot = service.match_media_faces(media_key)?;
                        explicit_terminal_result = Some(snapshot.clone());
                        viewer_snapshot = Some((media_key.to_string(), snapshot));
                        format!("Match faces for media {media_key} opened")
                    }
                    "open_person_faces" => {
                        let person_id = id.as_deref().unwrap_or_default();
                        let person_offset = requested_offset.unwrap_or_default();
                        let snapshot = service.match_person_faces(person_id, person_offset, 256)?;
                        explicit_terminal_result = Some(snapshot.clone());
                        person_faces_snapshot = Some((person_id.to_string(), snapshot));
                        format!("Canonical faces for Person {person_id} opened")
                    }
                    "person_edit_preflight" => {
                        let person_id = id.as_deref().unwrap_or_default();
                        let preview = service
                            .match_person_edit_preflights(person_id, target_id.as_deref())?;
                        explicit_terminal_result = Some(preview);
                        format!("Exact Person edit preflight for {person_id} completed")
                    }
                    "create_person" => {
                        let person = service.match_create_person(
                            name.as_deref().unwrap_or_default(),
                            aliases.clone(),
                        )?;
                        ui_snapshot = service.match_ui_snapshot(people_offset, 256).ok();
                        format!(
                            "Person {} created",
                            person["person_id"].as_str().unwrap_or("?")
                        )
                    }
                    "update_person" => {
                        let person = service.match_update_person(
                            id.as_deref().unwrap_or_default(),
                            expected_revision.unwrap_or_default(),
                            name.as_deref().unwrap_or_default(),
                            aliases.clone(),
                        )?;
                        ui_snapshot = service.match_ui_snapshot(people_offset, 256).ok();
                        format!(
                            "Person {} updated",
                            person["person_id"].as_str().unwrap_or("?")
                        )
                    }
                    "set_person_preferences" => {
                        let person = service.match_update_person_preferences(
                            id.as_deref().unwrap_or_default(),
                            expected_revision.unwrap_or_default(),
                            cover_media_key.clone(),
                            hidden.unwrap_or(false),
                            favorite.unwrap_or(false),
                        )?;
                        ui_snapshot = service.match_ui_snapshot(people_offset, 256).ok();
                        format!(
                            "Person {} preferences updated",
                            person["person_id"].as_str().unwrap_or("?")
                        )
                    }
                    "configure_root" => {
                        let root = service.match_configure_root(
                            path.as_deref().unwrap_or_default(),
                            exclusions.clone(),
                        )?;
                        settings_snapshot = service.match_settings_snapshot().ok();
                        format!(
                            "Match root {} configured",
                            root["root_id"].as_str().unwrap_or("?")
                        )
                    }
                    "remove_root" => {
                        service.match_remove_root(id.as_deref().unwrap_or_default())?;
                        settings_snapshot = service.match_settings_snapshot().ok();
                        "Match root removed".to_string()
                    }
                    "start" => {
                        let job = service.match_start_job_with_io(
                            id.as_deref().unwrap_or_default(),
                            Arc::clone(&match_io),
                        )?;
                        settings_snapshot = service.match_settings_snapshot().ok();
                        format!(
                            "Match job {} started",
                            job["job_id"].as_str().unwrap_or("?")
                        )
                    }
                    "pause" | "resume" | "cancel" | "retry" => {
                        let job = service.match_control_job_with_io(
                            id.as_deref().unwrap_or_default(),
                            action,
                            Arc::clone(&match_io),
                        )?;
                        settings_snapshot = service.match_settings_snapshot().ok();
                        format!(
                            "Match job {} is {}",
                            job["job_id"].as_str().unwrap_or("?"),
                            job["lifecycle"].as_str().unwrap_or("unknown")
                        )
                    }
                    "pause_all" | "resume_all" => {
                        let paused = action == "pause_all";
                        service.match_set_operator_paused_with_io(paused, Arc::clone(&match_io))?;
                        settings_snapshot = service.match_settings_snapshot().ok();
                        if paused {
                            "Match automatic analysis paused".to_string()
                        } else {
                            "Match automatic analysis resumed".to_string()
                        }
                    }
                    other => return Err(format!("unknown Match intent action: {other}")),
                };
                let mut public_result = service.match_public_snapshot().unwrap_or_else(|_| {
                    serde_json::json!({
                        "availability": "snapshot_failed",
                        "error_code": "match_public_snapshot_unavailable"
                    })
                });
                if let (Some(object), Some(navigation)) = (
                    public_result.as_object_mut(),
                    match_navigation_receipt(
                        action,
                        requested_offset,
                        ui_snapshot.as_ref(),
                        settings_snapshot.as_ref(),
                        gallery.as_ref(),
                    ),
                ) {
                    object.insert("navigation".to_string(), navigation);
                }
                let terminal_result =
                    explicit_terminal_result.unwrap_or_else(|| public_result.clone());
                Ok(MatchIntentOutcome {
                    message,
                    public_result,
                    terminal_result,
                    ui_snapshot,
                    settings_snapshot,
                    gallery,
                    viewer_snapshot,
                    person_faces_snapshot,
                })
            })();
            let _ = tx.send(CompareWorkEvent::MatchIntentReady {
                command,
                navigation,
                result,
            });
            repaint.request_repaint();
        });
        true
    }

    fn queue_background_match_cluster_review(
        &mut self,
        ctx: &egui::Context,
        command: ApiCommand,
    ) -> bool {
        let CommandKind::MatchClusterReview(request) = &command.command else {
            return false;
        };
        if let Err(error) = api::validate_match_cluster_review(request) {
            self.finish_background_match_intent(command, false, error, serde_json::Value::Null);
            return true;
        }
        if self.match_video_ui.busy {
            self.finish_background_match_intent(
                command,
                false,
                "Match review request already pending".into(),
                serde_json::Value::Null,
            );
            return true;
        }
        self.match_video_ui.generation = self.match_video_ui.generation.wrapping_add(1);
        let generation = self.match_video_ui.generation;
        self.match_video_ui.busy = true;
        self.match_video_ui.cluster_review = serde_json::Value::Null;
        let request = request.clone();
        let service = Arc::clone(&self.service);
        let tx = self.compare_work_tx.clone();
        let repaint = ctx.clone();
        thread::spawn(move || {
            let result = service
                .lock()
                .map_err(|_| "service lock poisoned".to_string())
                .and_then(|service| service.match_cluster_review(&request));
            let _ = tx.send(CompareWorkEvent::MatchClusterReviewReady {
                command,
                generation,
                result,
            });
            repaint.request_repaint();
        });
        true
    }

    fn draw_match_cluster_review(&mut self, ui: &mut egui::Ui) {
        ui.label("Unnamed cluster review — explicit selected Faces only");
        ui.label("Review only: no assignment, naming or trust changes.");
        ui.add_enabled_ui(!self.match_video_ui.busy, |ui| {
            let state = &mut self.match_video_ui;
            let mut changed = false;
            ui.label(format!(
                "{} selected Faces (maximum 256)",
                state.cluster_ids.len()
            ));
            for (label, value) in [
                ("Model generation (required)", &mut state.cluster_model),
                (
                    "Similarity threshold [-1, 1] (required)",
                    &mut state.cluster_similarity,
                ),
                (
                    "Minimum quality [0, 1] (required)",
                    &mut state.cluster_quality,
                ),
                (
                    "Minimum independent families [1, 256] (required)",
                    &mut state.cluster_families,
                ),
            ] {
                ui.label(label);
                changed |= ui.text_edit_singleline(value).changed();
            }
            if changed {
                state.cluster_review = serde_json::Value::Null;
            }
            let request = cluster_request_from_inputs(state);
            if ui
                .add_enabled(
                    request.is_ok(),
                    egui::Button::new("Review selected unnamed clusters"),
                )
                .clicked()
            {
                let request = request.expect("enabled only for valid explicit policy");
                self.defer_match_action(move |app, ctx| {
                    app.queue_background_match_cluster_review(
                        ctx,
                        ApiCommand {
                            action_id: format!("cluster-review-{}", uuid::Uuid::new_v4().simple()),
                            protocol_version: api::API_PROTOCOL_VERSION,
                            actor: Some("operator".into()),
                            issued_at: None,
                            command: CommandKind::MatchClusterReview(request),
                        },
                    );
                });
            }
        });
        if let Some(rows) = self.match_video_ui.cluster_review["rows"].as_array() {
            for row in rows.iter().take(256) {
                ui.label(format!(
                    "Face {} · cluster {} · independent families {} · {}",
                    row["face_id"],
                    row["cluster_id"],
                    row["independent_families"],
                    row["exclusion_reason"]
                        .as_str()
                        .unwrap_or("review candidate")
                ));
            }
        }
    }

    fn queue_background_match_video(&mut self, ctx: &egui::Context, command: ApiCommand) -> bool {
        let CommandKind::MatchVideo(request) = &command.command else {
            return false;
        };
        if let Err(error) = api::validate_match_video(request) {
            self.finish_background_match_intent(command, false, error, serde_json::Value::Null);
            return true;
        }
        if self.match_video_ui.busy {
            self.finish_background_match_intent(
                command,
                false,
                "video appearance request already pending".into(),
                serde_json::Value::Null,
            );
            return true;
        }
        self.match_video_ui.generation = self.match_video_ui.generation.wrapping_add(1);
        let generation = self.match_video_ui.generation;
        self.match_video_ui.busy = true;
        let request = request.clone();
        let service = Arc::clone(&self.service);
        let tx = self.compare_work_tx.clone();
        let repaint = ctx.clone();
        let coordinator = Arc::clone(&self.media_io);
        if matches!(
            request.action,
            api::MatchVideoAction::InspectAppearance | api::MatchVideoAction::SeekAppearance
        ) {
            self.match_video_ui.inspection = None;
            self.match_video_ui.inspection_pending =
                request.action == api::MatchVideoAction::InspectAppearance;
            self.match_video_ui.appearance_seek_preparing =
                request.action == api::MatchVideoAction::SeekAppearance;
            if self.match_video_ui.appearance_seek_preparing {
                self.match_external_holds.set_playback(true);
            }
            let cancelled = Arc::new(std::sync::atomic::AtomicBool::new(false));
            self.match_video_ui.inspection_cancel = Some(Arc::clone(&cancelled));
            self.media_pending_video_start = None;
            if self.video_player.active_path().is_some() {
                if let Err(error) = self.video_player.set_playing(false) {
                    self.match_video_ui.busy = false;
                    self.clear_match_inspection();
                    self.finish_background_match_intent(
                        command,
                        false,
                        error,
                        serde_json::Value::Null,
                    );
                    return true;
                }
            }
            self.reconcile_video_surface();
            thread::spawn(move || {
                // Clone ready storage under a short guard; no source I/O, process work,
                // or decoding may retain the render thread's service mutex.
                let store = {
                    service
                        .lock()
                        .map_err(|_| "service lock poisoned".to_string())
                        .and_then(|service| service.inspection_store())
                };
                let result = store.and_then(|store| {
                    FacialService::match_inspect_appearance(
                        store,
                        &request,
                        &coordinator,
                        &cancelled,
                    )
                });
                if request.action == api::MatchVideoAction::SeekAppearance {
                    let result = result.and_then(|frame| {
                        let profile = crate::video_player::AppearancePlaybackProfile::for_container(frame.sample.container)?;
                        let time = frame.sample.time;
                        let origin = frame.sample.playback_origin;
                        let pin = frame.playback_pin.as_ref().map(Arc::clone).ok_or("native source pin missing")?;
                        Ok((serde_json::json!({
                            "media_key":request.media_key,"track_id":request.track_id,
                            "track_revision":request.track_revision,"timestamp":time,"playback_origin":origin,
                            "seek_ms":time.playback_milliseconds(origin)?,
                            "native_seek_ms":profile.seek_milliseconds(time,origin)?,
                            "container":frame.sample.container,"playback_profile":profile,
                            "media_fingerprint":frame.media_fingerprint
                        }),pin))
                        // Frame pixels and their private lease are dropped before sending metadata.
                    });
                    let _ = tx.send(CompareWorkEvent::MatchNativeSeekReady {
                        command,
                        generation,
                        result,
                    });
                } else {
                    let _ = tx.send(CompareWorkEvent::MatchInspectionReady {
                        command,
                        generation,
                        result,
                    });
                }
                repaint.request_repaint();
            });
            return true;
        }
        thread::spawn(move || {
            let result = service
                .lock()
                .map_err(|_| "service lock poisoned".to_string())
                .and_then(|mut service| service.match_video(&command.action_id, &request));
            let _ = tx.send(CompareWorkEvent::MatchVideoReady {
                command,
                generation,
                result,
            });
            repaint.request_repaint();
        });
        true
    }

    fn submit_match_video_ui(&mut self, request: api::MatchVideoRequest) {
        self.defer_match_action(move |app, ctx| {
            app.queue_background_match_video(
                ctx,
                ApiCommand {
                    action_id: format!("video-appearance-{}", uuid::Uuid::new_v4().simple()),
                    protocol_version: api::API_PROTOCOL_VERSION,
                    actor: Some("operator".into()),
                    issued_at: None,
                    command: CommandKind::MatchVideo(request),
                },
            );
        });
    }

    fn match_video_scope_is_current(&self, media_key: &str) -> bool {
        self.active_tab == Tab::Media
            && !self.media_explorer.chrome_hidden
            && self.match_video_ui.media_key == media_key
            && self.match_video_ui.tab_id == self.media_tabs.active_id().as_str()
            && self
                .media_selected_path(self.match_video_ui.lane_id)
                .is_some_and(|path| self.media_key(&path) == media_key)
    }

    fn clear_match_inspection(&mut self) {
        let seek_preparing = self.match_video_ui.appearance_seek_preparing;
        self.match_video_ui.appearance_seek_preparing = false;
        if let Some(cancelled) = self.match_video_ui.inspection_cancel.take() {
            cancelled.store(true, std::sync::atomic::Ordering::Release);
        }
        if seek_preparing
            || self.match_video_ui.inspection.is_some()
            || self.match_video_ui.inspection_pending
        {
            self.match_video_ui.generation = self.match_video_ui.generation.wrapping_add(1);
            self.match_video_ui.inspection = None;
            self.match_video_ui.inspection_pending = false;
        }
    }

    fn finish_match_inspection(
        &mut self,
        ctx: &egui::Context,
        command: ApiCommand,
        generation: u64,
        result: Result<crate::service::MatchInspectionFrame, String>,
    ) {
        self.match_video_ui.busy = false;
        self.match_video_ui.inspection_pending = false;
        self.match_video_ui.inspection_cancel = None;
        let result = result.and_then(|frame| {
            if generation != self.match_video_ui.generation
                || !self.match_video_scope_is_current(&frame.request.media_key)
                || self
                    .media_selected_path(self.match_video_ui.lane_id)
                    .as_deref()
                    != Some(frame.source_path.as_str())
            {
                return Err("inspection selection changed".into());
            }
            let image =
                image::load_from_memory_with_format(&frame.sample.encoded, image::ImageFormat::Pnm)
                    .map_err(|_| "inspection image decode failed")?
                    .to_rgba8();
            let size = [image.width() as usize, image.height() as usize];
            let texture = ctx.load_texture(
                "match-appearance-still",
                egui::ColorImage::from_rgba_unmultiplied(size, image.as_raw()),
                TextureOptions::LINEAR,
            );
            self.match_video_ui.selected_track = frame.request.track_id.clone().unwrap_or_default();
            self.match_video_ui.timestamp = frame.request.timestamp;
            self.match_video_ui.inspection = Some(MatchAppearanceStill {
                frame,
                texture,
                generation,
            });
            self.reconcile_video_surface();
            Ok(())
        });
        let ok = result.is_ok();
        let message = result
            .err()
            .unwrap_or_else(|| "Exact appearance inspected; native transport unchanged".into());
        self.match_video_ui.message = message.clone();
        self.finish_background_match_intent(command, ok, message, serde_json::Value::Null);
    }

    fn finish_match_video_request(
        &mut self,
        command: ApiCommand,
        generation: u64,
        result: Result<serde_json::Value, String>,
        source_pin: Option<Arc<crate::match_video_decode::PlaybackSourcePin>>,
    ) {
        use api::MatchVideoAction as Action;
        let CommandKind::MatchVideo(request) = &command.command else {
            return;
        };
        let current = generation == self.match_video_ui.generation
            && self.match_video_scope_is_current(&request.media_key);
        // A single request owns the busy flag, even if navigation invalidated its presentation.
        self.match_video_ui.busy = false;
        self.match_video_ui.appearance_seek_preparing = false;
        self.match_video_ui.inspection_cancel = None;
        let value = match result {
            Ok(value) => value,
            Err(error) => {
                if current {
                    self.match_video_ui.message = error.clone();
                    self.match_video_ui.preview = serde_json::Value::Null;
                }
                self.finish_background_match_intent(command, false, error, serde_json::Value::Null);
                return;
            }
        };
        if request.action == Action::SeekAppearance {
            let seek = verified_native_appearance_seek(request, &value);
            if !current || seek.is_err() {
                self.finish_background_match_intent(
                    command,
                    false,
                    seek.err()
                        .unwrap_or_else(|| "appearance seek scope changed".into()),
                    serde_json::Value::Null,
                );
                return;
            }
            let path = self
                .media_selected_path(self.match_video_ui.lane_id)
                .unwrap();
            let (profile, seek_ms) = seek.unwrap();
            let Some(source_pin) = source_pin else {
                self.finish_background_match_intent(
                    command,
                    false,
                    "native source pin missing".into(),
                    serde_json::Value::Null,
                );
                return;
            };
            // Retire the old native owner before its source pin can be replaced.
            self.video_player.stop();
            if let Err(error) = self.queue_media_video_start_with_profile(
                &path,
                VideoSurfaceOwner::Viewer,
                Some(profile),
            ) {
                self.finish_background_match_intent(command, false, error, serde_json::Value::Null);
                return;
            }
            self.video_player.set_appearance_source(source_pin);
            self.match_video_ui.busy = true;
            self.match_video_ui.pending_seek = Some((
                path,
                seek_ms,
                generation,
                std::time::Instant::now(),
                command,
                value,
            ));
            return;
        }
        if current {
            match request.action {
                Action::AppearanceList => {
                    self.match_video_ui.snapshot = value.clone();
                    self.match_video_ui.selected_track.clear();
                }
                Action::PersonAppearanceList => {
                    self.match_video_ui.person_appearances = value.clone();
                }
                Action::CorrectionPreview | Action::SplitPreview => {
                    self.match_video_ui.preview = value.clone();
                    self.match_video_ui.preview_request = Some(request.clone());
                }
                Action::ContextReview => self.match_video_ui.context = value.clone(),
                Action::CorrectionApply | Action::SplitApply => {
                    self.match_video_ui.preview = serde_json::Value::Null;
                    self.match_video_ui.preview_request = None;
                    self.match_video_ui.snapshot = serde_json::Value::Null;
                }
                _ => {}
            }
            self.match_video_ui.message = "Appearance request completed".into();
        }
        self.finish_background_match_intent(
            command,
            true,
            "Video appearance request completed".into(),
            value,
        );
    }

    fn poll_match_video_seek(&mut self) {
        if !self.match_video_scope_is_current(&self.match_video_ui.media_key) {
            self.clear_match_inspection();
        }
        if self
            .match_video_ui
            .inspection
            .as_ref()
            .is_some_and(|still| {
                still.generation != self.match_video_ui.generation
                    || still.frame.request.track_id.as_deref()
                        != Some(self.match_video_ui.selected_track.as_str())
                    || still.frame.request.timestamp != self.match_video_ui.timestamp
                    || !self.match_video_scope_is_current(&still.frame.request.media_key)
            })
        {
            self.match_video_ui.inspection = None;
        }
        let Some((path, time, generation, started, command, value)) =
            self.match_video_ui.pending_seek.take()
        else {
            return;
        };
        let CommandKind::MatchVideo(request) = &command.command else {
            return;
        };
        if generation != self.match_video_ui.generation
            || !self.match_video_scope_is_current(&request.media_key)
            || started.elapsed() > std::time::Duration::from_secs(10)
        {
            self.match_video_ui.busy = false;
            self.finish_background_match_intent(
                command,
                false,
                "appearance seek cancelled or playback preparation timed out".into(),
                serde_json::Value::Null,
            );
        } else if self.video_player.active_path() == Some(path.as_str())
            && self.media_pending_video_start.is_none()
        {
            self.match_video_ui.busy = false;
            let result = self.match_video_set_time(time);
            self.finish_background_match_intent(
                command,
                result.is_ok(),
                result
                    .err()
                    .unwrap_or_else(|| "Viewer seek requested for exact appearance".into()),
                value,
            );
        } else {
            self.match_video_ui.pending_seek =
                Some((path, time, generation, started, command, value));
        }
    }

    fn draw_match_person_appearances(
        &mut self,
        ui: &mut egui::Ui,
        lane_id: usize,
        base: &api::MatchVideoRequest,
    ) {
        if self.media_tabs.active().viewport.kind != crate::media_tabs::MediaTabKind::MatchPerson {
            return;
        }
        let request = api::MatchVideoRequest {
            action: api::MatchVideoAction::PersonAppearanceList,
            person_id: Some(self.media_tabs.active().viewport.match_person_id.clone()),
            ..base.clone()
        };
        if ui
            .add_enabled(
                !self.match_video_ui.busy,
                egui::Button::new("Load this Person's video appearances"),
            )
            .clicked()
        {
            self.submit_match_video_ui(request.clone());
        }
        let page = self.match_video_ui.person_appearances.clone();
        if let Some(rows) = page["rows"].as_array() {
            ui.label(format!("{} assigned appearances on this page", rows.len()));
            for row in rows.iter().take(64) {
                let path = row["source_path"].as_str();
                let label = format!(
                    "Seek {} · {} ms · {}",
                    path.and_then(|p| std::path::Path::new(p).file_name())
                        .map(|n| n.to_string_lossy())
                        .unwrap_or_default(),
                    row["seek_ms"],
                    row["observation_id"].as_str().unwrap_or_default()
                );
                if ui
                    .add_enabled(
                        !self.match_video_ui.busy && path.is_some(),
                        egui::Button::new(label),
                    )
                    .clicked()
                {
                    let Ok(time) = serde_json::from_value::<crate::match_video::VideoTime>(
                        row["timestamp"].clone(),
                    ) else {
                        continue;
                    };
                    let Some(key) = row["media_key"].as_str() else {
                        continue;
                    };
                    if self.media_select_paths(lane_id, &[path.unwrap().to_string()]) != 1 {
                        self.match_video_ui.message = "Appearance media is absent from this gallery; refresh the Person gallery before seeking.".into();
                        continue;
                    }
                    self.match_video_ui.media_key = key.to_string();
                    self.match_video_ui.generation = self.match_video_ui.generation.wrapping_add(1);
                    self.match_video_ui.snapshot = serde_json::Value::Null;
                    self.match_video_ui.preview = serde_json::Value::Null;
                    self.submit_match_video_ui(api::MatchVideoRequest {
                        action: api::MatchVideoAction::SeekAppearance,
                        media_key: key.to_string(),
                        track_id: row["track_id"].as_str().map(str::to_string),
                        track_revision: row["track_revision"].as_u64(),
                        timestamp: Some(time),
                        ..base.clone()
                    });
                    return;
                }
            }
        }
        // A bounded scan may produce an empty filtered page with a continuation.
        if page["has_more"].as_bool() == Some(true) {
            if let Ok(cursor) = serde_json::from_value(page["next_cursor"].clone()) {
                if ui
                    .add_enabled(
                        !self.match_video_ui.busy,
                        egui::Button::new("Next Person appearance page"),
                    )
                    .clicked()
                {
                    self.submit_match_video_ui(api::MatchVideoRequest {
                        person_cursor: Some(cursor),
                        ..request
                    });
                }
            }
        }
    }

    fn draw_match_video_metadata(&mut self, ui: &mut egui::Ui, lane_id: usize, media_key: &str) {
        use api::MatchVideoAction as Action;
        if self.match_video_ui.media_key != media_key
            || self.match_video_ui.tab_id != self.media_tabs.active_id().as_str()
        {
            // Pending operations keep their receipt ownership. Their completion
            // cannot retarget presentation to the newly selected media.
            self.match_video_ui.media_key = media_key.to_string();
            self.match_video_ui.generation = self.match_video_ui.generation.wrapping_add(1);
            self.match_video_ui.tab_id = self.media_tabs.active_id().as_str().to_string();
            self.match_video_ui.lane_id = lane_id;
            self.match_video_ui.snapshot = serde_json::Value::Null;
            self.match_video_ui.person_appearances = serde_json::Value::Null;
            self.match_video_ui.preview = serde_json::Value::Null;
            self.match_video_ui.selected_track.clear();
            self.match_video_ui.cluster_ids.clear();
            self.match_video_ui.cluster_review = serde_json::Value::Null;
            self.match_video_ui.context = serde_json::Value::Null;
        }
        ui.label(egui::RichText::new("Video appearances").strong());
        ui.label("Review exact track/timestamp rows. Playback has no face boxes.");
        if !self.match_video_ui.message.is_empty() {
            ui.label(&self.match_video_ui.message);
        }
        let request = api::MatchVideoRequest {
            action: Action::AppearanceList,
            after_track_id: None,
            person_id: None,
            person_cursor: None,
            media_key: media_key.to_string(),
            track_id: None,
            track_revision: None,
            timestamp: None,
            correction_action: None,
            source_person_id: None,
            target_person_id: None,
            split_observation_ids: Vec::new(),
            preview_token: None,
            confirmed: false,
        };
        self.draw_match_person_appearances(ui, lane_id, &request);
        if ui
            .add_enabled(
                !self.match_video_ui.busy,
                egui::Button::new("Load appearances"),
            )
            .clicked()
        {
            self.submit_match_video_ui(request.clone());
        }
        let tracks = self
            .match_video_ui
            .snapshot
            .get("tracks")
            .and_then(|v| v.as_array())
            .or_else(|| self.match_video_ui.snapshot.as_array())
            .cloned()
            .unwrap_or_default();
        for track in tracks.iter().take(256) {
            let id = track["track_id"].as_str().unwrap_or_default();
            let label = format!(
                "Track {id} · {} observations · {} exemplars",
                track["observation_count"], track["exemplar_count"]
            );
            if ui
                .add_enabled(
                    !self.match_video_ui.busy,
                    egui::SelectableLabel::new(self.match_video_ui.selected_track == id, label),
                )
                .clicked()
            {
                self.match_video_ui.selected_track = id.to_string();
                self.match_video_ui.timestamp = serde_json::from_value(track["start"].clone()).ok();
                self.match_video_ui.split_ids.clear();
                self.match_video_ui.cluster_ids.clear();
                self.match_video_ui.cluster_review = serde_json::Value::Null;
                self.match_video_ui.preview = serde_json::Value::Null;
                self.match_video_ui.preview_request = None;
                self.match_video_ui.context = serde_json::Value::Null;
            }
        }
        if self.match_video_ui.snapshot["has_more"].as_bool() == Some(true) {
            if let Some(cursor) = self.match_video_ui.snapshot["next_cursor"]
                .as_str()
                .map(str::to_string)
            {
                if ui
                    .add_enabled(
                        !self.match_video_ui.busy,
                        egui::Button::new("Next media appearance page"),
                    )
                    .clicked()
                {
                    self.submit_match_video_ui(api::MatchVideoRequest {
                        after_track_id: Some(cursor),
                        ..request.clone()
                    });
                }
            }
        }
        let Some(track) = tracks.iter().find(|track| {
            track["track_id"].as_str() == Some(self.match_video_ui.selected_track.as_str())
        }) else {
            return;
        };
        let observations = track["observations"]
            .as_array()
            .cloned()
            .unwrap_or_default();
        for row in observations.iter().take(1024) {
            let Some(id) = row["observation_id"].as_str() else {
                continue;
            };
            let Ok(time) =
                serde_json::from_value::<crate::match_video::VideoTime>(row["time"].clone())
            else {
                continue;
            };
            ui.horizontal_wrapped(|ui| {
                if ui
                    .add_enabled(
                        !self.match_video_ui.busy,
                        egui::SelectableLabel::new(
                            self.match_video_ui.timestamp == Some(time),
                            format!(
                                "{} ms · PTS {} ({}/{})",
                                time.milliseconds().unwrap_or(0),
                                time.pts,
                                time.numerator,
                                time.denominator
                            ),
                        ),
                    )
                    .clicked()
                {
                    self.match_video_ui.timestamp = Some(time);
                    self.match_video_ui.preview = serde_json::Value::Null;
                }
                let mut selected = self.match_video_ui.split_ids.contains(id);
                if let Some(face_id) = row["face_id"].as_str() {
                    let mut cluster_selected = self.match_video_ui.cluster_ids.contains(face_id);
                    let enabled = !self.match_video_ui.busy
                        && (cluster_selected || self.match_video_ui.cluster_ids.len() < 256);
                    if ui
                        .add_enabled(
                            enabled,
                            egui::Checkbox::new(&mut cluster_selected, "Cluster review member"),
                        )
                        .changed()
                    {
                        if cluster_selected {
                            self.match_video_ui.cluster_ids.insert(face_id.into());
                        } else {
                            self.match_video_ui.cluster_ids.remove(face_id);
                        }
                        self.match_video_ui.cluster_review = serde_json::Value::Null;
                    }
                }
                if ui
                    .add_enabled(
                        !self.match_video_ui.busy,
                        egui::Checkbox::new(&mut selected, "Split member"),
                    )
                    .changed()
                {
                    if selected {
                        self.match_video_ui.split_ids.insert(id.into());
                    } else {
                        self.match_video_ui.split_ids.remove(id);
                    }
                    self.match_video_ui.preview = serde_json::Value::Null;
                }
            });
        }
        let scoped = api::MatchVideoRequest {
            track_id: Some(self.match_video_ui.selected_track.clone()),
            track_revision: track["revision"].as_u64(),
            timestamp: self.match_video_ui.timestamp,
            ..request
        };
        ui.add_enabled_ui(!self.match_video_ui.busy, |ui| {
            if ui.button("Inspect exact appearance").clicked() {
                self.submit_match_video_ui(api::MatchVideoRequest {
                    action: Action::InspectAppearance,
                    ..scoped.clone()
                });
            }
            if ui.button("Seek to appearance").clicked() {
                self.submit_match_video_ui(api::MatchVideoRequest {
                    action: Action::SeekAppearance,
                    ..scoped.clone()
                });
            }
            ui.label("Track-wide correction — review the exact scope before applying.");
            egui::ComboBox::from_id_source("video-track-action")
                .selected_text(&self.match_video_ui.correction_action)
                .show_ui(ui, |ui| {
                    for (value, label) in [
                        ("assign", "Assign Person"),
                        ("reassign", "Reassign Person"),
                        ("remove", "Remove assignment"),
                        ("ignore", "Ignore track"),
                        ("not_a_person", "Not a person"),
                    ] {
                        if ui
                            .selectable_value(
                                &mut self.match_video_ui.correction_action,
                                value.to_string(),
                                label,
                            )
                            .changed()
                        {
                            self.match_video_ui.preview = serde_json::Value::Null;
                        }
                    }
                });
            ui.label("Source Person ID (reassign/remove)");
            if ui
                .text_edit_singleline(&mut self.match_video_ui.source_person)
                .changed()
            {
                self.match_video_ui.preview = serde_json::Value::Null;
            }
            ui.label("Target Person ID (assign/reassign)");
            if ui
                .text_edit_singleline(&mut self.match_video_ui.target_person)
                .changed()
            {
                self.match_video_ui.preview = serde_json::Value::Null;
            }
            if ui.button("Preview track correction").clicked() {
                self.submit_match_video_ui(api::MatchVideoRequest {
                    action: Action::CorrectionPreview,
                    correction_action: Some(self.match_video_ui.correction_action.clone()),
                    source_person_id: (matches!(
                        self.match_video_ui.correction_action.as_str(),
                        "reassign" | "remove"
                    ) && !self.match_video_ui.source_person.is_empty())
                    .then(|| self.match_video_ui.source_person.clone()),
                    target_person_id: (matches!(
                        self.match_video_ui.correction_action.as_str(),
                        "assign" | "reassign"
                    ) && !self.match_video_ui.target_person.is_empty())
                    .then(|| self.match_video_ui.target_person.clone()),
                    ..scoped.clone()
                });
            }
            if ui
                .add_enabled(
                    !self.match_video_ui.split_ids.is_empty(),
                    egui::Button::new("Preview contaminated-track split"),
                )
                .clicked()
            {
                self.submit_match_video_ui(api::MatchVideoRequest {
                    action: Action::SplitPreview,
                    split_observation_ids: self.match_video_ui.split_ids.iter().cloned().collect(),
                    ..scoped.clone()
                });
            }
            if !self.match_video_ui.preview.is_null() {
                ui.label(video_track_preview_label(&self.match_video_ui.preview));
                if let (Some(token), Some(mut apply)) = (
                    self.match_video_ui.preview["preview_id"]
                        .as_str()
                        .map(str::to_string),
                    self.match_video_ui.preview_request.clone(),
                ) {
                    let allowed = self
                        .match_video_ui
                        .preview
                        .get("batch")
                        .map(|batch| batch["within_limit"].as_bool() == Some(true))
                        .unwrap_or(true);
                    if ui
                        .add_enabled(allowed, egui::Button::new("Confirm exact preview"))
                        .clicked()
                    {
                        apply.action = if apply.action == Action::SplitPreview {
                            Action::SplitApply
                        } else {
                            Action::CorrectionApply
                        };
                        apply.confirmed = true;
                        apply.preview_token = Some(token);
                        self.submit_match_video_ui(apply);
                    }
                }
            }
            if ui.button("Review contextual ranking").clicked() {
                self.submit_match_video_ui(api::MatchVideoRequest {
                    action: Action::ContextReview,
                    ..scoped.clone()
                });
            }
        });
        ui.collapsing("Unnamed cluster review", |ui| {
            self.draw_match_cluster_review(ui)
        });
        ui.label(
            "Context changes review order only; it never assigns a Person or authorizes trust.",
        );
        if let Some(rows) = self
            .match_video_ui
            .context
            .get("ranked")
            .and_then(|v| v.as_array())
        {
            for row in rows.iter().take(32) {
                ui.label(format!(
                    "{} · visual {} · context {}",
                    row["person_id"], row["visual_score"], row["context_score"]
                ));
            }
        }
    }

    pub(crate) fn debug_match_cluster_review_fixture(&mut self, ui: &mut egui::Ui) -> bool {
        let saved = std::mem::take(&mut self.match_video_ui);
        self.match_video_ui
            .cluster_ids
            .insert("face-fixture".into());
        self.draw_match_cluster_review(ui);
        let no_request =
            !self.match_video_ui.busy && cluster_request_from_inputs(&self.match_video_ui).is_err();
        self.match_video_ui = saved;
        no_request
    }

    pub(crate) fn debug_match_video_metadata_fixture(&mut self, ui: &mut egui::Ui) -> bool {
        let saved = std::mem::take(&mut self.match_video_ui);
        let saved_viewport = self.media_tabs.active().viewport.clone();
        self.media_tabs.active_mut().viewport.kind = crate::media_tabs::MediaTabKind::MatchPerson;
        self.media_tabs.active_mut().viewport.match_person_id = "person-fixture".into();
        let time = crate::match_video::VideoTime {
            pts: 1500,
            numerator: 1,
            denominator: 1000,
        };
        let track = serde_json::json!({"track_id":"track-fixture", "revision":7,
            "observation_count":2,"exemplar_count":1,"start":time,"timestamps":[time],
            "observations":[{"observation_id":"observation-fixture","face_id":"face-fixture","time":time}]});
        self.match_video_ui = MatchVideoUiState {
            media_key: "video-fixture".into(),
            tab_id: self.media_tabs.active_id().as_str().into(),
            selected_track: "track-fixture".into(),
            timestamp: Some(time),
            snapshot: serde_json::json!({"tracks":[track.clone()],"has_more":true,"next_cursor":"track-fixture"}),
            person_appearances: serde_json::json!({
                "rows":[{"media_key":"video-fixture","media_fingerprint":"a".repeat(64),
                    "source_path":"appearance-fixture.mkv","track_id":"track-fixture","track_revision":7,
                    "observation_id":"observation-fixture","timestamp":time,
                    "playback_origin":{"pts":0,"numerator":1,"denominator":1000},"seek_ms":1500}],
                "has_more":true,"next_cursor":{"person_id":"person-fixture","person_revision":1,
                    "identity_revision":1,"catalog_revision":1,"after_assignment_id":"assignment-fixture"}
            }),
            correction_action: "assign".into(),
            preview: serde_json::json!({"track":track,"selected_observation_ids":["observation-fixture"]}),
            context: serde_json::json!({"ranked":[{"person_id":"person-fixture","visual_score":0.9,"context_score":0.1,"review_score":1.0}]}),
            ..Default::default()
        };
        self.draw_match_video_metadata(ui, 0, "video-fixture");
        let no_seek = self.match_video_ui.pending_seek.is_none() && !self.match_video_ui.busy;
        self.match_video_ui = saved;
        self.media_tabs.active_mut().viewport = saved_viewport;
        no_seek
    }

    fn queue_background_match_maintenance(
        &mut self,
        ctx: &egui::Context,
        command: ApiCommand,
    ) -> bool {
        if self.match_snapshot_loading {
            self.finish_background_match_intent(
                command,
                false,
                "match_operation_busy".to_string(),
                serde_json::Value::Null,
            );
            return true;
        }
        let request = match &command.command {
            CommandKind::MatchMaintenance(request) => request.clone(),
            _ => return false,
        };
        self.match_snapshot_loading = true;
        self.match_message = format!("{:?} in progress…", request.action);
        self.pending_match_model_intent = Some(command.action_id.clone());
        let service = Arc::clone(&self.service);
        let tx = self.compare_work_tx.clone();
        let repaint = ctx.clone();
        let work_command = command.clone();
        thread::spawn(move || {
            let result = service
                .lock()
                .map_err(|_| "Match service lock is poisoned".to_string())
                .and_then(|mut service| {
                    service.match_maintenance(&work_command.action_id, &request)
                });
            let _ = tx.send(CompareWorkEvent::MatchMaintenanceReady { command, result });
            repaint.request_repaint();
        });
        true
    }

    fn queue_background_match_correction(
        &mut self,
        ctx: &egui::Context,
        command: ApiCommand,
    ) -> bool {
        if !queued_match_correction_can_claim(
            self.queued_match_correction_intent.as_deref(),
            &command.action_id,
        ) {
            self.finish_background_match_intent(
                command,
                false,
                "match_correction_already_queued".to_string(),
                serde_json::Value::Null,
            );
            return true;
        }
        if self.match_snapshot_loading {
            if self.queued_match_correction_intent.as_deref() == Some(command.action_id.as_str()) {
                self.queued_match_correction_intent = None;
            }
            self.finish_background_match_intent(
                command,
                false,
                "match_operation_busy".to_string(),
                serde_json::Value::Null,
            );
            return true;
        }
        let correction = match &command.command {
            CommandKind::MatchCorrection(request) => request.clone(),
            _ => return false,
        };
        if self.queued_match_correction_intent.as_deref() == Some(command.action_id.as_str()) {
            self.queued_match_correction_intent = None;
        }
        self.match_snapshot_loading = true;
        self.match_message = format!("{:?} correction in progress…", correction.action);
        self.pending_match_model_intent = Some(command.action_id.clone());
        let service = Arc::clone(&self.service);
        let tx = self.compare_work_tx.clone();
        let repaint = ctx.clone();
        let current_media_key = self.match_viewer_snapshot_key.clone();
        thread::spawn(move || {
            let result = (|| -> Result<MatchCorrectionOutcome, String> {
                let mut service = service
                    .lock()
                    .map_err(|_| "Match service lock is poisoned".to_string())?;
                let result = service.match_apply_correction(&correction)?;
                let viewer_snapshot = current_media_key.as_ref().and_then(|media_key| {
                    service
                        .match_media_faces(media_key)
                        .ok()
                        .map(|snapshot| (media_key.clone(), snapshot))
                });
                let public_result = service.match_public_snapshot().unwrap_or_else(|_| {
                    serde_json::json!({
                        "availability": "snapshot_failed",
                        "error_code": "match_public_snapshot_unavailable"
                    })
                });
                let operation_id = result
                    .get("operation_id")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or("none");
                Ok(MatchCorrectionOutcome {
                    message: format!(
                        "{:?} applied; operation_id={operation_id}",
                        correction.action
                    ),
                    result,
                    public_result,
                    viewer_snapshot,
                })
            })();
            let _ = tx.send(CompareWorkEvent::MatchCorrectionReady { command, result });
            repaint.request_repaint();
        });
        true
    }

    fn queue_background_match_split_person_preflight(
        &mut self,
        ctx: &egui::Context,
        command: ApiCommand,
    ) -> bool {
        if self.match_snapshot_loading {
            self.finish_background_match_intent(
                command,
                false,
                "match_operation_busy".to_string(),
                serde_json::Value::Null,
            );
            return true;
        }
        let preflight = match &command.command {
            CommandKind::MatchSplitPersonPreflight(request) => request.clone(),
            _ => return false,
        };
        self.match_snapshot_loading = true;
        self.match_message = "Exact split Person preflight in progress…".to_string();
        self.pending_match_model_intent = Some(command.action_id.clone());
        let service = Arc::clone(&self.service);
        let tx = self.compare_work_tx.clone();
        let repaint = ctx.clone();
        thread::spawn(move || {
            let result = service
                .lock()
                .map_err(|_| "Match service lock is poisoned".to_string())
                .and_then(|service| service.match_split_person_preflight(&preflight));
            let _ = tx
                .send(CompareWorkEvent::MatchSplitPersonPreflightCommandReady { command, result });
            repaint.request_repaint();
        });
        true
    }

