    #[test]
    fn match_navigation_offsets_are_action_scoped_and_receipt_applied() {
        assert_eq!(match_query_offset("open_person", None, 768, 400), 0);
        assert_eq!(match_query_offset("open_settings", None, 768, 0), 0);
        assert_eq!(match_query_offset("open_settings", Some(200), 768, 0), 200);
        assert_eq!(match_query_offset("open_people", None, 768, 400), 768);

        let people = serde_json::json!({ "catalog": { "offset": 512, "limit": 256 } });
        let people_receipt =
            match_navigation_receipt("open_people", Some(512), Some(&people), None, None).unwrap();
        assert_eq!(people_receipt["requested_offset"], 512);
        assert_eq!(people_receipt["applied_offset"], 512);
        assert_eq!(people_receipt["page_limit"], 256);

        let settings = serde_json::json!({ "page": { "offset": 0, "limit": 200 } });
        let settings_receipt =
            match_navigation_receipt("open_settings", None, None, Some(&settings), None).unwrap();
        assert_eq!(settings_receipt["requested_offset"], 0);
        assert_eq!(settings_receipt["applied_offset"], 0);
        assert_eq!(settings_receipt["page_limit"], 200);

        let unpaged =
            match_navigation_receipt("open_suggestions", None, Some(&people), None, None).unwrap();
        assert_eq!(unpaged, serde_json::json!({ "action": "open_suggestions" }));
        assert!(match_navigation_receipt("refresh", None, Some(&people), None, None).is_none());
    }

    /// WP-065 single-writer invariant for the native video child.
    ///
    /// There is one LibVLC child window and several draw sites that would like
    /// to place it. When each site called `show_clipped`/`hide` directly while
    /// painting, the last one to paint won — a frame could move the child, hide
    /// it, and move it again, which is what left the previous video smeared
    /// across the app. Draw sites now only record a claim.
    ///
    /// A behavioural test cannot cover this headlessly: without LibVLC loaded
    /// there is no child window to place, so the draw sites never reach the
    /// placement call at all. The defect is structural — an added draw site
    /// that pokes the window directly — so the guard is structural too.
    #[test]
    fn only_the_reconciler_moves_the_native_video_surface() {
        let source = include_str!("ui.rs");
        // The needles are assembled at runtime so this test's own text is not
        // one of the call sites it counts.
        let place = format!(".{}(", "show_clipped");
        let hide = format!(".video_player.{}()", "hide");
        let placements = source.matches(place.as_str()).count();
        let hides = source.matches(hide.as_str()).count();
        assert_eq!(
            placements, 1,
            "the native video surface is placed from {placements} sites; \
             all placement must go through FacialApp::reconcile_video_surface, \
             or two draw sites will fight over one window within a frame (WP-065)"
        );
        assert_eq!(
            hides, 1,
            "the native video surface is hidden from {hides} sites; a draw-time \
             hide races the reconciler's show and strands the picture (WP-065)"
        );
        assert!(
            source.contains("fn reconcile_video_surface"),
            "the reconciler this invariant depends on is gone"
        );
    }

    #[test]
    fn video_commands_defer_decoder_start_until_the_surface_reconciler() {
        let source = include_str!("ui.rs");
        let selected_anchor = source
            .find("let selected_video = selected")
            .expect("selected video resolution");
        let command_start = source[..selected_anchor]
            .rfind("CommandKind::MediaVideoControl")
            .expect("media video command handler");
        let command_end = source[selected_anchor..]
            .find("CommandKind::MediaLabelMutation")
            .map(|offset| selected_anchor + offset)
            .expect("next command handler");
        let command = &source[command_start..command_end];
        assert!(command.contains("queue_media_video_start"));
        assert!(!command.contains("play_media_video_clipped"));

        let reconciler_start = source
            .find("fn reconcile_video_surface")
            .expect("surface reconciler");
        let reconciler = &source[reconciler_start..];
        assert!(reconciler.contains("play_media_video_clipped"));
    }

    #[test]
    fn delete_display_remap_drops_removed_rows_and_keeps_survivor_order() {
        let files: Vec<String> = ["a.jpg", "b.jpg", "c.jpg", "d.jpg"]
            .iter()
            .map(|name| name.to_string())
            .collect();
        // Display order deliberately differs from file order (a sort/query).
        let display = vec![3usize, 1, 0, 2];
        let removed: HashSet<String> = ["b.jpg".to_string(), "d.jpg".to_string()]
            .into_iter()
            .collect();
        // Survivors are a (new 0) and c (new 1); display keeps their relative
        // order (a before c, as in the old display).
        assert_eq!(
            remap_display_after_removal(&files, &display, &removed),
            vec![0, 1]
        );
        // Removing the display's first file only shifts later indices.
        let removed_first: HashSet<String> = ["a.jpg".to_string()].into_iter().collect();
        assert_eq!(
            remap_display_after_removal(&files, &display, &removed_first),
            vec![2, 0, 1]
        );
        // Nothing removed: identity. Everything removed: empty, never a panic.
        assert_eq!(
            remap_display_after_removal(&files, &display, &HashSet::new()),
            display
        );
        let all: HashSet<String> = files.iter().cloned().collect();
        assert!(remap_display_after_removal(&files, &display, &all).is_empty());
        // A stale out-of-range display index is dropped, not a panic.
        assert_eq!(
            remap_display_after_removal(&files, &[9usize, 0], &HashSet::new()),
            vec![0]
        );
    }

    /// WP-074 structural guard: destination-directed filing must resolve the
    /// canonical selection, never the rendered display slice. A sheet or
    /// filtered view shows a subset, and filing the subset silently loses
    /// files (GLOBAL-SOT-027/031).
    #[test]
    fn destination_jobs_resolve_the_canonical_selection() {
        let source = include_str!("ui.rs");
        // Runtime-assembled needles keep this test out of its own search space.
        let request_needle = format!("fn request_media_{}", "destination");
        let runner_needle = format!("fn run_media_destination_{}", "job");
        let start = source
            .find(&request_needle)
            .expect("destination request fn");
        let end = source[start..]
            .find(&runner_needle)
            .map(|offset| start + offset)
            .expect("destination runner fn");
        let body = &source[start..end];
        assert!(
            body.contains("media_selected_paths"),
            "the destination request must read the canonical selection"
        );
        assert!(
            !body.contains("display"),
            "the destination request must never consume the rendered display slice"
        );
        // The armed job carries its own sources, so a selection change while
        // the picker is open cannot retarget it.
        assert!(source.contains("struct MediaDestinationJob"));
        assert!(source.contains("sources: Vec<String>"));
    }

    /// WP-074: a destination pick must not reach the lane-folder sink that
    /// changes the tab's folder and rescans.
    #[test]
    fn destination_picks_never_change_the_lane_folder() {
        let source = include_str!("ui.rs");
        // Needles are assembled at runtime so this test's own text is not the
        // region it inspects (the WP-065 guard uses the same technique).
        let sink_needle = format!("if let PickerEvent::{} {{", "Picked");
        let start = source.find(&sink_needle).expect("picker sink");
        let end = source[start..]
            .find("reconcile_video_surface")
            .map(|offset| start + offset)
            .expect("frame tail");
        let sink = &source[start..end];
        let move_needle = format!("{}Destination", "Move");
        let lane_needle = format!("{}Folder", "Lane");
        let destination_arm = sink
            .find(&move_needle)
            .and_then(|begin| sink[begin..].find(&lane_needle).map(|off| begin + off))
            .expect("destination arm precedes the lane arm");
        assert!(
            !sink[..destination_arm].contains("start_compare_scan"),
            "a destination pick must not start a scan"
        );
        assert!(
            !sink[..destination_arm].contains(".folder ="),
            "a destination pick must not assign a lane folder"
        );
    }

    /// WP-075 structural guard: the receiving pane must never write the
    /// singleton grid state. Cursor, scroll, columns, and search belong to the
    /// one Library grid; a second surface touching them makes the left grid
    /// jump while the operator drags into the right one.
    #[test]
    fn the_receiving_pane_never_writes_singleton_grid_state() {
        let source = include_str!("ui.rs");
        let start_needle = format!("fn draw_media_receiving_{}", "pane");
        let end_needle = format!("fn paint_media_tile_{}", "readonly");
        let start = source.find(&start_needle).expect("receiving pane fn");
        let end = source[start..]
            .find(&end_needle)
            .map(|offset| start + offset)
            .expect("pane tile fn");
        let body = &source[start..end];
        for forbidden in [
            "media_explorer.cursor",
            "media_explorer.last_grid_columns",
            "media_explorer.last_scroll_top",
            "media_scroll_to_cursor",
            "media_search_query",
            "start_compare_scan",
            "activate_media_tab",
        ] {
            assert!(
                !body.contains(forbidden),
                "the receiving pane must not touch {forbidden}: it is owned by the Library grid"
            );
        }
    }

    /// WP-075: a drop must be validated against the destination pinned at drag
    /// start, so a pane rebind or tab close mid-drag cannot misfile.
    #[test]
    fn drops_revalidate_the_pinned_destination() {
        let source = include_str!("ui.rs");
        let start_needle = format!("fn finish_media_{}", "drop");
        let end_needle = format!("fn draw_media_receiving_{}", "pane");
        let start = source.find(&start_needle).expect("drop handler");
        let end = source[start..]
            .find(&end_needle)
            .map(|offset| start + offset)
            .expect("pane fn");
        let body = &source[start..end];
        assert!(
            body.contains("still_bound") && body.contains("same_folder"),
            "the drop handler must revalidate both the bound tab and its folder"
        );
        assert!(
            body.contains("Drop cancelled"),
            "a stale drop must be rejected with a stated reason, not silently filed"
        );
        // The payload struct pins both halves of the destination.
        assert!(source.contains("target_tab: String"));
        assert!(source.contains("target_folder: String"));
    }

